	if !eq(names(ents), []string{"rc"}) {
		t.Errorf("after MREPL /bin should hold only rc, got %v", names(ents))
	}
	if _, err := n.Stat("/bin/ls"); err != ninep.ErrNotExist {
		t.Errorf("replaced file still reachable: %v", err)
	}
}

