}

func TestErrors(t *testing.T) {
	tr := New("dev", "sys", nil)
	tr.Root().Add("null", func() string { return "" })

	if _, err := tr.Root().Read(0, -1); err != ninep.ErrIsDir {
		t.Errorf("read a directory: got %v", err)
	}
	if _, err := tr.Root().Walk("absent"); err != ninep.ErrNotExist {
		t.Errorf("walk missing: got %v", err)
	}
	if _, err := tr.Root().Walk("a/b"); err != ninep.ErrBadName {
		t.Errorf("walk bad name: got %v", err)
	}
	f, _ := tr.Root().Walk("null")
	if _, err := f.Walk("x"); err != ninep.ErrNotDir {
		t.Errorf("walk through a file: got %v", err)
	}
	if _, err := f.ReadDir(); err != ninep.ErrNotDir {
		t.Errorf("readdir a file: got %v", err)
	}
}

func TestSyntheticTreeIsReadOnly(t *testing.T) {
	// The whole point: a synthetic tree implements File and NOT Mutable, so
	// it is safe to hand to a namespace owned by somebody else.
	tr := New("dev", "sys", nil)
	var f ninep.File = tr.Root()
	if _, ok := f.(ninep.Mutable); ok {
		t.Error("a synthetic tree must not be Mutable")
	}
}

// Package crew is small-group coordination as a product rather than as a
// framework: three to fifteen people with a shared pot, a way to decide, and a
// way to leave with their share.
//
// # Why not a DAO framework
//
// A framework asks you to pick a governance module, a voting strategy and a
// treasury adapter before anybody has put in a single ugnot. The targets here
// are real and already exist: a validator set, a working group, a hackathon
// team, a five-person company. They want the thing you can create in one
// transaction. [gno.land/p/moul/grants] and daokit are the framework layer, and
// this package is deliberately underneath them: one call to open a crew, one to
// join it, one to leave with what your shares are worth.
//
// # The model
//
//	Crews     every crew, plus the credit ledger every payout goes through
//	Crew      a name, a creation height, members with shares, a treasury, proposals
//	Proposal  advisory text with a deadline and a share-weighted tally
//
// Shares are the whole design. They are the vote weight and the claim on the
// treasury at the same time, minted by [Crews.Join] and burned by
// [Crews.Ragequit], so leaving is priced by the same number that decides. There
// is no separate token to issue, distribute or forget to make meaningful.
//
// # Rounding, which is the part that has to be right
//
// Every division here rounds DOWN, and both of them therefore round in the
// crew's favour:
//
//   - joining mints amount * totalShares / treasury, so a late joiner buys
//     exactly what they paid for at the CURRENT per-share value and never a
//     share more. Rounding up would hand them a sliver of value the existing
//     members built, which is the whole reason a flat price is wrong here.
//   - ragequitting credits shares * treasury / totalShares, so a leaver takes
//     no more than their slice and the remainder stays with the people who
//     stayed.
//
// The dust that accrues from both is never stranded: the last member to
// ragequit holds every outstanding share, so their MulDiv is exact and the
// treasury empties to the last ugnot. [Crews.Ragequit] has a test for that.
//
// # What v0 deliberately does not do
//
// A proposal is advisory text. Passing one executes nothing, moves nothing and
// binds nothing; it records that the crew agreed by share weight at a point in
// time. Executing a payout is the obvious next step and the one that turns this
// into a treasury contract rather than a notice board.
//
// A vote is weighed at the moment it is cast. A member who votes and then
// ragequits leaves their weight behind in the tally, because unwinding it would
// mean re-weighing every ballot on every share change.
//
// # Errors, not aborts
//
// This is a p/, so it returns errors and declares no crossing function: the
// caller, the height and the amount all arrive as plain arguments and the realm
// that wires it to the chain decides what to abort on.
package crew

import (
	"chain/markdown"
	"errors"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/xmath/v1"
)

const (
	// MaxMembers is the upper end of "three to fifteen people". It is a
	// product constraint and not a technical one: above it the share math
	// still works and the thing stops being a crew.
	MaxMembers = 15

	// InitialPricePerShare is what a share costs in ugnot before the crew
	// has a treasury to price against: at creation, and again if every
	// member has left. 1000 ugnot makes 1 GNOT worth 1000 shares, which
	// keeps the integer arithmetic far away from both zero and overflow.
	InitialPricePerShare = int64(1000)

	// VoteBlocks is how long a proposal stays open, in blocks.
	VoteBlocks = int64(1000)

	// MaxNameLen and MaxTextLen bound what one call can make the crew's
	// members pay a storage deposit on.
	MaxNameLen = 60
	MaxTextLen = 500

	// ExcerptLen is how much of a proposal a listing shows.
	ExcerptLen = 60
)

// maxInt64 is the largest int64, spelled out because the overflow guards
// compare against it directly.
const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back.
var (
	ErrBadName     = errors.New("crew: name is empty, too long, or has control characters")
	ErrBadText     = errors.New("crew: text is empty, too long, or has control characters")
	ErrBadAmount   = errors.New("crew: amount must be positive")
	ErrNoCrew      = errors.New("crew: no such crew")
	ErrNoProposal  = errors.New("crew: no such proposal")
	ErrNotMember   = errors.New("crew: not a member of this crew")
	ErrIsMember    = errors.New("crew: already a member of this crew")
	ErrFull        = errors.New("crew: the crew is full")
	ErrNoShares    = errors.New("crew: the amount sent buys no whole share")
	ErrVoteClosed  = errors.New("crew: the proposal is no longer open")
	ErrVoteOpen    = errors.New("crew: the proposal is still open")
	ErrNothing     = errors.New("crew: nothing to withdraw")
	ErrWouldExceed = errors.New("crew: the amount would overflow the ledger")
)

// Crew is one group: who is in it, what it holds, and what it is deciding.
type Crew struct {
	Name      string
	CreatedAt int64 // block height
	Treasury  int64 // ugnot, accounted here and held at the realm's address

	// TotalShares is every share outstanding. It is the denominator of both
	// the join price and the ragequit payout, so it is maintained here
	// rather than summed over the members on demand.
	TotalShares int64

	shares    map[string]int64 // address -> shares held
	order     []address        // members in join order, so output never iterates a map
	proposals []store.ID
}

// SharesOf is how many shares who holds, zero when they hold none.
func (c *Crew) SharesOf(who address) int64 {
	if c == nil {
		return 0
	}
	return c.shares[who.String()]
}

// IsMember reports whether who holds any share.
func (c *Crew) IsMember(who address) bool { return c.SharesOf(who) > 0 }

// MemberCount is how many addresses hold shares.
func (c *Crew) MemberCount() int {
	if c == nil {
		return 0
	}
	return len(c.order)
}

// Members returns the members in join order. The slice is a copy, so a caller
// rendering it cannot reorder the crew.
func (c *Crew) Members() []address {
	if c == nil {
		return nil
	}
	out := make([]address, len(c.order))
	copy(out, c.order)
	return out
}

// Proposals returns this crew's proposal ids, oldest first, as a copy.
func (c *Crew) Proposals() []store.ID {
	if c == nil {
		return nil
	}
	out := make([]store.ID, len(c.proposals))
	copy(out, c.proposals)
	return out
}

// ValuePerShare is what one share is worth in ugnot right now, rounded down.
//
// It is a display figure and nothing computes against it: [Crews.Join] and
// [Crews.Ragequit] divide by the real totals, so a crew whose treasury is
// smaller than its share count still prices both correctly while this reads 0.
func (c *Crew) ValuePerShare() int64 {
	if c == nil || c.TotalShares == 0 {
		return 0
	}
	return c.Treasury / c.TotalShares
}

// PricePerShare is what the next share costs a joiner, rounded down, which is
// [Crew.ValuePerShare] except on a crew nobody holds a share in.
func (c *Crew) PricePerShare() int64 {
	if c == nil || c.TotalShares == 0 || c.Treasury == 0 {
		return InitialPricePerShare
	}
	return c.Treasury / c.TotalShares
}

// ballot is one member's vote: which way, and what it weighed when cast.
type ballot struct {
	yes    bool
	weight int64
}

// Proposal is a question put to a crew. v0 proposals are advisory text and
// execute nothing: see the package doc.
type Proposal struct {
	CrewID   store.ID
	Author   address
	Text     string
	OpenedAt int64
	Deadline int64 // OpenedAt + VoteBlocks, exclusive

	// Yes and No are the running share-weighted tally, maintained on every
	// vote so reading it never walks the ballots.
	Yes int64
	No  int64

	Closed bool
	Passed bool

	votes map[string]ballot
}

// Open reports whether the proposal still accepts votes at height now.
func (p *Proposal) Open(now int64) bool {
	return p != nil && !p.Closed && now < p.Deadline
}

// VoteOf reports how who voted and what it weighed, and whether they voted at
// all.
func (p *Proposal) VoteOf(who address) (yes bool, weight int64, voted bool) {
	if p == nil {
		return false, 0, false
	}
	b, ok := p.votes[who.String()]
	return b.yes, b.weight, ok
}

// Voters is how many members have cast a ballot.
func (p *Proposal) Voters() int {
	if p == nil {
		return 0
	}
	return len(p.votes)
}

// Crews holds every crew, every proposal, and the credit ledger each payout
// goes through.
type Crews struct {
	crews *store.Store
	props *store.Store

	credit map[string]int64 // address -> ugnot owed
	owed   int64            // the sum of the above, which the holder must reserve
}

// New returns an empty Crews.
func New() *Crews {
	return &Crews{
		crews:  store.Named("crew"),
		props:  store.Named("proposal"),
		credit: map[string]int64{},
	}
}

// Create opens a crew with founder as its only member, their shares bought out
// of amount at [InitialPricePerShare].
//
// The remainder below one whole share stays in the treasury rather than being
// refunded, which is the same direction every other division here rounds.
func (cs *Crews) Create(name string, founder address, amount, at int64) (store.ID, error) {
	if !ValidName(name) {
		return 0, ErrBadName
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	shares := amount / InitialPricePerShare
	if shares < 1 {
		return 0, ErrNoShares
	}
	c := &Crew{
		Name:        name,
		CreatedAt:   at,
		Treasury:    amount,
		TotalShares: shares,
		shares:      map[string]int64{founder.String(): shares},
		order:       []address{founder},
	}
	return cs.crews.Add(c), nil
}

// Join mints who shares at the crew's CURRENT per-share value and adds amount
// to its treasury.
//
// amount * totalShares / treasury, rounded down. That is the whole anti-dilution
// rule: a crew that turned 10 GNOT into 20 sells the next share for what a share
// is worth now, not for what the founders paid, and the rounding remainder stays
// with the crew rather than with the joiner.
func (cs *Crews) Join(id store.ID, who address, amount int64) (int64, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	if c.IsMember(who) {
		return 0, ErrIsMember
	}
	if len(c.order) >= MaxMembers {
		return 0, ErrFull
	}
	if c.Treasury > maxInt64-amount {
		return 0, ErrWouldExceed
	}

	var shares int64
	if c.TotalShares == 0 || c.Treasury == 0 {
		// Nobody holds a share, so there is no value to price against and
		// the crew is back at its opening price.
		shares = amount / InitialPricePerShare
	} else {
		shares = xmath.MulDiv(amount, c.TotalShares, c.Treasury)
	}
	if shares < 1 {
		return 0, ErrNoShares
	}
	if c.TotalShares > maxInt64-shares {
		return 0, ErrWouldExceed
	}

	c.shares[who.String()] = shares
	c.order = append(c.order, who)
	c.TotalShares += shares
	c.Treasury += amount
	return shares, nil
}

// Fund adds amount to a crew's treasury and mints nothing.
//
// It is what makes the join price mean anything: a crew whose treasury only
// ever moves with its share count prices every joiner identically forever, and
// the anti-dilution rule in [Crews.Join] would be decorative. Revenue, a grant
// and a member topping the pot up all arrive this way, and every existing share
// is worth more afterwards.
func (cs *Crews) Fund(id store.ID, amount int64) error {
	c, ok := cs.Get(id)
	if !ok {
		return ErrNoCrew
	}
	if amount <= 0 {
		return ErrBadAmount
	}
	if c.Treasury > maxInt64-amount {
		return ErrWouldExceed
	}
	c.Treasury += amount
	return nil
}

// Propose opens an advisory question, open for [VoteBlocks] blocks. Any member
// may propose.
func (cs *Crews) Propose(id store.ID, who address, text string, at int64) (store.ID, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if !c.IsMember(who) {
		return 0, ErrNotMember
	}
	if !ValidText(text) {
		return 0, ErrBadText
	}
	p := &Proposal{
		CrewID:   id,
		Author:   who,
		Text:     text,
		OpenedAt: at,
		Deadline: at + VoteBlocks,
		votes:    map[string]ballot{},
	}
	pid := cs.props.Add(p)
	c.proposals = append(c.proposals, pid)
	return pid, nil
}

// Vote records who's ballot, weighted by the shares they hold right now.
//
// One ballot per member, changeable while the proposal is open: a second call
// replaces the first, tally and weight both, so changing your mind after buying
// more shares counts the shares you now hold.
func (cs *Crews) Vote(pid store.ID, who address, yes bool, at int64) error {
	p, ok := cs.Proposal(pid)
	if !ok {
		return ErrNoProposal
	}
	if !p.Open(at) {
		return ErrVoteClosed
	}
	c, ok := cs.Get(p.CrewID)
	if !ok {
		return ErrNoCrew
	}
	weight := c.SharesOf(who)
	if weight <= 0 {
		return ErrNotMember
	}

	key := who.String()
	if prev, voted := p.votes[key]; voted {
		if prev.yes {
			p.Yes -= prev.weight
		} else {
			p.No -= prev.weight
		}
	}
	p.votes[key] = ballot{yes: yes, weight: weight}
	if yes {
		p.Yes += weight
	} else {
		p.No += weight
	}
	return nil
}

// Close records a proposal as passed or failed by share weight, once its
// deadline has gone by. Anyone may call it: closing is bookkeeping, not
// authority, and a proposal nobody closes is simply never recorded.
//
// A tie fails. There is no quorum in v0: a crew where one member votes and the
// rest ignore it passes the proposal, which is exactly as advisory as the text
// it carries.
func (cs *Crews) Close(pid store.ID, at int64) (bool, error) {
	p, ok := cs.Proposal(pid)
	if !ok {
		return false, ErrNoProposal
	}
	if p.Closed {
		return p.Passed, ErrVoteClosed
	}
	if at < p.Deadline {
		return false, ErrVoteOpen
	}
	p.Closed = true
	p.Passed = p.Yes > p.No
	return p.Passed, nil
}

// Ragequit burns every share who holds, credits them their pro-rata slice of
// the treasury and removes them from the crew.
//
// shares * treasury / totalShares, rounded down, so the remainder stays with
// the members who stayed. This is what makes a share mean something: the exit
// is priced by the same number that votes, and nobody has to agree to let you
// out.
//
// The payout is credited, never sent. The caller moves the coins after this
// returns, which is the ordering the pull-payment pattern exists for.
func (cs *Crews) Ragequit(id store.ID, who address) (shares, amount int64, err error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, 0, ErrNoCrew
	}
	shares = c.SharesOf(who)
	if shares <= 0 {
		return 0, 0, ErrNotMember
	}

	amount = xmath.MulDiv(shares, c.Treasury, c.TotalShares)
	c.TotalShares -= shares
	c.Treasury -= amount
	delete(c.shares, who.String())
	c.order = dropAddress(c.order, who)

	if amount > 0 {
		if err := cs.credits(who, amount); err != nil {
			return 0, 0, err
		}
	}
	return shares, amount, nil
}

// credits adds to an address's withdrawable balance.
func (cs *Crews) credits(who address, amount int64) error {
	key := who.String()
	if cs.credit[key] > maxInt64-amount || cs.owed > maxInt64-amount {
		return ErrWouldExceed
	}
	cs.credit[key] += amount
	cs.owed += amount
	return nil
}

// Withdraw zeroes who's credit and returns what they were owed.
//
// The balance is gone from the ledger before this returns, so the caller can
// move the coins afterwards and a reentrant call finds nothing: effects, then
// interactions.
func (cs *Crews) Withdraw(who address) (int64, error) {
	key := who.String()
	amount, ok := cs.credit[key]
	if !ok || amount == 0 {
		return 0, ErrNothing
	}
	delete(cs.credit, key)
	cs.owed -= amount
	return amount, nil
}

// CreditOf is what who can withdraw right now.
func (cs *Crews) CreditOf(who address) int64 { return cs.credit[who.String()] }

// TotalOwed is the sum of every outstanding credit, which is what the holding
// realm must keep in reserve on top of every crew's treasury.
func (cs *Crews) TotalOwed() int64 { return cs.owed }

// Get returns a crew by id.
func (cs *Crews) Get(id store.ID) (*Crew, bool) {
	v, ok := cs.crews.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Crew), true
}

// Proposal returns a proposal by id.
func (cs *Crews) Proposal(pid store.ID) (*Proposal, bool) {
	v, ok := cs.props.Get(pid)
	if !ok {
		return nil, false
	}
	return v.(*Proposal), true
}

// Len is how many crews exist.
func (cs *Crews) Len() int { return cs.crews.Len() }

// ProposalCount is how many proposals exist, across every crew.
func (cs *Crews) ProposalCount() int { return cs.props.Len() }

// Listing is one row of [Crews.List]: the crew and the id a link needs.
type Listing struct {
	ID   store.ID
	Crew *Crew
}

// List returns up to limit crews, newest first. limit below 1 returns nothing.
func (cs *Crews) List(limit int) []Listing {
	var out []Listing
	for _, e := range cs.crews.PageReverse(1, limit) {
		out = append(out, Listing{ID: e.ID, Crew: e.Value.(*Crew)})
	}
	return out
}

// ValidName reports whether name can be stored: non-empty after the render's
// own stripping and trimming,
// within [MaxNameLen], free of control characters including newlines, and
// free of the pipe character.
//
// The pipe is the one restriction that is not obvious, and it is here because
// a name is rendered as the TITLE of a link inside a table cell. md.Link
// escapes its title with the inline-text escaper, which deliberately leaves
// "|" alone because a pipe is markdown-inert outside a table, and wrapping the
// title in ui.Cell on top of that would double-escape and render the
// backslashes. Refusing the character at write time is the only place left
// where the fix is one rule rather than one exception per call site.
//
// A proposal's text has no such restriction: [ValidText] allows a pipe and the
// render escapes it with ui.Cell, because free prose legitimately contains one
// and a name does not.
func ValidName(name string) bool {
	if len(name) > MaxNameLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(name)) == "" {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		if c < 0x20 || c == 0x7f || c == '|' {
			return false
		}
	}
	return true
}

// ValidText reports whether a proposal body can be stored: non-empty after
// the render's own stripping and trimming, within [MaxTextLen], and free of control characters other than
// newline and tab.
//
// Control characters are refused rather than stripped because the text is shown
// back to its author, and silently rewriting what somebody wrote is worse than
// telling them it was refused. Everything else is allowed and escaped at render
// time: a validator and an escaper protect against different mistakes.
func ValidText(text string) bool {
	if len(text) > MaxTextLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(text)) == "" {
		return false
	}
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// dropAddress returns addrs without who, in a freshly allocated slice.
//
// It allocates rather than shortening in place: a slice is one persisted object
// and the storage deposit only comes back when that object is dropped, so
// append(s[:i], s[i+1:]...) would keep the peak allocation charged forever.
func dropAddress(addrs []address, who address) []address {
	out := make([]address, 0, len(addrs))
	for _, a := range addrs {
		if a != who {
			out = append(out, a)
		}
	}
	return out
}

package crew

import "testing"

// Finding 325-input-validation-1 (review run 001-cd0b6a9).
//
// A validator that calls a field required must agree with the escaper its own
// render runs. strings.TrimSpace uses unicode.IsSpace, which does NOT include
// U+200B and the rest of the bidi and zero-width set, while every escaper on
// the output side runs chain/markdown.StripBidiAndZeroWidth, which does. So a
// value made only of those characters passes validation and renders as
// nothing: a required field that is blank on the page.
//
// The cases below are the invariant, not the implementation. A value the
// validator accepts must still be non-empty after the stripper.
func TestValidatorsAgreeWithTheEscaper(t *testing.T) {
	// One per class the stripper removes, so a fix that handles only
	// U+200B does not pass.
	blank := []string{
		"\u200b\u200b\u200b",   // ZWSP
		"\u200d",                // ZWJ
		"\u200e",                // LRM
		"\u202e",                // RLO
		"\u2066\u2069",          // LRI PDI
		"\ufeff",                // BOM
		" \u200b \u200b ",        // mixed with real spaces
	}
	// These must stay valid: the stripper removes the marks and leaves text.
	ok := []string{
		"a",
		"a\u200bb",
		"  padded  ",
	}

	for _, s := range blank {
		if ValidName(s) {
			t.Errorf("ValidName(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidName(s) {
			t.Errorf("ValidName(%q) is false, but it renders as real text", s)
		}
	}

	for _, s := range blank {
		if ValidText(s) {
			t.Errorf("ValidText(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidText(s) {
			t.Errorf("ValidText(%q) is false, but it renders as real text", s)
		}
	}

}

// Package patron is the engine behind recurring support for a builder: a plan
// somebody subscribes to, period after period, paid in ugnot on chain.
//
// # There is no cron on chain, so a renewal is a pull and not a push
//
// Nothing here can charge anybody. The supporter sends another payment and
// their paid-through height moves forward; there is no scheduler, no keeper,
// and no standing authority over anybody's balance. There is no way to write
// one either, because a native coin cannot be pulled at all: a banker may only
// spend its own realm's address, so the inbound path is always the holder
// signing. A reader arriving from web2 expects the opposite, and that is the
// one expectation to unlearn before reading the rest of this package.
//
// # What this adds over a tip jar
//
// A tip jar is one payment and then nothing, and the one-shot version is
// already live at gno.land/r/moul/x/daily/tipjar. The recurrence is the only
// reason this exists: a plan carries a price per period and a period measured
// in BLOCKS, a supporter buys whole periods, and anybody can ask at any height
// whether a given address is still active. It is the one piece of the x/social
// family that produces a recurring write rather than a one-off.
//
// # The model
//
//	Registry  every plan, plus the credit ledger money leaves through
//	Plan      a creator, a title, a description, a price, a period, open or not
//	Payment   what one Subscribe call bought: periods, spent, change, through
//
// # Renewing early never loses time already paid for
//
// [Registry.Subscribe] extends from whichever is LATER, now or the supporter's
// current paid-through height. Renewing two blocks before a lapse adds a whole
// period on top of what is left. Renewing after a lapse starts from now,
// because the gap was never paid for and nothing backdates it.
//
// # The change is credited back, never kept
//
// A payment buys floor(sent / price) whole periods, and the remainder under
// one period is credited to the SUPPORTER's own withdrawable balance. Keeping
// it would be a fee nobody agreed to, and a silent fee is the thing a
// subscription realm must not have. The supporter takes it back through the
// same [Registry.Withdraw] a creator uses.
//
// # Earnings are credited at the moment of payment, not streamed
//
// The creator can withdraw the whole price the instant it is paid. A supporter
// who stops being active is therefore NOT refunded, and no part of a paid
// period is ever returned. That is a real limitation and it is v0 on purpose:
// escrowed streaming, where the creator claims only what has elapsed and the
// supporter can cancel and reclaim the rest, needs a claim schedule and a
// refund path, which is a bigger realm than this one. It is the v1, and it is
// not a line that can be bolted onto this one.
//
// # Money leaves by pull, never by a push loop
//
// Nothing here moves coins. [Registry.Subscribe] credits a
// gno.land/p/moul/x/daily/pullpayment ledger, and [Registry.Withdraw] zeroes a
// credit and reports what was owed so the holding realm can transfer after
// that call, with the balance already gone when control leaves. A realm that
// looped over payees instead would fail entirely on one unpayable address and
// hand a griefer a cheap denial of service.
//
// # A title and a description are attacker-controlled markdown
//
// Both are free text. [ValidTitle] and [ValidDescription] bound them and
// refuse control characters, which is a different protection from escaping and
// not a substitute for it: a realm that renders either one escapes it with
// ui.Inline in prose or ui.Cell in a table cell.
package patron

import (
	"chain/markdown"
	"errors"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/pullpayment/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/xmath/v1"
)

const (
	// MaxTitleLen and MaxDescriptionLen bound the two free-text fields. Long
	// enough to say what the plan is, short enough that opening one cannot
	// lock an unbounded storage deposit somebody else is paying for.
	MaxTitleLen       = 80
	MaxDescriptionLen = 500

	// MinPeriodBlocks and MaxPeriodBlocks bound a period both ways. A period
	// of zero blocks is not a subscription, it is a division by zero wearing
	// a price tag. The ceiling is about a year at the five second blocks the
	// test chain runs, past which "recurring" stops meaning anything and the
	// plan is a one-off with extra steps.
	MinPeriodBlocks = int64(10)
	MaxPeriodBlocks = int64(6307200)

	// MinPricePerPeriod is one ugnot, because a free plan is a tip jar
	// (gno.land/r/moul/x/daily/tipjar) and not a subscription: at a price of
	// zero there is nothing to buy a period with and every address would be
	// active forever.
	MinPricePerPeriod = int64(1)

	// MaxPeriodsPerPayment bounds what one payment may buy. It keeps
	// periods * PeriodBlocks inside an int64 by construction rather than by
	// hope, and it stops a single send from parking a paid-through height so
	// far ahead that no later arithmetic on it means anything.
	MaxPeriodsPerPayment = int64(10000)
)

// The errors a caller can get back. A p/ package returns them and the realm
// decides to abort.
var (
	ErrBadTitle          = errors.New("patron: title is empty, too long, or has control characters")
	ErrBadDescription    = errors.New("patron: description is too long or has control characters")
	ErrBadPrice          = errors.New("patron: a plan needs a price of at least one ugnot per period")
	ErrBadPeriod         = errors.New("patron: period out of range")
	ErrNoPlan            = errors.New("patron: no such plan")
	ErrPlanClosed        = errors.New("patron: this plan is closed to new subscriptions")
	ErrNotCreator        = errors.New("patron: only the plan's creator can do that")
	ErrAlreadyOpen       = errors.New("patron: the plan is already open")
	ErrAlreadyClosed     = errors.New("patron: the plan is already closed")
	ErrShortOfOnePeriod  = errors.New("patron: the payment does not cover one whole period")
	ErrTooManyPeriods    = errors.New("patron: one payment cannot buy that many periods")
	ErrNothingToWithdraw = errors.New("patron: nothing to withdraw")
)

// Plan is one creator's recurring support plan.
type Plan struct {
	Creator     address
	Title       string
	Description string

	// PricePerPeriod is what one period costs, in ugnot.
	PricePerPeriod int64

	// PeriodBlocks is how long a period lasts, in blocks. Blocks and not
	// seconds: height is the clock consensus agrees on, and a block timestamp
	// is set by proposers and is not something to build a billing cliff out
	// of at second resolution.
	PeriodBlocks int64

	// Open reports whether the plan takes NEW payments. Closing it never
	// touches a subscription already paid for, which runs to its own
	// paid-through height.
	Open bool

	// Received is the lifetime ugnot this plan credited to its creator.
	Received int64

	// paidThrough is the first height at which a supporter is no longer
	// active. A supporter is active while now < paidThrough, so a period
	// bought at height h ends at h+PeriodBlocks and the holder is inactive
	// at exactly that height.
	paidThrough map[string]int64

	// supporters is every address that has ever paid, in first-payment
	// order. It exists so a listing is deterministic without iterating a map
	// as if insertion order were a sort.
	supporters []address
}

// PaidThrough is the height who stops being active at, or zero if they never
// paid.
func (p *Plan) PaidThrough(who address) int64 {
	if p == nil {
		return 0
	}
	return p.paidThrough[who.String()]
}

// IsActive reports whether who is paid up at height now.
//
// The comparison is strict: a supporter paid through height h is active at
// h-1 and not at h. One rule, applied at both edges, so a period never
// overlaps the next one by a block.
func (p *Plan) IsActive(who address, now int64) bool {
	return p.PaidThrough(who) > now
}

// SupporterCount is how many distinct addresses have ever paid, active or not.
func (p *Plan) SupporterCount() int {
	if p == nil {
		return 0
	}
	return len(p.supporters)
}

// Supporters is every address that has ever paid, in first-payment order.
//
// It returns a copy. Handing out the stored slice would be a live mutation
// handle on realm state, which is the cheapest way for a reader to become a
// writer.
func (p *Plan) Supporters() []address {
	if p == nil {
		return nil
	}
	out := make([]address, len(p.supporters))
	copy(out, p.supporters)
	return out
}

// ActiveCount is how many supporters are paid up at height now.
func (p *Plan) ActiveCount(now int64) int {
	if p == nil {
		return 0
	}
	n := 0
	for _, who := range p.supporters {
		if p.IsActive(who, now) {
			n++
		}
	}
	return n
}

// Payment is what one [Registry.Subscribe] call bought.
type Payment struct {
	// Periods is how many whole periods the payment covered.
	Periods int64

	// Spent is the ugnot those periods cost, credited to the creator.
	Spent int64

	// Change is the remainder under one period, credited back to the
	// supporter rather than kept.
	Change int64

	// PaidThrough is the supporter's new paid-through height.
	PaidThrough int64

	// NewSupporter reports whether this address had never paid this plan
	// before, which is the signal a realm wants for an event or a counter.
	NewSupporter bool
}

// Registry holds every plan and the credit ledger money leaves through.
type Registry struct {
	plans  *store.Store
	ledger *pullpayment.Ledger

	// earned is lifetime ugnot credited per creator, which survives a
	// withdrawal. The ledger only knows what is owed RIGHT NOW, and a page
	// showing a creator zero the moment they cash out would be telling the
	// truth about the wrong question.
	earned map[string]int64
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry {
	return &Registry{
		plans:  store.Named("plan"),
		ledger: pullpayment.New(),
		earned: map[string]int64{},
	}
}

// Open creates a plan and returns its id. Anyone may open one.
func (r *Registry) Open(creator address, title, description string, pricePerPeriod, periodBlocks int64) (store.ID, error) {
	if !ValidTitle(title) {
		return 0, ErrBadTitle
	}
	if !ValidDescription(description) {
		return 0, ErrBadDescription
	}
	if pricePerPeriod < MinPricePerPeriod {
		return 0, ErrBadPrice
	}
	if periodBlocks < MinPeriodBlocks || periodBlocks > MaxPeriodBlocks {
		return 0, ErrBadPeriod
	}
	return r.plans.Add(&Plan{
		Creator:        creator,
		Title:          title,
		Description:    description,
		PricePerPeriod: pricePerPeriod,
		PeriodBlocks:   periodBlocks,
		Open:           true,
		paidThrough:    map[string]int64{},
	}), nil
}

// Subscribe buys whole periods on a plan with sent ugnot, at height now.
//
// It refuses anything short of one period, buys floor(sent / price) of them,
// and credits the remainder back to the supporter. The extension starts from
// whichever is LATER, now or the supporter's current paid-through height, so
// renewing early never discards time already paid for and renewing after a
// lapse never backdates the gap.
//
// The creator is credited at the moment of payment, not as the periods
// elapse. See the package doc for why that is v0 and what v1 would have to
// carry instead.
func (r *Registry) Subscribe(id store.ID, who address, sent, now int64) (Payment, error) {
	p, ok := r.Get(id)
	if !ok {
		return Payment{}, ErrNoPlan
	}
	if !p.Open {
		return Payment{}, ErrPlanClosed
	}
	if sent < p.PricePerPeriod {
		return Payment{}, ErrShortOfOnePeriod
	}

	// The one rounding decision in this function: periods is floor, so a
	// supporter is never sold a period they did not fully fund, and the
	// remainder is handed back below rather than kept. Neither side keeps a
	// fraction of a period.
	periods := sent / p.PricePerPeriod
	if periods > MaxPeriodsPerPayment {
		return Payment{}, ErrTooManyPeriods
	}
	spent := sent - sent%p.PricePerPeriod
	change := sent - spent

	// spent is an exact whole number of periods, so this division leaves no
	// remainder and there is no second rounding direction to choose. MulDiv
	// is here for the intermediate: spent * PeriodBlocks overflows an int64
	// for a plan priced in whole GNOT with a period measured in months, and
	// the naive product wraps to a plausible-looking height rather than to an
	// obvious one. MulDivUp would be identical on an exact division; MulDiv
	// says plainly that nothing is being rounded up.
	added := xmath.MulDiv(spent, p.PeriodBlocks, p.PricePerPeriod)

	from := now
	if pt := p.PaidThrough(who); pt > from {
		from = pt
	}
	through := from + added

	key := who.String()

	// Both credits happen before the plan is touched, and both can fail: the
	// ledger is bounded and guards its own overflow. A realm calling this
	// aborts on the error, which reverts everything written in the same
	// frame, so a half-applied subscription is not reachable from a crossing
	// call. The ordering is what makes that true for every other caller too.
	if err := r.ledger.Credit(p.Creator.String(), spent); err != nil {
		return Payment{}, err
	}
	if change > 0 {
		if err := r.ledger.Credit(key, change); err != nil {
			return Payment{}, err
		}
	}
	r.earned[p.Creator.String()] += spent

	_, seen := p.paidThrough[key]
	if !seen {
		p.supporters = append(p.supporters, who)
	}
	p.paidThrough[key] = through
	p.Received += spent

	return Payment{
		Periods:      periods,
		Spent:        spent,
		Change:       change,
		PaidThrough:  through,
		NewSupporter: !seen,
	}, nil
}

// Close stops a plan taking new subscriptions. Creator only.
//
// It does not touch anything already paid for: existing supporters run to
// their own paid-through height, which is the only behaviour that does not
// turn closing a plan into taking money back.
func (r *Registry) Close(id store.ID, who address) error {
	p, err := r.ownPlan(id, who)
	if err != nil {
		return err
	}
	if !p.Open {
		return ErrAlreadyClosed
	}
	p.Open = false
	return nil
}

// Reopen lets a closed plan take subscriptions again. Creator only.
func (r *Registry) Reopen(id store.ID, who address) error {
	p, err := r.ownPlan(id, who)
	if err != nil {
		return err
	}
	if p.Open {
		return ErrAlreadyOpen
	}
	p.Open = true
	return nil
}

// ownPlan is the shared lookup plus authority check, so Close and Reopen
// cannot drift apart on who is allowed to call them.
func (r *Registry) ownPlan(id store.ID, who address) (*Plan, error) {
	p, ok := r.Get(id)
	if !ok {
		return nil, ErrNoPlan
	}
	if p.Creator != who {
		return nil, ErrNotCreator
	}
	return p, nil
}

// Withdraw zeroes who's credit and reports what they were owed.
//
// It moves no coins. The holding realm transfers the returned amount AFTER
// this call, which is the whole point of the pattern: the credit is already
// gone from the ledger when control passes to the payee, so a reentrant call
// finds nothing and gets [ErrNothingToWithdraw].
func (r *Registry) Withdraw(who address) (int64, error) {
	amount, err := r.ledger.Withdraw(who.String())
	if err != nil {
		return 0, ErrNothingToWithdraw
	}
	return amount, nil
}

// CreditOf is what addr can withdraw right now: earnings as a creator, change
// as a supporter, or both.
func (r *Registry) CreditOf(addr address) int64 { return r.ledger.Balance(addr.String()) }

// EarnedBy is the lifetime ugnot credited to creator across every plan,
// whether or not it has been withdrawn.
func (r *Registry) EarnedBy(creator address) int64 { return r.earned[creator.String()] }

// TotalOwed is everything the holding realm must keep in reserve.
func (r *Registry) TotalOwed() int64 { return r.ledger.TotalOwed() }

// Get returns a plan by id.
func (r *Registry) Get(id store.ID) (*Plan, bool) {
	v, ok := r.plans.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Plan), true
}

// Count is how many plans exist.
func (r *Registry) Count() int { return r.plans.Len() }

// Listing is one row of [Registry.List]: the plan and the id a link needs.
type Listing struct {
	ID   store.ID
	Plan *Plan
}

// List returns one page of plans, newest first.
func (r *Registry) List(page, size int) []Listing {
	var out []Listing
	for _, e := range r.plans.PageReverse(page, size) {
		out = append(out, Listing{ID: e.ID, Plan: e.Value.(*Plan)})
	}
	return out
}

// Pages is how many pages of the given size the registry holds.
func (r *Registry) Pages(size int) int { return r.plans.Pages(size) }

// ValidTitle reports whether title can be stored: non-empty after the
// render's own stripping and trimming,
// within [MaxTitleLen], and free of control characters including newlines.
//
// A title is one line by construction, so a newline in one is refused rather
// than stripped: silently rewriting what somebody typed is worse than telling
// them it was refused.
func ValidTitle(title string) bool {
	if len(title) > MaxTitleLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(title)) == "" {
		return false
	}
	for i := 0; i < len(title); i++ {
		if c := title[i]; c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidDescription reports whether description can be stored: within
// [MaxDescriptionLen] and free of control characters other than newline and
// tab. Empty is allowed, because a plan whose title says it all should not
// have to invent prose.
func ValidDescription(description string) bool {
	if len(description) > MaxDescriptionLen {
		return false
	}
	for i := 0; i < len(description); i++ {
		c := description[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// PlanURL is the gnoweb path of one plan on the hosting realm.
func PlanURL(realmPath string, id store.ID) string {
	return RealmURL(realmPath) + ":plan/" + id.String()
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

package patron

import "testing"

// Finding 325-input-validation-1 (review run 001-cd0b6a9).
//
// A validator that calls a field required must agree with the escaper its own
// render runs. strings.TrimSpace uses unicode.IsSpace, which does NOT include
// U+200B and the rest of the bidi and zero-width set, while every escaper on
// the output side runs chain/markdown.StripBidiAndZeroWidth, which does. So a
// value made only of those characters passes validation and renders as
// nothing: a required field that is blank on the page.
//
// The cases below are the invariant, not the implementation. A value the
// validator accepts must still be non-empty after the stripper.
func TestValidatorsAgreeWithTheEscaper(t *testing.T) {
	// One per class the stripper removes, so a fix that handles only
	// U+200B does not pass.
	blank := []string{
		"\u200b\u200b\u200b",   // ZWSP
		"\u200d",                // ZWJ
		"\u200e",                // LRM
		"\u202e",                // RLO
		"\u2066\u2069",          // LRI PDI
		"\ufeff",                // BOM
		" \u200b \u200b ",        // mixed with real spaces
	}
	// These must stay valid: the stripper removes the marks and leaves text.
	ok := []string{
		"a",
		"a\u200bb",
		"  padded  ",
	}

	for _, s := range blank {
		if ValidTitle(s) {
			t.Errorf("ValidTitle(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidTitle(s) {
			t.Errorf("ValidTitle(%q) is false, but it renders as real text", s)
		}
	}

}

// Package vouch is the engine behind a web of trust: one address says it
// stands behind another, in writing, optionally with its own money locked
// against the claim.
//
// # What it is for
//
// It is a sybil gate, and it exists because the apps around it do not have
// one. A realm that mints a point per distinct replier is farmed by two
// addresses replying to each other; a realm that counts one vote per address
// is farmed by holding a hundred addresses. Neither can fix that alone,
// because neither knows anything about the people behind the addresses.
//
// This package knows one thing: who was willing to say, on chain and under
// their own name, that an address is a person they stand behind. A realm asks
// [Graph.IsTrusted] and gates on the answer. That is the whole product, and
// every other read here exists to make that one legible.
//
// # The model
//
//	Graph   every vouch, in both directions, plus the refund ledger
//	Vouch   a directed statement: from, for, reason, bond, heights
//
// A vouch is directed and at most one exists per ordered pair. A second
// [Graph.Record] from the same address to the same target UPDATES the reason
// and ADDS to the bond rather than counting twice, which is what makes the
// score a count of people instead of a count of transactions. An address
// cannot vouch for itself.
//
// # The bond
//
// A vouch may lock coins. The engine only counts them: it takes the amount as
// an argument, tracks who posted how much on whom, and on [Graph.Revoke] moves
// that amount into a withdrawal ledger the voucher pulls from. It moves
// nothing itself. The realm holding the coins performs the transfer AFTER
// [Graph.Withdraw] has zeroed the credit, which is the ordering the
// pull-payment pattern demands.
//
// # No slashing, and why that is the hard part
//
// A bond here is value at risk only in the sense that it is illiquid: it can
// be withdrawn by revoking, and nothing can take it away. That is deliberate
// for a v0, and the missing half is not the accounting.
//
// Slashing needs an arbiter: somebody has to decide that a vouch was a lie.
// Every candidate is a design question with teeth. A DAO vote is a popularity
// contest against whoever is unpopular this month. A challenge market pays
// whoever is loudest and turns the graph into a griefing surface. An oracle is
// one key that can confiscate anyone's money. Shipping any of them by default
// would be shipping the wrong one, so this version ships the part that is
// uncontroversial: who said what, who put money behind it, and the gate that
// reads it.
//
// # Reasons are attacker-controlled markdown
//
// A reason is free text. [ValidReason] bounds it to [MaxReasonLen] bytes on
// one line and refuses control characters, but everything inside that is
// allowed and must be escaped where it is shown: ui.Inline in prose, ui.Cell
// in a table cell.
package vouch

import (
	"chain/markdown"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/addrset/v1"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/num/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/tally/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/pullpayment/v0"
)

// MaxReasonLen is the longest reason accepted, in bytes. Long enough to say
// how you know somebody, short enough that one call cannot lock an unbounded
// storage deposit the realm's deployer is paying for.
const MaxReasonLen = 200

const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back. A p/ returns them; the realm decides to
// abort.
var (
	ErrSelfVouch   = errors.New("vouch: an address cannot vouch for itself")
	ErrBadReason   = errors.New("vouch: reason is empty, too long, multi-line, or has control characters")
	ErrBadBond     = errors.New("vouch: a bond cannot be negative")
	ErrNoVouch     = errors.New("vouch: no such vouch")
	ErrNothingOwed = errors.New("vouch: nothing to withdraw")
	ErrOverflow    = errors.New("vouch: bond would overflow")
)

// Vouch is one directed statement of trust.
type Vouch struct {
	From   address
	For    address
	Reason string

	// Bond is the amount locked on this vouch, in the realm's denom. It is
	// the sum of every bond sent with this pair, since a repeated vouch
	// adds to it rather than replacing it.
	Bond int64

	// At is the height the vouch was first made, UpdatedAt the height it
	// last changed. They are equal until the voucher restates it.
	At        int64
	UpdatedAt int64
}

// Graph is the whole web of trust: every vouch, both directions of every
// edge, what is bonded on whom, and what revoking owes back to whom.
type Graph struct {
	edges    map[string]*Vouch       // "from|for" -> the vouch
	inbound  map[string]*addrset.Set // target -> who vouches for them
	outbound map[string]*addrset.Set // voucher -> who they vouch for
	bonded   map[string]int64        // target -> total bonded on them

	// people is every address with at least one inbound vouch, sorted, so
	// a listing never has to iterate a map to build rendered output.
	people addrset.Set

	refunds     *pullpayment.Ledger
	count       int
	totalBonded int64
}

// NewGraph returns an empty graph.
func NewGraph() *Graph {
	return &Graph{
		edges:    map[string]*Vouch{},
		inbound:  map[string]*addrset.Set{},
		outbound: map[string]*addrset.Set{},
		bonded:   map[string]int64{},
		refunds:  pullpayment.New(),
	}
}

// Record writes from's vouch for target and reports whether it replaced one
// that already existed.
//
// A repeated vouch is an update and not a second voice: the reason is
// replaced, the bond is added to the one already posted, and the score does
// not move. bond may be zero, which is the ordinary case.
func (g *Graph) Record(from, target address, reason string, bond, at int64) (updated bool, err error) {
	if from == target {
		return false, ErrSelfVouch
	}
	if !ValidReason(reason) {
		return false, ErrBadReason
	}
	if bond < 0 {
		return false, ErrBadBond
	}
	tk := target.String()
	if g.bonded[tk] > maxInt64-bond || g.totalBonded > maxInt64-bond {
		return false, ErrOverflow
	}

	if v, ok := g.edges[key(from, target)]; ok {
		if v.Bond > maxInt64-bond {
			return false, ErrOverflow
		}
		v.Reason = reason
		v.Bond += bond
		v.UpdatedAt = at
		g.bonded[tk] += bond
		g.totalBonded += bond
		return true, nil
	}

	g.edges[key(from, target)] = &Vouch{
		From:      from,
		For:       target,
		Reason:    reason,
		Bond:      bond,
		At:        at,
		UpdatedAt: at,
	}
	g.set(g.inbound, tk).Add(from)
	g.set(g.outbound, from.String()).Add(target)
	g.people.Add(target)
	g.bonded[tk] += bond
	g.totalBonded += bond
	g.count++
	return false, nil
}

// Revoke removes from's vouch for target and credits the bond back to from,
// returning the amount credited.
//
// The coins are not sent here and this package never holds any: the credit
// waits in the refund ledger until from calls [Graph.Withdraw].
func (g *Graph) Revoke(from, target address) (refund int64, err error) {
	v, ok := g.edges[key(from, target)]
	if !ok {
		return 0, ErrNoVouch
	}
	// Credit first, because it is the only step that can fail. Nothing is
	// mutated until the refund is certain, so a full ledger leaves the
	// graph exactly as it was rather than half revoked.
	if v.Bond > 0 {
		if err := g.refunds.Credit(from.String(), v.Bond); err != nil {
			return 0, err
		}
	}

	delete(g.edges, key(from, target))
	tk, fk := target.String(), from.String()

	if in, ok := g.inbound[tk]; ok {
		in.Remove(from)
		if in.Size() == 0 {
			delete(g.inbound, tk)
			g.people.Remove(target)
		}
	}
	if out, ok := g.outbound[fk]; ok {
		out.Remove(target)
		if out.Size() == 0 {
			delete(g.outbound, fk)
		}
	}

	g.bonded[tk] -= v.Bond
	if g.bonded[tk] == 0 {
		delete(g.bonded, tk)
	}
	g.totalBonded -= v.Bond
	g.count--
	return v.Bond, nil
}

// Withdraw zeroes what the graph owes who and returns it, so the realm can
// send exactly that much.
//
// The credit is gone from the ledger before this returns, which is what makes
// a reentrant call find nothing: the realm transfers after, never before.
func (g *Graph) Withdraw(who address) (int64, error) {
	amount, err := g.refunds.Withdraw(who.String())
	if err != nil {
		return 0, ErrNothingOwed
	}
	return amount, nil
}

// Get returns one vouch.
func (g *Graph) Get(from, target address) (*Vouch, bool) {
	v, ok := g.edges[key(from, target)]
	return v, ok
}

// ScoreOf is how many distinct addresses vouch for addr.
//
// It counts people and not statements: restating a vouch does not raise it,
// and revoking lowers it.
func (g *Graph) ScoreOf(addr address) int {
	if in, ok := g.inbound[addr.String()]; ok {
		return in.Size()
	}
	return 0
}

// BondedFor is the total locked on addr by everyone vouching for them.
func (g *Graph) BondedFor(addr address) int64 { return g.bonded[addr.String()] }

// IsTrusted reports whether addr is vouched for by at least min distinct
// addresses. It is the gate another realm calls, and the reason this package
// exists.
//
// A min below one is raised to one. A gate that lets everybody through is a
// bug at the call site rather than an answer worth returning, and silently
// agreeing with it is how a sybil check ships disabled.
//
// What it cannot tell you is whether those vouchers are distinct PEOPLE. Two
// addresses vouching for each other both reach a score of one for the price of
// two transactions, which is why [Graph.Mutual] is exported and why a gate
// that matters should ask for more than one.
func (g *Graph) IsTrusted(addr address, min int) bool {
	if min < 1 {
		min = 1
	}
	return g.ScoreOf(addr) >= min
}

// VouchedBy is every address that vouches for addr, sorted.
//
// Sorted and not chronological: the set is the storage, the order is a total
// order on the address, and two identical calls therefore render identically.
func (g *Graph) VouchedBy(addr address) []address {
	return collect(g.inbound[addr.String()])
}

// VouchesOf is every address addr vouches for, sorted. It is the other
// direction of [Graph.VouchedBy].
func (g *Graph) VouchesOf(addr address) []address {
	return collect(g.outbound[addr.String()])
}

// Mutual reports whether a and b vouch for each other.
//
// A mutual pair is the cheapest sybil shape there is, so this is here to be
// discounted by a caller that cares, not as a badge.
func (g *Graph) Mutual(a, b address) bool {
	if a == b {
		return false
	}
	_, there := g.edges[key(a, b)]
	_, back := g.edges[key(b, a)]
	return there && back
}

// ReasonFrom is what from wrote about target, or the empty string when there
// is no such vouch. It is raw caller text: escape it where it is shown.
func (g *Graph) ReasonFrom(from, target address) string {
	if v, ok := g.edges[key(from, target)]; ok {
		return v.Reason
	}
	return ""
}

// BondFrom is what from locked on target, or zero.
func (g *Graph) BondFrom(from, target address) int64 {
	if v, ok := g.edges[key(from, target)]; ok {
		return v.Bond
	}
	return 0
}

// Count is how many vouches exist, across everybody.
func (g *Graph) Count() int { return g.count }

// People is how many addresses have at least one vouch for them.
func (g *Graph) People() int { return g.people.Size() }

// Owed is what revoking has credited to addr and nobody has withdrawn yet.
func (g *Graph) Owed(addr address) int64 { return g.refunds.Balance(addr.String()) }

// TotalOwed is every unwithdrawn refund. The realm must hold at least
// TotalOwed plus [Graph.TotalBonded] to be solvent.
func (g *Graph) TotalOwed() int64 { return g.refunds.TotalOwed() }

// TotalBonded is everything locked on every vouch that still stands.
func (g *Graph) TotalBonded() int64 { return g.totalBonded }

// Ranked is one row of [Graph.Leaderboard].
type Ranked struct {
	Addr   address
	Score  int
	Bonded int64
}

// Leaderboard is the most vouched for addresses, highest score first, ties
// broken by address so the order is total and a Render never reshuffles.
//
// limit at or below zero returns nothing.
func (g *Graph) Leaderboard(limit int) []Ranked {
	if limit <= 0 || g.people.Size() == 0 {
		return nil
	}
	entries := make([]tally.Entry, 0, g.people.Size())
	g.people.IterateByOffset(0, g.people.Size(), func(a address) bool {
		entries = append(entries, tally.Entry{Key: a.String(), Score: int64(g.ScoreOf(a))})
		return false
	})
	top := tally.Top(entries, limit)

	out := make([]Ranked, 0, len(top))
	for _, e := range top {
		a := address(e.Key)
		out = append(out, Ranked{Addr: a, Score: int(e.Score), Bonded: g.bonded[e.Key]})
	}
	return out
}

// ValidReason reports whether reason can be stored: non-empty after the
// render's own stripping and trimming,
// within [MaxReasonLen], on one line, and free of control characters.
//
// One line is a deliberate bound rather than a rendering workaround. A reason
// is shown in a table cell beside the address it is about, and a writer who
// needs a second paragraph is writing something other than a reason.
//
// Control characters are refused rather than stripped because the text is
// shown back to whoever wrote it, and silently rewriting what somebody said is
// worse than telling them it was refused. Everything else is allowed and
// escaped at render time, since a validator and an escaper protect against
// different mistakes.
func ValidReason(reason string) bool {
	if len(reason) > MaxReasonLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(reason)) == "" {
		return false
	}
	for i := 0; i < len(reason); i++ {
		if c := reason[i]; c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// Badge is the one-line trust mark, for a realm that wants to show what the
// gate it just called was reading.
//
// It takes the numbers rather than the graph because the realm holding the
// graph is the only one that can read it: everybody else has the two integers
// from a cross-realm call and needs nothing more to render them.
func Badge(realmPath string, addr address, score int, bonded int64) string {
	if score == 0 {
		return md.Link("not vouched for", AddrURL(realmPath, addr))
	}
	word := " vouchers"
	if score == 1 {
		word = " voucher"
	}
	out := "\U0001F91D " + md.Link(strconv.Itoa(score)+word, AddrURL(realmPath, addr))
	if bonded > 0 {
		out += " · " + num.GNOTf(bonded) + " bonded"
	}
	return out
}

// AddrURL is the gnoweb path of one address's page on the hosting realm.
func AddrURL(realmPath string, addr address) string {
	return RealmURL(realmPath) + ":addr/" + addr.String()
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

// key is the storage key of one directed edge. Addresses are fixed-length
// bech32, so the separator is belt and braces rather than load-bearing.
func key(from, target address) string { return from.String() + "|" + target.String() }

// set returns the address set stored under k, creating it on first use.
func (g *Graph) set(m map[string]*addrset.Set, k string) *addrset.Set {
	if s, ok := m[k]; ok {
		return s
	}
	s := &addrset.Set{}
	m[k] = s
	return s
}

// collect reads a set out in sorted order.
func collect(s *addrset.Set) []address {
	if s == nil || s.Size() == 0 {
		return nil
	}
	out := make([]address, 0, s.Size())
	s.IterateByOffset(0, s.Size(), func(a address) bool {
		out = append(out, a)
		return false
	})
	return out
}

package vouch

import "testing"

// Finding 325-input-validation-1 (review run 001-cd0b6a9).
//
// A validator that calls a field required must agree with the escaper its own
// render runs. strings.TrimSpace uses unicode.IsSpace, which does NOT include
// U+200B and the rest of the bidi and zero-width set, while every escaper on
// the output side runs chain/markdown.StripBidiAndZeroWidth, which does. So a
// value made only of those characters passes validation and renders as
// nothing: a required field that is blank on the page.
//
// The cases below are the invariant, not the implementation. A value the
// validator accepts must still be non-empty after the stripper.
func TestValidatorsAgreeWithTheEscaper(t *testing.T) {
	// One per class the stripper removes, so a fix that handles only
	// U+200B does not pass.
	blank := []string{
		"\u200b\u200b\u200b",   // ZWSP
		"\u200d",                // ZWJ
		"\u200e",                // LRM
		"\u202e",                // RLO
		"\u2066\u2069",          // LRI PDI
		"\ufeff",                // BOM
		" \u200b \u200b ",        // mixed with real spaces
	}
	// These must stay valid: the stripper removes the marks and leaves text.
	ok := []string{
		"a",
		"a\u200bb",
		"  padded  ",
	}

	for _, s := range blank {
		if ValidReason(s) {
			t.Errorf("ValidReason(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidReason(s) {
			t.Errorf("ValidReason(%q) is false, but it renders as real text", s)
		}
	}

}

// Package bf is a Brainfuck machine for gno.land, and the measuring stick the
// rest of the guest-VM work is calibrated against.
//
// It ships two things that look alike and are not:
//
//   - [Execute], the naive interpreter: a switch over the source bytes, a
//     brace matcher that rescans the program on every loop edge. It is kept
//     verbatim as rung 0 of the optimization ladder, because a baseline you
//     have edited is not a baseline.
//   - [Compile] plus [Machine], the real one: the program is compiled to an
//     op array with resolved jumps, runs of identical operators are fused,
//     the common loop idioms become single ops, and execution is metered by
//     a caller-supplied fuel budget against a
//     [vmkit](/p/moul/x/vm/vmkit/v0) Host, so a program can pause when it
//     runs out and resume in a later transaction.
//
// The ladder between them is measured, not asserted: see the README for the
// table, and ladder_test.gno for the harness that produces it.
//
// Live demo: [r/moul/x/vm/bfdemo](/r/moul/x/vm/bfdemo/v0).
package bf

import "strings"

// NaiveTapeSize is the tape length used by [Execute]. It is 30,000 because
// that is what the original had, and rung 0 is not allowed to drift.
const NaiveTapeSize = 30000

// Execute runs code on a fresh tape and returns everything it wrote, using
// the original 2023 implementation: no compilation step, one switch per
// source byte, and a brace matcher that rescans the source every time a loop
// opens or closes.
//
// It is rung 0 of the ladder and exists to be measured. Two of its properties
// are bugs that are deliberately preserved, and are the reason nothing should
// call it on untrusted input:
//
//   - `,` panics with "unsupported": there is no input.
//   - unbalanced brackets run the scan off the end of the source and panic
//     with an index out of range.
//
// Use [Compile] and [Machine] for anything real: they reject a malformed
// program up front, read input from the host, and cannot run unbounded.
func Execute(code string) string {
	var (
		memory  = make([]byte, NaiveTapeSize) // memory tape
		pointer = 0                           // initial memory pointer
		buf     strings.Builder
	)

	// Loop through each character in the code
	for i := 0; i < len(code); i++ {
		switch code[i] {
		case '>':
			// Increment memory pointer
			pointer++
			if pointer >= NaiveTapeSize {
				pointer = 0
			}
		case '<':
			// Decrement memory pointer
			pointer--
			if pointer < 0 {
				pointer = NaiveTapeSize - 1
			}
		case '+':
			// Increment the byte at the memory pointer
			memory[pointer]++
		case '-':
			// Decrement the byte at the memory pointer
			memory[pointer]--
		case '.':
			// Output the byte at the memory pointer
			buf.WriteByte(memory[pointer])
		case ',':
			// Input a byte and store it in the memory
			panic("unsupported")
		case '[':
			// Jump forward past the matching ']' if the byte at the memory pointer is zero
			if memory[pointer] == 0 {
				braceCount := 1
				for braceCount > 0 {
					i++
					if code[i] == '[' {
						braceCount++
					} else if code[i] == ']' {
						braceCount--
					}
				}
			}
		case ']':
			// Jump backward to the matching '[' if the byte at the memory pointer is nonzero
			if memory[pointer] != 0 {
				braceCount := 1
				for braceCount > 0 {
					i--
					if code[i] == ']' {
						braceCount++
					} else if code[i] == '[' {
						braceCount--
					}
				}
				i-- // Move back one more to compensate for the upcoming increment in the loop
			}
		}
	}
	return buf.String()
}

package bf

import (
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// hello is the classic 106 byte hello-world. It writes "Hello World", 11
// bytes: the original run.gno comment was optimistic about the trailing "!\n".
const hello = "++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------."

// corpus is the set of programs every ladder level must agree on. Each one is
// here because it exercises a rewrite that could plausibly be wrong.
var corpus = []struct {
	name string
	src  string
	want string
}{
	{"empty", "", ""},
	{"comment only", "this is not brainfuck", ""},
	{"hello", hello, "Hello World"},
	{"clear idiom", "+++++[-]+++++++++++++++++++++++++++++++++++++++++++++++.", "/"},
	{"move idiom", "+++++++++++++++++++++++++++++++++++++++++++++++++++[->+<]>.", "3"},
	{"multiply idiom", "+++++[->++++++++++<]>++.", "4"},
	{"two targets", "+++[->+>++<<]>+++++++++++++++++++++++++++++++++++++++.>+++++++++++++++++++++++++++++++++++++++++.", "*/"},
	{"scan walks", ">+>+>+>+[<]++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++.", "H"},
	{"scan right", ">>>+++++++++<<<[>]+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++.", "?"},
	{"nested loops", "++[>++[>+<-]<-]>>+++++++++++++++++++++++++++++++++++++++++++++++++.", "5"},
	{"dead run", "+++--+++--+++++++++++++++++++++++++++++++++++++++++++.", "-"},
	{"skipped loop", "[++++++++++++++++++++]+++++++++++++++++++++++++++++++++++++++++++++++.", "/"},
	{"wraps under zero", "-[>+<-]>++++++++++.", "\t"},
}

func runLevel(t *testing.T, src string, lvl Level, input string) string {
	t.Helper()
	prog, err := Compile(src, lvl)
	uassert.NoError(t, err)
	if prog == nil {
		return ""
	}
	h := vmkit.NewTestHost().WithInput([]byte(input))
	m := NewMachine(prog)
	_, status := m.Step(h, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	return h.OutString()
}

// TestLadderLevelsAgree is the test the whole ladder rests on: an
// optimization that changes the output is not an optimization.
func TestLadderLevelsAgree(t *testing.T) {
	for _, tc := range corpus {
		naive := Execute(tc.src)
		uassert.Equal(t, tc.want, naive)

		for _, lvl := range []Level{LevelJumps, LevelFuse, LevelIdioms} {
			got := runLevel(t, tc.src, lvl, "")
			if got != tc.want {
				t.Errorf("%s at level %s: got %q, want %q",
					tc.name, lvl.String(), got, tc.want)
			}
		}
	}
}

func TestExecuteBaseline(t *testing.T) {
	// Rung 0 is kept verbatim, so this is also a regression test on the
	// thing the published cycles-per-op number was measured against.
	uassert.Equal(t, "Hello World", Execute(hello))
	uassert.Equal(t, 11, len(Execute(hello)))
}

func TestCompileRejectsUnbalanced(t *testing.T) {
	cases := []string{"[", "]", "[[]", "+[->+<", "][", "[[[]]"}
	for _, src := range cases {
		_, err := CompileDefault(src)
		if err == nil {
			t.Errorf("Compile(%q) should have failed", src)
		}
	}
}

func TestCompileRejectsOversizeSource(t *testing.T) {
	src := "+"
	for len(src) <= MaxSource {
		src += src // doubling, not O(n^2) appending
	}
	_, err := CompileDefault(src)
	uassert.ErrorIs(t, err, ErrSourceTooLong)
}

func TestCompileRejectsUnknownLevel(t *testing.T) {
	_, err := Compile("+", Level(42))
	uassert.Error(t, err)
	_, err = Compile("+", Level(-1))
	uassert.Error(t, err)
}

// TestLadderShrinksTheOpStream is the compile-time half of the ladder: each
// rung has to produce strictly fewer ops than the one below it, or it is not
// buying anything.
func TestLadderShrinksTheOpStream(t *testing.T) {
	jumps, err := Compile(hello, LevelJumps)
	uassert.NoError(t, err)
	fuse, err := Compile(hello, LevelFuse)
	uassert.NoError(t, err)
	idioms, err := Compile(hello, LevelIdioms)
	uassert.NoError(t, err)

	uassert.True(t, jumps.Len() > fuse.Len())
	uassert.True(t, fuse.Len() > idioms.Len())
	uassert.Equal(t, "jumps", jumps.Level().String())
	uassert.Equal(t, hello, idioms.Source())
}

func TestIdiomRecognition(t *testing.T) {
	cases := []struct {
		name string
		src  string
		want int // ops, excluding the trailing halt
	}{
		{"clear", "[-]", 1},                 // opSet
		{"move", "[->+<]", 2},               // opAddMul, opSet
		{"multiply two", "[->++>+++<<]", 3}, // two opAddMul, opSet
		{"scan right", "[>]", 1},            // opScan
		{"scan left", "[<]", 1},             // opScan
	}
	for _, tc := range cases {
		prog, err := Compile(tc.src, LevelIdioms)
		uassert.NoError(t, err)
		if prog == nil {
			continue
		}
		if got := prog.Len() - 1; got != tc.want {
			t.Errorf("%s: %q compiled to %d ops, want %d",
				tc.name, tc.src, got, tc.want)
		}
	}
}

// TestPlusLoopIsNotRewritten pins the conservative half of the rewrite: a
// loop that adds one per iteration still reaches zero by wrapping, but only
// after 256 iterations, and folding it would be a different program. It has
// to stay a real loop.
func TestPlusLoopIsNotRewritten(t *testing.T) {
	prog, err := Compile("[+]", LevelIdioms)
	uassert.NoError(t, err)
	// opJmpZ, opAdd, opJmpNZ, opHalt: untouched.
	uassert.Equal(t, 4, prog.Len())
}

func TestInputThroughTheHost(t *testing.T) {
	// Read three bytes and echo them back.
	const echo3 = ",.,.,."
	h := vmkit.NewTestHost().WithInput([]byte("gno"))
	m, err := Load(echo3)
	uassert.NoError(t, err)
	_, status := m.Step(h, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	uassert.Equal(t, "gno", h.OutString())
}

func TestInputEndsAsZero(t *testing.T) {
	// Past the end of input, `,` yields a zero cell. Without input at all,
	// the naive interpreter would have panicked here.
	h := vmkit.NewTestHost().WithInput([]byte("a"))
	m, err := Load(",.+++++++++++++++++++++++++++++++++++++++++++++++.,+++++++++++++++++++++++++++++++++++++++++++++++++.")
	uassert.NoError(t, err)
	_, status := m.Step(h, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	uassert.Equal(t, "a\x901", h.OutString())
}

func TestExecutePanicsOnInput(cur realm, t *testing.T) {
	// Rung 0's second preserved bug, pinned so nobody "fixes" the baseline.
	uassert.PanicsWithMessage(t, cur, "unsupported", func() { Execute(",") })
}

func TestMachineWithoutProgram(t *testing.T) {
	m := &Machine{status: vmkit.Running}
	used, status := m.Step(vmkit.NewTestHost(), 10)
	uassert.Equal(t, int64(0), used)
	uassert.Equal(t, "trapped", status.String())
	uassert.Equal(t, "no program", m.Trap())
}

package bf

import (
	"errors"

	"gno.land/p/nt/ufmt/v0"
)

// TapeSize is the tape length of a compiled [Machine]. It matches
// [NaiveTapeSize] so that the ladder compares like with like: a rung that
// changed the semantics would not be a rung, it would be a different program.
const TapeSize = 30000

// MaxSource bounds the program a realm will accept. Compilation is linear in
// the source, but the op array and every snapshot of it are consensus state,
// so the size has to be bounded somewhere the caller can see.
const MaxSource = 64 * 1024

// ErrSourceTooLong is returned by [Compile] for a program above [MaxSource].
var ErrSourceTooLong = errors.New("bf: source too long")

// Level selects how far up the optimization ladder [Compile] goes.
//
// Every level produces the same output for the same program: the levels exist
// so the cost of each optimization can be measured in isolation, which is the
// published result this package is really for. Rung 0 of the ladder is
// [Execute] and has no compiler at all.
type Level int

const (
	// LevelJumps is rung 1: one op per source byte, with the jump targets
	// resolved at compile time. This is the rung that kills the brace
	// rescan, which in [Execute] costs O(loop body) on every iteration.
	LevelJumps Level = iota

	// LevelFuse is rung 2: runs of identical operators collapse, so
	// "+++++" is one add-5 and ">>>" is one move-3. Real programs are
	// mostly runs.
	LevelFuse

	// LevelIdioms is rung 3: a loop whose body only moves and adds, and
	// which returns to where it started while decrementing the current
	// cell by one, is replaced by the multiply-adds it performs plus a
	// clear. "[-]" becomes one op, "[->+<]" becomes two.
	LevelIdioms
)

// Default is the level [CompileDefault] uses, and the one a realm should
// want: every optimization this package knows, same semantics.
const Default = LevelIdioms

// String names the level, for the ladder table and for realm output.
func (l Level) String() string {
	switch l {
	case LevelJumps:
		return "jumps"
	case LevelFuse:
		return "fuse"
	case LevelIdioms:
		return "idioms"
	}
	return "unknown"
}

type opcode byte

const (
	opAdd    opcode = iota // tape[p] += arg           (arg normalized to 0..255)
	opMove                 // p += arg
	opOut                  // write tape[p] to the host
	opIn                   // read one input byte into tape[p]
	opJmpZ                 // if tape[p] == 0 { pc = arg }
	opJmpNZ                // if tape[p] != 0 { pc = arg }
	opSet                  // tape[p] = byte(arg)
	opAddMul               // tape[p+off] += tape[p] * byte(arg)
	opScan                 // while tape[p] != 0 { p += arg }
	opHalt                 // end of program
)

// op is one compiled instruction. It is a flat struct on purpose: the
// execution loop indexes an array of these, and an op that owned a slice
// would allocate in the hot path.
type op struct {
	code opcode
	arg  int
	off  int
}

// Program is compiled Brainfuck, ready to run on a [Machine].
type Program struct {
	ops   []op
	src   string
	level Level
}

// Source returns the program text the [Program] was compiled from.
func (p *Program) Source() string { return p.src }

// Level returns the ladder rung this program was compiled at.
func (p *Program) Level() Level { return p.level }

// Len returns the number of compiled ops, including the trailing halt. It is
// the number worth quoting next to the source length: the ratio is exactly
// what the ladder buys.
func (p *Program) Len() int { return len(p.ops) }

// CompileDefault compiles at [Default].
func CompileDefault(src string) (*Program, error) { return Compile(src, Default) }

// Compile turns Brainfuck source into a [Program] at the requested ladder
// level. Everything that is not one of the eight operators is a comment, as
// the language requires.
//
// It fails on unbalanced brackets rather than trusting the runtime to notice,
// which is the first thing that separates it from [Execute]: a malformed
// program is rejected before anybody pays to run it.
func Compile(src string, lvl Level) (*Program, error) {
	if len(src) > MaxSource {
		return nil, ErrSourceTooLong
	}
	if lvl < LevelJumps || lvl > LevelIdioms {
		return nil, ufmt.Errorf("bf: unknown level %d", int(lvl))
	}

	ops := []op{}
	opens := []int{} // pc of each unclosed opJmpZ

	for i := 0; i < len(src); i++ {
		c := src[i]
		switch c {
		case '+', '-':
			delta := 1
			if c == '-' {
				delta = -1
			}
			if lvl >= LevelFuse {
				n := 1
				for i+n < len(src) && (src[i+n] == '+' || src[i+n] == '-') {
					if src[i+n] == '+' {
						delta++
					} else {
						delta--
					}
					n++
				}
				i += n - 1
			}
			if a := normAdd(delta); a != 0 {
				ops = append(ops, op{code: opAdd, arg: a})
			}
		case '>', '<':
			delta := 1
			if c == '<' {
				delta = -1
			}
			if lvl >= LevelFuse {
				n := 1
				for i+n < len(src) && (src[i+n] == '>' || src[i+n] == '<') {
					if src[i+n] == '>' {
						delta++
					} else {
						delta--
					}
					n++
				}
				i += n - 1
			}
			if d := normMove(delta); d != 0 {
				ops = append(ops, op{code: opMove, arg: d})
			}
		case '.':
			ops = append(ops, op{code: opOut})
		case ',':
			ops = append(ops, op{code: opIn})
		case '[':
			opens = append(opens, len(ops))
			ops = append(ops, op{code: opJmpZ})
		case ']':
			if len(opens) == 0 {
				return nil, ufmt.Errorf("bf: unmatched ']' at byte %d", i)
			}
			open := opens[len(opens)-1]
			opens = opens[:len(opens)-1]

			if lvl >= LevelIdioms {
				if idiom, ok := simpleLoop(ops[open+1:]); ok {
					ops = append(ops[:open], idiom...)
					continue
				}
			}
			// pc lands on the op after the jump, so a jump target is
			// the index of the partner op itself.
			ops = append(ops, op{code: opJmpNZ, arg: open})
			ops[open].arg = len(ops) - 1
		}
	}
	if len(opens) != 0 {
		return nil, ufmt.Errorf("bf: %d unmatched '['", len(opens))
	}

	ops = append(ops, op{code: opHalt})
	return &Program{ops: ops, src: src, level: lvl}, nil
}

// normAdd folds a signed delta into the 0..255 the byte tape actually sees,
// so the execution loop never has to convert a negative int to a byte.
func normAdd(d int) int {
	d %= 256
	if d < 0 {
		d += 256
	}
	return d
}

// normMove folds a pointer delta into one lap of the tape. Moving right
// TapeSize times is a no-op on a wrapping tape, in the naive interpreter as
// much as here, so collapsing it changes nothing but the op count.
func normMove(d int) int {
	d %= TapeSize
	if d < 0 {
		d += TapeSize
	}
	if d > TapeSize/2 {
		d -= TapeSize
	}
	return d
}

// cell is one offset the body of a simple loop writes to.
type cell struct {
	off   int
	delta int
}

// simpleLoop decides whether a loop body can be replaced by straight-line
// code, and returns that code.
//
// Two shapes qualify, and they are the two that dominate real programs:
//
//   - The body only moves, and ends somewhere other than where it started:
//     that is a scan, "[>]" walking to the next zero cell.
//   - The body only moves and adds, ends where it started, and takes exactly
//     one off the current cell: that is a multiply-add. The loop runs
//     tape[p] times, so every other cell it touches gains its delta times
//     tape[p], and the current cell ends at zero. "[-]" is the degenerate
//     case with no other cells.
//
// Anything else, including any body containing I/O or a nested loop that was
// itself rewritten, is left alone. Being conservative here costs a few ops in
// rare programs and is the only reason this rewrite is safe at all: a loop
// whose current cell does not reach zero in steps of one is not guaranteed to
// terminate, and constant-folding it would change the program.
func simpleLoop(body []op) ([]op, bool) {
	cursor := 0
	cells := []cell{}
	adds := 0

	for _, o := range body {
		switch o.code {
		case opMove:
			cursor += o.arg
		case opAdd:
			adds++
			// Carry the delta as a signed value; it is normalized
			// back into 0..255 when it is emitted.
			d := o.arg
			if d > 128 {
				d -= 256
			}
			cells = addCell(cells, cursor, d)
		default:
			return nil, false
		}
	}

	if cursor != 0 {
		// Net movement: only a pure scan qualifies, and only when the
		// step is not zero (which normMove already guarantees here).
		if adds != 0 {
			return nil, false
		}
		return []op{{code: opScan, arg: cursor}}, true
	}

	// Balanced. The current cell must fall by exactly one per iteration,
	// or the loop is not a counted multiply-add.
	if delta(cells, 0) != -1 {
		return nil, false
	}

	out := []op{}
	for _, c := range cells {
		if c.off == 0 || c.delta == 0 {
			continue
		}
		out = append(out, op{code: opAddMul, arg: normAdd(c.delta), off: c.off})
	}
	out = append(out, op{code: opSet, arg: 0})
	return out, true
}

// addCell accumulates a delta at an offset, keeping cells sorted by offset so
// that the op stream a program compiles to is identical on every node.
func addCell(cells []cell, off, d int) []cell {
	for i := range cells {
		if cells[i].off == off {
			cells[i].delta += d
			return cells
		}
		if cells[i].off > off {
			cells = append(cells, cell{})
			copy(cells[i+1:], cells[i:])
			cells[i] = cell{off: off, delta: d}
			return cells
		}
	}
	return append(cells, cell{off: off, delta: d})
}

func delta(cells []cell, off int) int {
	for _, c := range cells {
		if c.off == off {
			return c.delta
		}
	}
	return 0
}

package bf

import (
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// heavy is the benchmark program: 200 increments, then an outer loop that on
// each of its 200 iterations moves right, adds 200, clears that cell with the
// "[-]" idiom, and moves back.
//
// It writes nothing, so a measurement of it is a measurement of the dispatch
// loop and not of the output path.
var heavy = rep("+", 200) + "[" + "-" + ">" + rep("+", 200) + "[-]" + "<" + "]"

// GuestOps and NaiveDispatches are the two counts for [heavy], and the
// difference between them is the reason the ladder needs both named.
//
// A guest instruction is one operator the language executes, counted the way
// any jump-table interpreter counts it. The naive interpreter dispatches more
// often than that for the same program: its "]" handler scans back to the
// matching "[" and lands on it, so "[" is re-evaluated on every iteration of
// every loop. On heavy that is 1.33 dispatches per guest instruction.
//
// Rung 1 removes exactly that excess, so a ladder that used the naive
// dispatch count as its denominator would be crediting rung 1 twice. Both
// numbers come from an independent simulator, not from this package, so the
// denominator is not derived from the thing being measured.
const (
	GuestOps        = 121201
	NaiveDispatches = 161200
)

func rep(s string, n int) string {
	out := ""
	for i := 0; i < n; i++ {
		out += s
	}
	return out
}

// nullHost is a Host that costs as close to nothing as a Host can, so the
// ladder measures the dispatch loop rather than the storage or output path.
type nullHost struct{}

func (nullHost) Caller() address                     { return address("") }
func (nullHost) Origin() address                     { return address("") }
func (nullHost) Now() int64                          { return 0 }
func (nullHost) Height() int64                       { return 0 }
func (nullHost) Get(key []byte) []byte               { return nil }
func (nullHost) Set(key, val []byte)                 {}
func (nullHost) Input() []byte                       { return nil }
func (nullHost) Output(p []byte)                     {}
func (nullHost) Emit(typ string, kv ...string)       {}
func (nullHost) Send(to address, amount int64) error { return vmkit.ErrNotGranted }
func (nullHost) Log(msg string)                      {}

// runHeavy compiles heavy at lvl and runs it on the shipped machine,
// returning how many machine ops it executed. The count is the fuel the
// machine charged itself, so the ladder's "machine ops" column is measured by
// the machine and not counted by hand.
func runHeavy(t *testing.T, lvl Level) int64 {
	t.Helper()
	prog, err := Compile(heavy, lvl)
	uassert.NoError(t, err)
	if prog == nil {
		return 0
	}
	m := NewMachine(prog)
	used, status := m.Step(nullHost{}, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	return used
}

// The rungs. One test each, so `gno test -print-runtime-metrics` prints one
// cycle count per rung and the README's table is a transcription rather than
// an estimate. They assert that the run completed and how many machine ops it
// took: what is being recorded is the metric line.

func TestRung0Naive(t *testing.T) {
	uassert.Equal(t, "", Execute(heavy))
}

func TestRung0Naive4x(t *testing.T) {
	for i := 0; i < 4; i++ {
		Execute(heavy)
	}
}

func TestRung1Jumps(t *testing.T) {
	uassert.Equal(t, int64(GuestOps+1), runHeavy(t, LevelJumps))
}

func TestRung2Fuse(t *testing.T) {
	uassert.True(t, runHeavy(t, LevelFuse) < GuestOps)
}

func TestRung3Idioms(t *testing.T) {
	uassert.True(t, runHeavy(t, LevelIdioms) < GuestOps)
}

func TestRung3Idioms4x(t *testing.T) {
	for i := 0; i < 4; i++ {
		runHeavy(t, LevelIdioms)
	}
}

func TestRung5Metered(t *testing.T) {
	// Same program, same rung, but every op goes through the fuel meter's
	// budget branch instead of its unmetered one. The delta against
	// TestRung3Idioms is the price of being a machine that can be stopped.
	prog, err := Compile(heavy, LevelIdioms)
	uassert.NoError(t, err)
	m := NewMachine(prog)
	_, status := m.Step(nullHost{}, 1<<40)
	uassert.Equal(t, "halted", status.String())
}

// TestLadderOpCounts records the compile-time half of the ladder: how many
// machine ops each rung executes for the same 121,201 guest instructions.
// These are the numbers the README's table quotes, asserted here so the table
// cannot silently go stale.
func TestLadderOpCounts(t *testing.T) {
	jumps := runHeavy(t, LevelJumps)
	fuse := runHeavy(t, LevelFuse)
	idioms := runHeavy(t, LevelIdioms)

	// Rung 1 executes exactly one machine op per guest instruction, plus
	// the halt: the independent simulator and this machine agree to the op.
	uassert.Equal(t, int64(121202), jumps)
	// Fusing runs of + and > collapses the two 200-long runs.
	uassert.Equal(t, int64(81203), fuse)
	// Recognizing "[-]" turns the inner clear loop into a single op.
	uassert.Equal(t, int64(1203), idioms)

	uassert.True(t, fuse < jumps)
	uassert.True(t, idioms < fuse)
}

package bf

import (
	"errors"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/vm/vmkit/v0"
)

// VMName is the identifier this machine registers under in a
// [vmkit.Instance].
const VMName = "bf"

// snapMagic and snapVersion tag a snapshot so a machine refuses bytes that
// were not written by this machine at this version, instead of decoding them
// into a plausible-looking wrong state.
const (
	snapMagic   uint32 = 0x62660001 // "bf" 0001
	snapVersion byte   = 1
)

// ErrNoProgram is returned when a [Machine] is stepped without a program.
var ErrNoProgram = errors.New("bf: machine has no program")

// Machine is a compiled Brainfuck program, mid-execution: a
// [vmkit.Machine] with a fixed tape, a fuel-metered step loop, input and
// output through the host, and a snapshot small enough that pausing is
// cheaper than starting over.
//
// The tape is a fixed-size array rather than a slice: that is rung 4 of the
// ladder, and the README reports what it actually bought.
type Machine struct {
	prog *Program

	tape  [TapeSize]byte
	ptr   int
	pc    int
	inPos int // read cursor into Host.Input, carried across slices

	status vmkit.Status
	trap   string

	// hi is the highest tape index written so far, so a snapshot can stop
	// there instead of carrying 30,000 bytes of zeros.
	hi int
}

// NewMachine returns a machine ready to run prog from the start.
func NewMachine(prog *Program) *Machine {
	return &Machine{prog: prog, status: vmkit.Running}
}

// Load compiles src at [Default] and returns a machine for it.
func Load(src string) (*Machine, error) {
	prog, err := CompileDefault(src)
	if err != nil {
		return nil, err
	}
	return NewMachine(prog), nil
}

// Program returns the program the machine is running.
func (m *Machine) Program() *Program { return m.prog }

// Status returns the machine's current status.
func (m *Machine) Status() vmkit.Status { return m.status }

// Trap returns the reason the machine trapped, or "". It makes Machine a
// [vmkit.Trapper].
func (m *Machine) Trap() string { return m.trap }

// Pointer returns the tape pointer.
func (m *Machine) Pointer() int { return m.ptr }

// PC returns the index of the next op to execute.
func (m *Machine) PC() int { return m.pc }

// Cell returns the tape byte at i, wrapped into range.
func (m *Machine) Cell(i int) byte { return m.tape[wrap(i)] }

// Touched returns how many tape cells the program has reached, which is the
// length a snapshot has to carry.
func (m *Machine) Touched() int { return m.hi + 1 }

// Step runs until the program halts, traps, or spends `fuel` units, charging
// one unit per op executed and one per cell a scan walks over. Pass
// [vmkit.Unmetered] to run to completion.
//
// Fuel is charged before the op runs, so a machine that stops for lack of
// fuel has not half-executed anything: it is exactly at the op it could not
// pay for, and resuming re-executes that op and nothing else.
//
// Three things in here are written the way they are because the alternative
// was measured and lost. The README has the table.
//
//   - The fuel counter is two locals, not a [vmkit.Meter]. Calling
//     Meter.Charge once per instruction costs 86% on top of the whole
//     dispatch loop and triples the allocation count. Meter stays the type
//     at the API boundary, where it is called once; it is not a hot-path
//     type, and no guest VM should treat it as one.
//   - The program counter and the tape pointer are locals, written back once
//     by the deferred closure. Reaching through m. for them on every
//     instruction costs 16%.
//   - The pc range check happens once, before the loop, not per op. Every
//     jump target is produced by [Compile] and every restored pc is
//     validated by [Machine.Restore], so per-op checking buys nothing.
func (m *Machine) Step(h vmkit.Host, fuel int64) (int64, vmkit.Status) {
	if m.prog == nil {
		m.status, m.trap = vmkit.Trapped, "no program"
		return 0, m.status
	}
	if m.status != vmkit.Running {
		return 0, m.status
	}

	ops := m.prog.ops
	pc, ptr, hi := m.pc, m.ptr, m.hi
	// One write-back, on every return path, including a panic.
	defer func() { m.pc, m.ptr, m.hi = pc, ptr, hi }()

	if pc < 0 || pc >= len(ops) {
		m.status, m.trap = vmkit.Trapped, "pc out of range"
		return 0, m.status
	}

	// budget < 0 is vmkit.Unmetered.
	budget := fuel
	if budget < 0 {
		budget = vmkit.Unmetered
	}
	var used int64

	for {
		if budget != vmkit.Unmetered && used >= budget {
			return used, vmkit.Running
		}
		used++

		switch ops[pc].code {
		case opAdd:
			m.tape[ptr] += byte(ops[pc].arg)
		case opMove:
			ptr = wrap(ptr + ops[pc].arg)
			if ptr > hi {
				hi = ptr
			}
		case opSet:
			m.tape[ptr] = byte(ops[pc].arg)
		case opAddMul:
			if v := m.tape[ptr]; v != 0 {
				t := wrap(ptr + ops[pc].off)
				m.tape[t] += v * byte(ops[pc].arg)
				if t > hi {
					hi = t
				}
			}
		case opScan:
			// A scan is charged per cell, so it cannot be a way to
			// buy unbounded work for one unit of fuel. Stopping
			// mid-scan is safe: the pointer has moved, the pc has
			// not, so resuming continues the same walk.
			for m.tape[ptr] != 0 {
				if budget != vmkit.Unmetered && used >= budget {
					return used, vmkit.Running
				}
				used++
				ptr = wrap(ptr + ops[pc].arg)
				if ptr > hi {
					hi = ptr
				}
			}
		case opOut:
			h.Output([]byte{m.tape[ptr]})
		case opIn:
			in := h.Input()
			if m.inPos < len(in) {
				m.tape[ptr] = in[m.inPos]
				m.inPos++
			} else {
				// End of input is a zero cell, the most common
				// of the three conventions the language never
				// settled.
				m.tape[ptr] = 0
			}
		case opJmpZ:
			if m.tape[ptr] == 0 {
				pc = ops[pc].arg
			}
		case opJmpNZ:
			if m.tape[ptr] != 0 {
				pc = ops[pc].arg
			}
		case opHalt:
			m.status = vmkit.Halted
			return used, m.status
		default:
			m.status, m.trap = vmkit.Trapped, "unknown opcode"
			return used, m.status
		}
		pc++
	}
}

// Snapshot serializes the machine. The tape is truncated at the highest cell
// the program has reached, which is what makes pausing affordable: a hello
// world that touched six cells snapshots six bytes of tape, not 30,000.
func (m *Machine) Snapshot() []byte {
	w := vmkit.NewWriter(m.hi + 48)
	w.Uint32(snapMagic)
	w.Byte(snapVersion)
	w.Int(int64(m.pc))
	w.Int(int64(m.ptr))
	w.Int(int64(m.inPos))
	w.Byte(byte(m.status))
	w.String(m.trap)

	n := m.hi + 1
	if n > TapeSize {
		n = TapeSize
	}
	w.Bytes(m.tape[:n])
	return w.Out()
}

// Restore loads a snapshot into a machine that already carries the program
// the snapshot was taken from. The program is not in the snapshot: a realm
// stores it once, beside the instance, instead of once per pause.
func (m *Machine) Restore(b []byte) error {
	r := vmkit.NewReader(b)
	if r.Uint32() != snapMagic {
		return vmkit.ErrBadSnapshot
	}
	if r.Byte() != snapVersion {
		return vmkit.ErrBadSnapshot
	}
	pc := int(r.Int())
	ptr := int(r.Int())
	inPos := int(r.Int())
	status := vmkit.Status(r.Byte())
	trap := r.String()
	tape := r.Bytes()
	if err := r.Err(); err != nil {
		return err
	}
	if len(tape) > TapeSize || ptr < 0 || ptr >= TapeSize || inPos < 0 {
		return vmkit.ErrBadSnapshot
	}
	if m.prog != nil && (pc < 0 || pc > len(m.prog.ops)) {
		return vmkit.ErrBadSnapshot
	}

	m.pc, m.ptr, m.inPos = pc, ptr, inPos
	m.status, m.trap = status, trap
	// Zero only what this machine could have written: hi bounds every
	// write it has made, and a 30,000 element composite literal is not
	// something to put in a restore path.
	for i := 0; i <= m.hi && i < TapeSize; i++ {
		m.tape[i] = 0
	}
	copy(m.tape[:], tape)
	m.hi = len(tape) - 1
	if m.hi < 0 {
		m.hi = 0
	}
	return nil
}

// Run compiles src at [Default] and runs it to completion against h, with no
// fuel bound. It is the one-shot path: convenient for a test or a small
// program, and exactly the thing a realm should not do with untrusted input.
func Run(src string, h vmkit.Host) (vmkit.Status, error) {
	m, err := Load(src)
	if err != nil {
		return vmkit.Trapped, err
	}
	_, status := m.Step(h, vmkit.Unmetered)
	return status, nil
}

// wrap folds a tape index into range, the way the naive interpreter does one
// step at a time.
func wrap(i int) int {
	i %= TapeSize
	if i < 0 {
		i += TapeSize
	}
	return i
}

package bf

import (
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// oneShot runs src to completion and returns what it wrote.
func oneShot(t *testing.T, src string) string {
	t.Helper()
	h := vmkit.NewTestHost()
	status, err := Run(src, h)
	uassert.NoError(t, err)
	uassert.Equal(t, "halted", status.String())
	return h.OutString()
}

// TestSlicedRunEqualsOneShot is the property that makes a guest program a
// contract rather than a function call: chopping the execution into fuel
// slices, snapshotting between each, must produce exactly the single run.
func TestSlicedRunEqualsOneShot(t *testing.T) {
	for _, slice := range []int64{1, 2, 7, 64} {
		prog, err := CompileDefault(hello)
		uassert.NoError(t, err)

		h := vmkit.NewTestHost()
		snap := []byte(nil)
		status := vmkit.Running
		slices := 0
		for status == vmkit.Running && slices < 10000 {
			m := NewMachine(prog) // a realm holds bytes, not a machine
			if snap != nil {
				uassert.NoError(t, m.Restore(snap))
			}
			_, status = m.Step(h, slice)
			snap = m.Snapshot()
			slices++
		}
		uassert.Equal(t, "halted", status.String())
		uassert.Equal(t, "Hello World", h.OutString())
	}
}

func TestSlicedRunAgreesAcrossTheCorpus(t *testing.T) {
	for _, tc := range corpus {
		prog, err := CompileDefault(tc.src)
		uassert.NoError(t, err)
		if prog == nil {
			continue
		}
		h := vmkit.NewTestHost()
		snap := []byte(nil)
		status := vmkit.Running
		n := 0
		for status == vmkit.Running && n < 20000 {
			m := NewMachine(prog)
			if snap != nil {
				uassert.NoError(t, m.Restore(snap))
			}
			_, status = m.Step(h, 3)
			snap = m.Snapshot()
			n++
		}
		if h.OutString() != tc.want {
			t.Errorf("%s sliced: got %q, want %q", tc.name, h.OutString(), tc.want)
		}
	}
}

func TestFuelStopsTheMachine(t *testing.T) {
	prog, err := CompileDefault(hello)
	uassert.NoError(t, err)
	m := NewMachine(prog)
	h := vmkit.NewTestHost()

