// Package wrapped is an accounting-only port of Wrapped Ether (WETH).
//
// The canonical WETH contract lets anyone lock native ETH and mint a 1:1
// ERC-20 representation (and burn it back). On gno.land / sapphire there is no
// msg.value / payable, so there is NO real coin transfer here: Deposit and
// Withdraw are pure accounting operations that model the wrap/unwrap. Balances
// and totalSupply are plain uint64 ledgers kept in an avl.Tree.
package wrapped

import (
	"strconv"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// balances maps owner address (string) -> wrapped balance (uint64).
var (
	balances    avl.Tree
	totalSupply uint64
)

// Deposit wraps `amount` units of the (notional) native coin, crediting the
// caller's wrapped balance and the global totalSupply. Accounting only: no real
// coin ever moves — it models locking native funds to mint the wrapped token.
func Deposit(cur realm, amount uint64) {
	if amount == 0 {
		panic("wrapped: deposit amount must be > 0")
	}
	owner := unsafe.PreviousRealm().Address()
	setBalance(owner, balanceOf(owner)+amount)
	totalSupply += amount
	chain.Emit("Deposit", "dst", owner.String(), "wad", strconv.FormatUint(amount, 10))
}

// Withdraw unwraps `amount` units, burning them from the caller's balance and
// from totalSupply. Panics if the caller lacks the balance.
func Withdraw(cur realm, amount uint64) {
	if amount == 0 {
		panic("wrapped: withdraw amount must be > 0")
	}
	owner := unsafe.PreviousRealm().Address()
	bal := balanceOf(owner)
	if bal < amount {
		panic("wrapped: insufficient balance")
	}
	setBalance(owner, bal-amount)
	totalSupply -= amount
	chain.Emit("Withdrawal", "src", owner.String(), "wad", strconv.FormatUint(amount, 10))
}

// Transfer moves `amount` wrapped units from the caller to `to`.
func Transfer(cur realm, to address, amount uint64) {
	if amount == 0 {
		panic("wrapped: transfer amount must be > 0")
	}
	from := unsafe.PreviousRealm().Address()
	if from == to {
		panic("wrapped: cannot transfer to self")
	}
	fromBal := balanceOf(from)
	if fromBal < amount {
		panic("wrapped: insufficient balance")
	}
	setBalance(from, fromBal-amount)
	setBalance(to, balanceOf(to)+amount)
	chain.Emit("Transfer", "src", from.String(), "dst", to.String(), "wad", strconv.FormatUint(amount, 10))
}

// balanceOf returns the wrapped balance of `owner` (read-only, not crossing).
func balanceOf(owner address) uint64 {
	v := balances.Get(owner.String())
	if v == nil {
		return 0
	}
	return v.(uint64)
}

// BalanceOf is the exported read-only accessor for a single owner.
func BalanceOf(owner address) uint64 { return balanceOf(owner) }

// TotalSupply returns the total amount of wrapped units in existence.
func TotalSupply() uint64 { return totalSupply }

func setBalance(owner address, amount uint64) {
	if amount == 0 {
		balances.Remove(owner.String())
		return
	}
	balances.Set(owner.String(), amount)
}

// ---- pure/read-only helpers (unit-tested) ----

// canDebit reports whether `bal` can cover `amount` for a burn/transfer.
func canDebit(bal, amount uint64) bool {
	return amount > 0 && bal >= amount
}

// formatUnits renders a raw uint64 amount as a decimal string.
func formatUnits(n uint64) string {
	return strconv.FormatUint(n, 10)
}

// Render shows the total supply and a table of non-zero balances.
func Render(path string) string {
	out := "# Wrapped (WETH-style, accounting-only)\n\n"
	out += "Deposit mints wrapped units, Withdraw burns them. No real coins move — this is a pure ledger.\n\n"
	out += "**Total supply:** " + formatUnits(totalSupply) + "\n\n"

	if balances.Size() == 0 {
		out += "_No balances yet. Call `Deposit` to wrap some units._\n"
		return out
	}

	out += "| Owner | Balance |\n|---|---:|\n"
	balances.Iterate("", "", func(key string, value interface{}) bool {
		out += "| `" + key + "` | " + formatUnits(value.(uint64)) + " |\n"
		return false
	})
	return out
}

package wrapped

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestCanDebit(t *testing.T) {
	uassert.True(t, canDebit(100, 40), "bal covers amount")
	uassert.True(t, canDebit(50, 50), "exact balance is debitable")
	uassert.False(t, canDebit(10, 20), "amount exceeds balance")
	uassert.False(t, canDebit(100, 0), "zero amount is never debitable")
	uassert.False(t, canDebit(0, 1), "empty balance cannot be debited")
}

func TestFormatUnits(t *testing.T) {
	uassert.Equal(t, "0", formatUnits(0))
	uassert.Equal(t, "1", formatUnits(1))
	uassert.Equal(t, "1000000", formatUnits(1_000_000))
}

// Package grc20faucet issues two free GRC20 tokens, RED and BLUE, and gives
// them away on request.
//
// It exists so that anything needing a token to experiment on has one that is
// worthless, unlimited and shared. Both tokens are registered in
// gno.land/r/nt/grc20reg/v0, which is what lets another realm find and move
// them by key without importing this package: that indirection is the whole
// point, and it is what gno.land/r/moul/x/grc20wrapdemo/v0 wraps.
//
// Two tokens rather than one, because the interesting patterns start at two: a
// meta-token over a pair needs a pair.
package grc20faucet

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Tokens are exported so an importing realm can read them directly; the
// ledgers stay private, since they carry unrestricted mint and burn.
var (
	Red  *grc20.Token
	Blue *grc20.Token

	redLedger  *grc20.PrivateLedger
	blueLedger *grc20.PrivateLedger

	// RedKey and BlueKey are the grc20reg lookup keys, the way a realm that
	// does NOT import this package refers to these tokens.
	RedKey  string
	BlueKey string

	lastClaim = avl.NewTree() // address -> block height of its last claim
)

const (
	decimals = 4

	// ClaimAmount is minted of EACH token per claim: 100.0000 units.
	ClaimAmount = int64(1_000_000)

	// ClaimEvery is the cooldown, in blocks, between two claims by the same
	// account. Free money with no cooldown is a spam vector, not a faucet.
	ClaimEvery = int64(100)
)

func init(cur realm) {
	Red, redLedger = grc20.NewToken("Red Token", "RED", decimals, 0, cur)
	Blue, blueLedger = grc20.NewToken("Blue Token", "BLUE", decimals, 1, cur)
	RedKey = grc20reg.Register(cross(cur), Red, "red")
	BlueKey = grc20reg.Register(cross(cur), Blue, "blue")
}

// Claim mints ClaimAmount of both RED and BLUE to the caller.
func Claim(cur realm) {
	who := caller(cur)
	now := runtime.ChainHeight()
	if next, ok := NextClaim(who); ok && now < next {
		panic(ufmt.Sprintf("too soon: next claim at block %d, current %d", next, now))
	}
	lastClaim.Set(who.String(), now)
	checkErr(redLedger.Mint(who, ClaimAmount))
	checkErr(blueLedger.Mint(who, ClaimAmount))
}

// NextClaim returns the block height at which `who` may claim again, and
// whether they have ever claimed at all.
func NextClaim(who address) (int64, bool) {
	v := lastClaim.Get(who.String())
	if v == nil {
		return 0, false
	}
	return v.(int64) + ClaimEvery, true
}

// Transfer moves the caller's own units of `symbol`.
func Transfer(cur realm, symbol string, to address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().Transfer(0, cur, to, amount))
}

// Approve lets `spender` draw `amount` of `symbol` from the caller's balance.
//
// This is the call that makes every wrapper in grc20wrapdemo work: the wrapper
// realm has no authority over anybody's tokens until its address is named here.
func Approve(cur realm, symbol string, spender address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().Approve(0, cur, spender, amount))
}

// TransferFrom spends an allowance the caller was granted.
func TransferFrom(cur realm, symbol string, from, to address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().TransferFrom(0, cur, from, to, amount))
}

// BalanceOf returns `owner`'s balance of `symbol`.
func BalanceOf(symbol string, owner address) int64 {
	return tokenOf(symbol).BalanceOf(owner)
}

// Allowance returns what `owner` let `spender` draw of `symbol`.
func Allowance(symbol string, owner, spender address) int64 {
	return tokenOf(symbol).Allowance(owner, spender)
}

// TotalSupply returns how much of `symbol` has been claimed so far.
func TotalSupply(symbol string) int64 {
	return tokenOf(symbol).TotalSupply()
}

func tokenOf(symbol string) *grc20.Token {
	switch symbol {
	case "RED":
		return Red
	case "BLUE":
		return Blue
	}
	panic("unknown symbol " + symbol + " (RED or BLUE)")
}

func ledgerOf(symbol string) *grc20.PrivateLedger {
	switch symbol {
	case "RED":
		return redLedger
	case "BLUE":
		return blueLedger
	}
	panic("unknown symbol " + symbol + " (RED or BLUE)")
}

// caller is the account or realm that crossed into this one.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("grc20faucet: stale realm token")
	}
	return cur.Previous().Address()
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

func Render(path string) string {
	s := "# GRC20 faucet: RED and BLUE\n\n"
	s += "Two worthless tokens to experiment on. `Claim` gives you "
	s += ufmt.Sprintf("%d of each, once every %d blocks.\n\n", ClaimAmount, ClaimEvery)

	s += "| token | symbol | decimals | supply | registry key |\n"
	s += "|---|---|---|---|---|\n"
	s += ufmt.Sprintf("| %s | RED | %d | %d | `%s` |\n",
		Red.GetName(), Red.GetDecimals(), Red.TotalSupply(), RedKey)
	s += ufmt.Sprintf("| %s | BLUE | %d | %d | `%s` |\n",
		Blue.GetName(), Blue.GetDecimals(), Blue.TotalSupply(), BlueKey)

	s += "\n## Use it\n\n"
	s += "```\n"
	s += "gnokey maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Claim ...\n"
	s += "gnokey maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Approve \\\n"
	s += "  -args RED -args <spender> -args 1000000 ...\n"
	s += "```\n\n"
	s += "Both tokens are registered in [grc20reg](/r/nt/grc20reg/v0), so a realm can\n"
	s += "move them by key without importing this one. That is what\n"
	s += "[grc20wrapdemo](/r/moul/x/grc20wrapdemo/v0) does with them.\n"

	if path != "" {
		s += "\n---\n\n"
		s += ufmt.Sprintf("Balance of `%s`: RED %d, BLUE %d\n",
			path, Red.BalanceOf(address(path)), Blue.BalanceOf(address(path)))
	}
	return s
}

// Package aaa is a throwaway GRC20 with an open faucet, used to exercise the
// pair instances in this repo. It has no value and no owner controls.
package aaa

import (
	"gno.land/p/nt/grc20/v0"
	"gno.land/r/nt/grc20reg/v0"
)

var (
	Token         *grc20.Token
	privateLedger *grc20.PrivateLedger
	userTeller    grc20.Teller
)

// Key is this token's grc20reg key, the string an instance realm is
// configured with.
const Key = "gno.land/r/moul/x/pairs/aaa/v0.AAA"

func init(cur realm) {
	Token, privateLedger = grc20.NewToken("Test Alpha", "AAA", 6, 0, cur)
	userTeller = privateLedger.CallerTeller()
	grc20reg.Register(cross(cur), Token, "")
}

// Faucet mints a fixed amount to the caller. Unrestricted on purpose.
func Faucet(cur realm) {
	if err := privateLedger.Mint(cur.Previous().Address(), 1_000_000_000); err != nil {
		panic(err)
	}
}

func TotalSupply() int64                      { return userTeller.TotalSupply() }
func BalanceOf(owner address) int64           { return userTeller.BalanceOf(owner) }
func Allowance(owner, spender address) int64  { return userTeller.Allowance(owner, spender) }

func Transfer(cur realm, to address, amount int64) {
	if err := userTeller.Transfer(0, cur, to, amount); err != nil {
		panic(err)
	}
}

func Approve(cur realm, spender address, amount int64) {
	if err := userTeller.Approve(0, cur, spender, amount); err != nil {
		panic(err)
	}
}

func Render(string) string {
	return "# AAA\n\nThrowaway test token for the pair instances. `Faucet` mints 1000 AAA to you.\n"
}

package pairreg

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// The not-found branch echoes the visitor's URL path into a code span. Built by
// hand, a backtick in the path closed the span early and everything after it
// rendered as markdown on a gno.land page. md.InlineCode sizes the fence past
// any backtick run in the content, so the payload must come back wrapped in a
// DOUBLE fence, with the backtick intact inside it. Asserting on the payload
// itself rather than on any double fence in the page: an earlier version of
// this test passed on an unrelated span elsewhere in the output.
func TestRenderPathCannotEscapeItsCodeSpan(t *testing.T) {
	out := Render("/a`b")
	fenced := strings.Contains(out, "``a`b``") || strings.Contains(out, "``/a`b``")
	uassert.True(t, fenced,
		"the fence did not outscan the caller's backtick, so the span closes early")
}

// Package pairreg is the registry every AMM pair instance announces itself to,
// and the unified frontend over all of them.
//
// It is the third artifact of the instance-per-realm pattern: one shared
// p/moul/x/pair/v0 holding the logic, N tiny realms holding one pair each, and
// this realm knowing all of them.
//
// # Why registration cannot be faked, and code cannot be trusted
//
// Register keys an instance by cur.Previous().PkgPath(), which the runtime
// supplies, so an instance cannot claim a path that is not its own. That is
// the whole on-chain guarantee. It is NOT a guarantee about the code at that
// path: gno has no way to read another package's source from inside a realm,
// so nothing here can check that an instance really runs the shared template.
// The mirror image of Ethereum's CREATE2, which proves the code and says
// nothing legible about who deployed it.
//
// Consequences a reader of the index must keep in mind:
//
//   - Reserves shown here are CLAIMED. They are read live from the instance's
//     own struct, which is honest for an instance running the template and
//     arbitrary for one that does not.
//   - Several instances may exist for the same token couple. That is allowed
//     on purpose; there is no canonical pair and no factory to enforce one.
//   - Approving tokens to an instance risks exactly what was approved. Read
//     the instance's source (vm/qfile on its path) before funding it.
//
// # Why the registry can read live state at all
//
// Instances register a *pair.Pair pointer, not an address, the way grc20reg
// registers a *grc20.Token. One vm/qrender here therefore renders the real
// state of every instance, with no indexer and no multicall. It is safe
// because pair.Pair holds only concrete types: an interface or a func field
// would let a hostile instance hand foreign code to this realm's frame.
package pairreg

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/pair/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Entry is one registered instance.
type Entry struct {
	Path   string     // the instance realm's package path, supplied by the runtime
	Pair   *pair.Pair // live pointer into the instance's own storage
	Height int64      // chain height at registration
}

// entries maps instance path -> *Entry. couples maps a pair ID
// ("keyA~keyB") -> int, how many instances claim that couple.
var (
	entries avl.Tree
	couples avl.Tree
)

// Register records the calling realm as an instance. Call it from the
// instance's init, so that deploying and listing are one transaction:
//
//	func init(cur realm) {
//		p = pair.New(keyA, keyB, grc20reg.MustGet(keyA), grc20reg.MustGet(keyB))
//		pairreg.Register(cross(cur), p)
//	}
//
// Permissionless by design: anyone may deploy an instance under their own
// address namespace and land here. Spam is self funded, since the registering
// transaction pays for the storage it adds.
func Register(cur realm, p *pair.Pair) {
	caller := cur.Previous()
	path := caller.PkgPath()
	if path == "" {
		panic("pairreg: only a realm can register")
	}
	if p == nil {
		panic("pairreg: nil pair")
	}
	if entries.Has(path) {
		panic("pairreg: already registered: " + path)
	}

	entries.Set(path, &Entry{Path: path, Pair: p, Height: runtime.ChainHeight()})
	couples.Set(p.ID(), countFor(p.ID())+1)

	chain.Emit("RegisterPair",
		"path", path,
		"pair", p.ID(),
	)
}

// Get returns the entry for an instance path, or nil.
func Get(path string) *Entry {
	v := entries.Get(path)
	if v == nil {
		return nil
	}
	return v.(*Entry)
}

// Size returns how many instances are registered.
func Size() int { return entries.Size() }

// Couples returns how many distinct token couples are represented.
func Couples() int { return couples.Size() }

// InstancesFor returns the instance paths claiming a given couple id.
func InstancesFor(id string) []string {
	out := []string{}
	entries.Iterate("", "", func(_ string, value any) bool {
		e := value.(*Entry)
		if e.Pair.ID() == id {
			out = append(out, e.Path)
		}
		return false
	})
	return out
}

// Render is the unified frontend: the index of every instance with its live
// state, or one instance's own page when path is an instance path.
func Render(path string) string {
	if path != "" {
		e := Get(path)
		if e == nil {
			return "# 404\n\nNo instance registered at " + md.InlineCode(path) + ".\n"
		}
		out := e.Pair.Render("")
		out += "\n---\n\n"
		out += ufmt.Sprintf("Instance: [`%s`](%s) · registered at height %d · %d instance(s) claim this couple.\n",
			e.Path, webPath(e.Path), e.Height, countFor(e.Pair.ID()))
		return out
	}

	out := "# AMM pairs\n\n"
	out += "One realm per token couple, all running [p/moul/x/pair/v0](/p/moul/x/pair/v0). "
	out += "Anyone can deploy one under their own namespace and it lands here.\n\n"

	if entries.Size() == 0 {
		out += "_No instance yet._\n"
		return out
	}

	out += ufmt.Sprintf("%d instance(s), %d couple(s).\n\n", entries.Size(), couples.Size())
	out += "**Reserves below are claimed by each instance, not verified.** "
	out += "Nothing on chain can check that an instance runs the shared template; read its source before funding it.\n\n"
	out += "| pair | reserves | LP shares | providers | instance |\n"
	out += "|---|---|---|---|---|\n"
	entries.Iterate("", "", func(key string, value any) bool {
		e := value.(*Entry)
		symA, symB := e.Pair.Symbols()
		resA, resB := e.Pair.Reserves()
		out += ufmt.Sprintf("| [%s/%s](/r/moul/x/pairreg/v0:%s) | %d %s / %d %s | %d | %d | [`%s`](%s) |\n",
			symA, symB, key,
			resA, symA, resB, symB,
			e.Pair.TotalShares(), e.Pair.Providers(),
			shortPath(e.Path), webPath(e.Path))
		return false
	})
	return out
}

//
// Internals.
//

func countFor(id string) int {
	v := couples.Get(id)
	if v == nil {
		return 0
	}
	return v.(int)
}

// webPath turns a package path into a gnoweb link.
func webPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i:]
	}
	return "/" + pkgPath
}

// shortPath drops the chain domain, which is the same on every row.
func shortPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i+1:]
	}
	return pkgPath
}

