// Package geohashdemo is a small gnoweb demo of the
// [p/moul/x/daily/geohash](/p/moul/x/daily/geohash/v0) library: it shows a
// point encoded at growing precision, the box a hash actually names, and the
// eight cells around one, including the wrap at the antimeridian.
//
// It contains no geohash logic of its own. Stateless and read-only, so Render
// is fully deterministic and takes nothing from a caller.
package geohashdemo

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/geohash/v0"
)

// The three fixed points the demo encodes. Coordinates only, so nothing here
// depends on the chain, the clock or the caller.
const (
	jutlandLat, jutlandLon = 57.64911, 10.40744
	leonLat, leonLon       = 42.6, -5.6
	sampleHash             = "ezs42"
)

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/")  -> a point at growing precision
//	Render("/cell")           -> the box a hash names
//	Render("/neighbors")      -> the eight cells around one, and the wrap
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Geohash\n\n")
	b.WriteString("Turning a latitude and longitude into a short base32 string, ")
	b.WriteString("demoing the [`p/moul/x/daily/geohash`](/p/moul/x/daily/geohash/v0) library.\n\n")

	switch parseArg(path) {
	case "cell":
		b.WriteString(renderCell())
	case "neighbors":
		b.WriteString(renderNeighbors())
	default:
		b.WriteString(renderPrecision())
	}
	return b.String()
}

// renderPrecision shows one point at every length, which is the property that
// makes a geohash worth storing: the prefix is the same place, zoomed out.
func renderPrecision() string {
	var b strings.Builder
	b.WriteString("## One point, at growing precision\n\n")
	b.WriteString("Jutland, Denmark, at ")
	b.WriteString(coord(jutlandLat, jutlandLon))
	b.WriteString(":\n\n```\n")
	for p := 1; p <= 11; p++ {
		h, err := geohash.Encode(jutlandLat, jutlandLon, p)
		if err != nil {
			return b.String() + "```\n_unexpected error: " + err.Error() + "_\n"
		}
		b.WriteString(pad(strconv.Itoa(p), 2))
		b.WriteString("  ")
		b.WriteString(h)
		b.WriteString("\n")
	}
	b.WriteString("```\n\n")
	b.WriteString("Every character adds five bits and every prefix is itself a valid ")
	b.WriteString("geohash of the same place, so truncating one zooms out. Two hashes ")
	b.WriteString("sharing a long prefix are close together, which is what lets an avl ")
	b.WriteString("tree keyed this way answer \"everything near here\" with a range scan ")
	b.WriteString("and no geometry at all.\n\n")
	b.WriteString("Two more places, at the length each one needs:\n\n")
	b.WriteString(bullet("Null Island", 0, 0, 5))
	b.WriteString(bullet("Leon, Spain", leonLat, leonLon, 5))
	b.WriteString(bullet("Jutland, Denmark", jutlandLat, jutlandLon, 6))
	b.WriteString("\n> Next: [`/cell`](/r/moul/x/daily/geohashdemo/v0:cell) for the box a ")
	b.WriteString("hash names, [`/neighbors`](/r/moul/x/daily/geohashdemo/v0:neighbors) ")
	b.WriteString("for the eight cells around one.\n")
	return b.String()
}

// renderCell shows that a geohash is a box and not a point, which is the thing
// most callers get wrong about it.
func renderCell() string {
	var b strings.Builder
	box, err := geohash.DecodeBox(sampleHash)
	if err != nil {
		return "_unexpected error: " + err.Error() + "_\n"
	}
	b.WriteString("## The box `" + sampleHash + "` names\n\n")
	b.WriteString("A geohash is a box, never a point, and the shorter the hash the bigger ")
	b.WriteString("the box.\n\n```\n")
	b.WriteString("latitude   " + num(box.MinLat) + " .. " + num(box.MaxLat) + "\n")
	b.WriteString("longitude  " + num(box.MinLon) + " .. " + num(box.MaxLon) + "\n")
	b.WriteString("size       " + num(box.HeightDeg()) + " by " + num(box.WidthDeg()) + " degrees\n")
	b.WriteString("```\n\n")
	lat, lon := box.Center()
	b.WriteString("`Decode` reports the centre, " + coord(lat, lon) + ", because the centre ")
	b.WriteString("is the best single point a box can give. The coordinates that produced ")
	b.WriteString("the hash, " + coord(leonLat, leonLon) + ", are inside it: ")
	b.WriteString(yesNo(box.Contains(leonLat, leonLon)) + ".\n\n")
	b.WriteString("Null Island is not: " + yesNo(box.Contains(0, 0)) + ".\n\n")
	b.WriteString("> Next: [`/neighbors`](/r/moul/x/daily/geohashdemo/v0:neighbors).\n")
	return b.String()
}

// renderNeighbors shows the eight cells around one, and the wrap that the
// classic lookup-table implementations do not do.
func renderNeighbors() string {
	var b strings.Builder
	b.WriteString("## The eight cells around `" + sampleHash + "`\n\n```\n")
	// The grid read as a map: north at the top, east on the right. The centre
	// is the hash itself, so it is not a direction.
	rows := [3][]geohash.Direction{
		{geohash.NorthWest, geohash.North, geohash.NorthEast},
		{geohash.West, geohash.East},
		{geohash.SouthWest, geohash.South, geohash.SouthEast},
	}
	for i, row := range rows {
		cells := make([]string, 0, 3)
		for _, d := range row {
			n, err := geohash.Neighbor(sampleHash, d)
			if err != nil {
				return b.String() + "```\n_unexpected error: " + err.Error() + "_\n"
			}
			cells = append(cells, n)
		}
		if i == 1 {
			// Put the hash itself back in the middle of the middle row.
			cells = []string{cells[0], sampleHash, cells[1]}
		}
		b.WriteString(strings.Join(cells, " ") + "\n")
	}
	b.WriteString("```\n\n")
	b.WriteString("Each one is computed by walking exactly one cell from the centre and ")
	b.WriteString("re-encoding. Every bound is an exact binary fraction, so the step lands ")
	b.WriteString("on another centre rather than near one, and stepping back is the identity.\n\n")
	b.WriteString("### The antimeridian is not an edge of the world\n\n")
	east, err := geohash.Neighbor("z", geohash.East)
	if err != nil {
		return b.String() + "_unexpected error: " + err.Error() + "_\n"
	}
	b.WriteString("`z` is the top right corner cell of the world. The cell east of it is ")
	b.WriteString("`" + east + "`, the top left one, because longitude wraps. The classic ")
	b.WriteString("lookup-table implementations report nothing there, which is a property ")
	b.WriteString("of the tables and not of the globe.\n\n")
	around, err := geohash.Neighbors("z")
	if err != nil {
		return b.String() + "_unexpected error: " + err.Error() + "_\n"
	}
	b.WriteString("Latitude genuinely stops, though, so `z` has no northern neighbour and ")
	b.WriteString("`Neighbors` returns " + strconv.Itoa(len(around)) + " cells rather than eight: ")
	b.WriteString("`" + strings.Join(around, "`, `") + "`.\n\n")
	b.WriteString("> Back to [the overview](/r/moul/x/daily/geohashdemo/v0).\n")
	return b.String()
}

// bullet renders one named place as a list item.
func bullet(name string, lat, lon float64, precision int) string {
	h, err := geohash.Encode(lat, lon, precision)
	if err != nil {
		return "- " + name + ": _unexpected error: " + err.Error() + "_\n"
	}
	return "- " + name + " (" + coord(lat, lon) + "): `" + h + "`\n"
}

// coord formats a latitude and longitude pair.
func coord(lat, lon float64) string { return num(lat) + ", " + num(lon) }

// num formats a float with no trailing zeros. Every value this demo prints is
// an exact binary fraction, so the shortest round-trip form is also the exact
// one.
func num(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }

// yesNo renders a containment answer as a sentence fragment.
func yesNo(ok bool) string {
	if ok {
		return "yes"
	}
	return "no"
}

// pad right-aligns a short string to width n, so the precision column lines up
// inside the code block.
func pad(s string, n int) string {
	for len(s) < n {
		s = " " + s
	}
	return s
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

package geohashdemo

// ExampleRender pins the realm's root Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Geohash
	//
	// Turning a latitude and longitude into a short base32 string, demoing the [`p/moul/x/daily/geohash`](/p/moul/x/daily/geohash/v0) library.
	//
	// ## One point, at growing precision
	//
	// Jutland, Denmark, at 57.64911, 10.40744:
	//
	// ```
	//  1  u
	//  2  u4
	//  3  u4p
	//  4  u4pr
	//  5  u4pru
	//  6  u4pruy
	//  7  u4pruyd
	//  8  u4pruydq
	//  9  u4pruydqq
	// 10  u4pruydqqv
	// 11  u4pruydqqvj
	// ```
	//
	// Every character adds five bits and every prefix is itself a valid geohash of the same place, so truncating one zooms out. Two hashes sharing a long prefix are close together, which is what lets an avl tree keyed this way answer "everything near here" with a range scan and no geometry at all.
	//
	// Two more places, at the length each one needs:
	//
	// - Null Island (0, 0): `s0000`
	// - Leon, Spain (42.6, -5.6): `ezs42`
	// - Jutland, Denmark (57.64911, 10.40744): `u4pruy`
	//
	// > Next: [`/cell`](/r/moul/x/daily/geohashdemo/v0:cell) for the box a hash names, [`/neighbors`](/r/moul/x/daily/geohashdemo/v0:neighbors) for the eight cells around one.
}

// ExampleRender_cell pins the page that shows a geohash is a box, not a point.
func ExampleRender_cell() {
	print(Render("/cell"))
	// Output:
	// # Geohash
	//
	// Turning a latitude and longitude into a short base32 string, demoing the [`p/moul/x/daily/geohash`](/p/moul/x/daily/geohash/v0) library.
	//
	// ## The box `ezs42` names
	//
	// A geohash is a box, never a point, and the shorter the hash the bigger the box.
	//
	// ```
	// latitude   42.5830078125 .. 42.626953125
	// longitude  -5.625 .. -5.5810546875
	// size       0.0439453125 by 0.0439453125 degrees
	// ```
	//
	// `Decode` reports the centre, 42.60498046875, -5.60302734375, because the centre is the best single point a box can give. The coordinates that produced the hash, 42.6, -5.6, are inside it: yes.
	//
	// Null Island is not: no.
	//
	// > Next: [`/neighbors`](/r/moul/x/daily/geohashdemo/v0:neighbors).
}

// ExampleRender_neighbors pins the eight surrounding cells and the wrap at the
// antimeridian.
func ExampleRender_neighbors() {
	print(Render("/neighbors"))
	// Output:
	// # Geohash
	//
	// Turning a latitude and longitude into a short base32 string, demoing the [`p/moul/x/daily/geohash`](/p/moul/x/daily/geohash/v0) library.
	//
	// ## The eight cells around `ezs42`
	//
	// ```
	// ezefx ezs48 ezs49
	// ezefr ezs42 ezs43
	// ezefp ezs40 ezs41
	// ```
	//
	// Each one is computed by walking exactly one cell from the centre and re-encoding. Every bound is an exact binary fraction, so the step lands on another centre rather than near one, and stepping back is the identity.
	//
	// ### The antimeridian is not an edge of the world
	//
	// `z` is the top right corner cell of the world. The cell east of it is `b`, the top left one, because longitude wraps. The classic lookup-table implementations report nothing there, which is a property of the tables and not of the globe.
	//
	// Latitude genuinely stops, though, so `z` has no northern neighbour and `Neighbors` returns 5 cells rather than eight: `b`, `8`, `x`, `w`, `y`.
	//
	// > Back to [the overview](/r/moul/x/daily/geohashdemo/v0).
}

// Package governor is a simplified on-chain governance realm inspired by
// OpenZeppelin's Governor. Anyone may open a proposal; every address gets a
// single equally-weighted vote (1 address = 1 vote); a proposal succeeds when
// its voting deadline has passed and the "for" tally strictly beats "against".
package governor

import (
	"chain/markdown"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/nt/avl/v0"
)

// votingPeriod is the number of blocks a proposal stays open for voting.
const votingPeriod = int64(100)

// Vote support values.
const (
	VoteAgainst = 0
	VoteFor     = 1
	VoteAbstain = 2
)

// Proposal state values.
const (
	StateActive    = "Active"
	StateSucceeded = "Succeeded"
	StateDefeated  = "Defeated"
	StateExecuted  = "Executed"
)

// Proposal is a single governance proposal. It carries no ID field: the id
// belongs to the store, which hands it back on lookup and iteration.
type Proposal struct {
	Proposer       address
	Description    string
	SnapshotHeight int64
	Deadline       int64
	For            int64
	Against        int64
	Abstain        int64
	Executed       bool
	votes          *avl.Tree // voter address (string) -> support (int)
}

// proposals assigns the proposal ids. v0 kept its own nextID plus an idKey()
// that zero-padded to width 12, which stopped ordering Render past 10^12, and
// its own totalCount, which the store's LastID already answers.
var proposals = store.Named("governor: proposal")

// Propose opens a new proposal and returns its id. The snapshot height and
// deadline are recorded from the current chain height.
func Propose(cur realm, description string) int64 {
	if strings.TrimSpace(markdown.StripBidiAndZeroWidth(description)) == "" {
		panic("governor: empty description")
	}
	proposer := unsafe.PreviousRealm().Address()
	h := runtime.ChainHeight()
	p := &Proposal{
		Proposer:       proposer,
		Description:    description,
		SnapshotHeight: h,
		Deadline:       h + votingPeriod,
		votes:          avl.NewTree(),
	}
	id := int64(proposals.Add(p))

	chain.Emit(
		"ProposalCreated",
		"id", strconv.FormatInt(id, 10),
		"proposer", proposer.String(),
		"deadline", strconv.FormatInt(p.Deadline, 10),
	)
	return id
}

// CastVote records one vote for the caller on proposal id. support is
// 0=against, 1=for, 2=abstain. One address may vote at most once per proposal,
// and voting is only allowed while the proposal is Active.
func CastVote(cur realm, id int64, support int) {
	p := mustGet(id)
	if computeState(p, runtime.ChainHeight()) != StateActive {
		panic("governor: voting closed")
	}
	if support < VoteAgainst || support > VoteAbstain {
		panic("governor: invalid support value")
	}
	voter := unsafe.PreviousRealm().Address()
	if p.votes.Has(voter.String()) {
		panic("governor: already voted")
	}
	p.votes.Set(voter.String(), support)

	switch support {
	case VoteFor:
		p.For++
	case VoteAgainst:
		p.Against++
	default:
		p.Abstain++
	}

	chain.Emit(
		"VoteCast",
		"id", strconv.FormatInt(id, 10),
		"voter", voter.String(),
		"support", strconv.Itoa(support),
	)
}

// Execute marks a Succeeded proposal as executed. It panics unless the
// proposal has reached the Succeeded state.
func Execute(cur realm, id int64) {
	p := mustGet(id)
	if computeState(p, runtime.ChainHeight()) != StateSucceeded {
		panic("governor: proposal not in Succeeded state")
	}
	p.Executed = true
	chain.Emit("ProposalExecuted", "id", strconv.FormatInt(id, 10))
}

// State returns the current lifecycle state of proposal id.
func State(id int64) string {
	return computeState(mustGet(id), runtime.ChainHeight())
}

// computeState is the pure state machine: it decides the state of p at chain
// height h. Kept free of globals so it is unit-testable.
func computeState(p *Proposal, h int64) string {
	if p.Executed {
		return StateExecuted
	}
	if h < p.Deadline {
		return StateActive
	}
	if p.For > p.Against {
		return StateSucceeded
	}
	return StateDefeated
}

func mustGet(id int64) *Proposal {
	return proposals.MustGet(store.ID(id)).(*Proposal)
}

// bar renders a proportional ▓░ progress bar of fixed width.
func bar(value, total int64, width int) string {
	if width <= 0 {
		return ""
	}
	filled := 0
	if total > 0 {
		filled = int((value*int64(width) + total/2) / total)
		if filled > width {
			filled = width
		}
	}
	return strings.Repeat("▓", filled) + strings.Repeat("░", width-filled)
}

// Render lists all proposals with their tallies and states as Markdown.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# 🏛️ Governor\n\n")
	b.WriteString("Simplified on-chain governance — 1 address = 1 vote, ")
	b.WriteString("voting period of " + strconv.FormatInt(votingPeriod, 10) + " blocks.\n\n")

	h := runtime.ChainHeight()
	b.WriteString("Current chain height: **" + strconv.FormatInt(h, 10) + "**\n\n")

	if proposals.Len() == 0 {
		b.WriteString("_No proposals yet. Call `Propose` to create one._\n")
		return b.String()
	}

	b.WriteString("Total proposals: **" + proposals.LastID().String() + "**\n\n")

	proposals.Each(func(id store.ID, v any) {
		p := v.(*Proposal)
		state := computeState(p, h)
		total := p.For + p.Against + p.Abstain

		b.WriteString("---\n\n")
		b.WriteString("## #" + id.String() + " · " + state + "\n\n")
		b.WriteString("> " + p.Description + "\n\n")
		b.WriteString("- Proposer: `" + p.Proposer.String() + "`\n")
		b.WriteString("- Snapshot height: " + strconv.FormatInt(p.SnapshotHeight, 10) + "\n")
		b.WriteString("- Deadline height: " + strconv.FormatInt(p.Deadline, 10))
		if state == StateActive {
			b.WriteString(" (" + strconv.FormatInt(p.Deadline-h, 10) + " blocks left)")
		}
		b.WriteString("\n\n")

		b.WriteString("| Choice | Votes | Tally |\n")
		b.WriteString("|---|---|---|\n")
		b.WriteString("| For | " + strconv.FormatInt(p.For, 10) + " | `" + bar(p.For, total, 20) + "` |\n")
		b.WriteString("| Against | " + strconv.FormatInt(p.Against, 10) + " | `" + bar(p.Against, total, 20) + "` |\n")
		b.WriteString("| Abstain | " + strconv.FormatInt(p.Abstain, 10) + " | `" + bar(p.Abstain, total, 20) + "` |\n\n")
	})

	return b.String()
}

package governor

import (
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestComputeState(t *testing.T) {
	tests := []struct {
		name string
		p    *Proposal
		h    int64
		want string
	}{
		{
			name: "before deadline is active",
			p:    &Proposal{Deadline: 100, For: 0, Against: 0},
			h:    50,
			want: StateActive,
		},
		{
			name: "at deadline with for>against succeeds",
			p:    &Proposal{Deadline: 100, For: 3, Against: 1},
			h:    100,
			want: StateSucceeded,
		},
		{
			name: "past deadline tie is defeated",
			p:    &Proposal{Deadline: 100, For: 2, Against: 2},
			h:    120,
			want: StateDefeated,
		},
		{
			name: "past deadline against wins is defeated",
			p:    &Proposal{Deadline: 100, For: 1, Against: 5},
			h:    101,
			want: StateDefeated,
		},
		{
			name: "executed overrides everything",
			p:    &Proposal{Deadline: 100, For: 9, Against: 0, Executed: true},
			h:    200,
			want: StateExecuted,
		},
	}
	for _, tt := range tests {
		got := computeState(tt.p, tt.h)
		uassert.Equal(t, tt.want, got, tt.name)
	}
}

func TestBar(t *testing.T) {
	// empty total renders all-empty of exact width
	uassert.Equal(t, "░░░░░░░░░░", bar(0, 0, 10), "zero total")
	// full value fills entirely
	uassert.Equal(t, "▓▓▓▓▓▓▓▓▓▓", bar(10, 10, 10), "full")
	// half value fills half
	uassert.Equal(t, "▓▓▓▓▓░░░░░", bar(5, 10, 10), "half")
	// zero width yields empty string
	uassert.Equal(t, "", bar(1, 2, 0), "zero width")
}

// v0 asserted that its own idKey() padded to width 12. That rule held only
// below the width: idKey(10^12) is 13 characters and sorts before
// idKey(10^12-1), so the proposal list would have rendered out of order from
// that id on. The store key has no width to outgrow.
func TestIDKey(t *testing.T) {
	uassert.True(t, store.ID(2).Key() < store.ID(10).Key(), "2 sorts before 10")
	uassert.True(t, store.ID(9).Key() < store.ID(100).Key(), "9 sorts before 100")
	uassert.True(t, store.ID(999999999999).Key() < store.ID(1000000000000).Key(),
		"and it keeps holding one past v0's width-12 ceiling")
}

