// A crafted URL path used to close this code span early and render its own
// markdown. md.InlineCode sizes the fence past any backtick run, so the payload
// comes back inside a double fence with the backtick intact.
func TestRenderPathCannotEscapeItsCodeSpan(t *testing.T) {
	out := Renderer{Program: NewProgram("ugnot", testutils.TestAddress("a")), Title: "T", Link: "/r/x/v0"}.Render("a`b")
	if !strings.Contains(out, "``a`b``") {
		t.Fatalf("the fence did not outscan the caller's backtick: %q", out)
	}
}

// Package grants is a grant board governed by a member set: anyone may ask
// the board for money, the members vote in the open, and the money leaves in
// tranches that each have to be earned by producing a proof the members
// accept.
//
// The package is pure. It holds no coins, reads no chain state and imports
// nothing from `chain`: the caller supplies the acting address and the block
// height, and the caller performs the transfer. That is what makes the whole
// state machine unit-testable without a node, and it is what lets the same
// board be driven by a realm, by a test, or by a different payment rail.
// Live board: gno.land/r/moul/grant/v0.
//
// # The shape of a grant
//
// A Request is a title, a body, and an ordered list of Milestones, each with
// its own amount. Approving a request does not pay anything: it only makes the
// first milestone claimable. To get a tranche the applicant submits a Proof
// (a URL, a hash, or plain text) and the members review that specific proof.
// A rejected proof does not kill the grant, it just closes one Attempt; the
// applicant submits another. Every attempt, accepted or not, stays on the
// record with the ballots that decided it.
//
// # Asking for someone else
//
// A request has an applicant, who files it and answers for it, and a
// beneficiary, who gets paid. SubmitFor separates the two and takes a reason
// for the detour; Submit is the common case where they are the same address.
//
// The split is not a convenience. An account with nothing in it cannot pay the
// gas to ask for its first coins, so on a board whose whole purpose is to fund
// empty accounts, "someone else files it" is the ONLY path that works. Both
// addresses are then barred from voting on the request, and either of them may
// submit a proof, for the same reason: the payee may not be able to transact
// at all until the first tranche lands.
//
// # Who may vote
//
// Every member, once, per decision. The party the decision is about is
// excluded: the applicant does not vote on their own grant, and the subject of
// a membership change does not vote on their own membership. The bar is a
// majority of the addresses that are actually eligible, recomputed on each
// ballot, so a board that grows mid-vote raises its own bar.
//
// # What this deliberately does not do
//
// No weights, no delegation, no quadratic anything, no deadline. A request
// with no majority either way simply stays Pending until someone breaks the
// tie or the applicant withdraws it. Those are all reasonable things to add on
// top; none of them is needed to show the shape.
package grants

import (
	"errors"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// Errors returned by the mutators. They are sentinels so a realm can map them
// onto its own messages, or simply panic with them.
var (
	ErrNotMember     = errors.New("grants: not a board member")
	ErrNotApplicant  = errors.New("grants: only the applicant may do this")
	ErrNoRequest     = errors.New("grants: no such request")
	ErrNoMilestone   = errors.New("grants: no such milestone")
	ErrNotPending    = errors.New("grants: the request is not pending")
	ErrNotApproved   = errors.New("grants: the request is not approved")
	ErrAlreadyVoted  = errors.New("grants: this member already voted")
	ErrConflict      = errors.New("grants: the party a decision is about may not vote on it")
	ErrOutOfOrder    = errors.New("grants: milestones are claimed in order")
	ErrProofPending  = errors.New("grants: a proof is already under review")
	ErrNoProof       = errors.New("grants: no proof is under review")
	ErrBadTitle      = errors.New("grants: title must be 1 to 100 characters")
	ErrBadBody       = errors.New("grants: body must be at most 2000 characters")
	ErrBadMilestones = errors.New("grants: a grant needs 1 to 10 milestones")
	ErrBadAmount     = errors.New("grants: every milestone must ask for a positive amount")
	ErrBadProof      = errors.New("grants: proof kind must be url, hash or text, with a reference")
	ErrBadReason     = errors.New("grants: reason must be at most 300 characters")
	ErrNeedReason    = errors.New("grants: filing for someone else needs a reason")
	ErrBadAddress    = errors.New("grants: invalid address")
	ErrIsMember      = errors.New("grants: already a board member")
	ErrLastMember    = errors.New("grants: the last member cannot be removed")
	ErrNothingSent   = errors.New("grants: a donation must be a positive amount")
	ErrUnderfunded   = errors.New("grants: the treasury cannot cover this tranche")
	ErrBadSpec       = errors.New("grants: milestones must read \"title:amount,title:amount\"")
)

// IndexRequests is how many requests a board's page lists.
//
// Finding 325-cost-at-caps-1: the page rendered every request ever made, and
// Apply is open to anyone with no removal path, so the cost every reader paid
// was set by whoever had applied the most.
const IndexRequests = 20

// Limits every input is checked against. Exported so a UI can pre-validate.
const (
	MaxTitle      = 100
	MaxBody       = 2000
	MaxReason     = 300
	MaxRef        = 300
	MaxNote       = 500
	MaxMilestones = 10
)

// Status is where a request sits in its lifecycle.
type Status int

const (
	Pending   Status = iota // open for member ballots
	Approved                // carried; milestones can be earned
	Rejected                // a majority voted no
	Completed               // every milestone released
	Withdrawn               // the applicant pulled it before a decision
)

func (s Status) String() string {
	switch s {
	case Pending:
		return "pending"
	case Approved:
		return "approved"
	case Rejected:
		return "rejected"
	case Completed:
		return "completed"
	case Withdrawn:
		return "withdrawn"
	}
	return "unknown"
}

// Kind says what carrying a request actually does.
type Kind int

const (
	KindGrant  Kind = iota // pays out, milestone by milestone
	KindMember             // adds or removes a board member, immediately
)

func (k Kind) String() string {
	if k == KindMember {
		return "membership"
	}
	return "grant"
}

// Outcome is the result of one proof attempt.
type Outcome int

const (
	UnderReview Outcome = iota // members are still voting on this proof
	Accepted                   // the tranche is earned
	Refused                    // this proof did not convince; another may
)

func (o Outcome) String() string {
	switch o {
	case Accepted:
		return "accepted"
	case Refused:
		return "refused"
	}
	return "under review"
}

// Ballot is one member's vote on one decision, with the reason they gave.
// Reasons are not optional decoration: they are the only part of a vote that
// tells an applicant what to fix.
type Ballot struct {
	Voter   address
	Approve bool
	Reason  string
	Height  int64
}

// Proof is the evidence an applicant offers for one milestone. Kind is "url",
// "hash" or "text"; the board decides what it is worth.
type Proof struct {
	Kind   string
	Ref    string
	Note   string
	Height int64
}

// Attempt is one proof and the review it got. A milestone keeps every attempt,
// so a refused proof and the reasons it was refused stay readable forever.
type Attempt struct {
	Proof    Proof
	Reviews  []Ballot
	Outcome  Outcome
	ClosedAt int64
}

// Milestone is one tranche of a grant: what has to be shown, and what it pays.
type Milestone struct {
	Title      string
	Amount     int64 // in the smallest unit of whatever the realm pays in
	Attempts   []*Attempt
	Released   bool
	ReleasedAt int64
}

// Current returns the attempt still under review, or nil.
func (m *Milestone) Current() *Attempt {
	if len(m.Attempts) == 0 {
		return nil
	}
	last := m.Attempts[len(m.Attempts)-1]
	if last.Outcome == UnderReview {
		return last
	}
	return nil
}

// Request is a grant application or a membership change.
type Request struct {
	ID          int
	Kind        Kind
	Applicant   address // who filed it and answers for it
	Beneficiary address // who gets paid; equal to Applicant on a self request
	Reason      string  // why the applicant is asking on someone else's behalf
	Title       string
	Body        string
	Milestones  []*Milestone
	Subject     address // KindMember only: the address being added or removed
	Add         bool    // KindMember only: true adds, false removes
	Votes       []Ballot
	Status      Status
	CreatedAt   int64
	DecidedAt   int64
}

// OnBehalf reports whether this grant was filed by one address for another.
func (r *Request) OnBehalf() bool {
	return r.Kind == KindGrant && r.Beneficiary != r.Applicant
}

// Payee is the address a released tranche pays. It is the beneficiary, which
// is the applicant unless the request was filed for someone else.
func (r *Request) Payee() address {
	if r.Beneficiary.IsValid() {
		return r.Beneficiary
	}
	return r.Applicant
}

// Total is the sum of every milestone, released or not.
func (r *Request) Total() int64 {
	var n int64
	for _, m := range r.Milestones {
		n += m.Amount
	}
	return n
}

// Paid is what the milestones released so far add up to.
func (r *Request) Paid() int64 {
	var n int64
	for _, m := range r.Milestones {
		if m.Released {
			n += m.Amount
		}
	}
	return n
}

// Outstanding is what an approved request can still cost the treasury. It is
// zero for anything not approved, which is what makes it safe to sum across
// the board as the committed amount.
func (r *Request) Outstanding() int64 {
	if r.Status != Approved {
		return 0
	}
	return r.Total() - r.Paid()
}

// Next is the index of the first unreleased milestone, or -1 when the grant is
// fully paid. Milestones are earned in order.
func (r *Request) Next() int {
	for i, m := range r.Milestones {
		if !m.Released {
			return i
		}
	}
	return -1
}

// Tally counts the ballots cast on the request itself.
func (r *Request) Tally() (yes, no int) {
	return count(r.Votes)
}

// BallotOf returns the member's ballot on the request, or nil.
func (r *Request) BallotOf(voter address) *Ballot {
	return find(r.Votes, voter)
}

// Excludes reports whether addr is barred from voting on this request because
// the decision is about them.
//
// A grant excludes BOTH parties, not just the one who typed the transaction:
// letting a member be paid by a request a friend filed for them is the same
// conflict with one more step in it.
func (r *Request) Excludes(addr address) bool {
	if r.Kind == KindMember {
		return addr == r.Subject
	}
	return addr == r.Applicant || addr == r.Payee()
}

func count(bs []Ballot) (yes, no int) {
	for _, b := range bs {
		if b.Approve {
			yes++
		} else {
			no++
		}
	}
	return yes, no
}

func find(bs []Ballot, voter address) *Ballot {
	for i := range bs {
		if bs[i].Voter == voter {
			return &bs[i]
		}
	}
	return nil
}

// Board is the whole state of one grant program: who decides, and what has
// been asked of them.
type Board struct {
	members  *avl.Tree // address string -> int64 join height
	requests *avl.Tree // zero-padded id -> *Request
	nextID   int
}

// New returns a board whose founding members are the given addresses, all
// recorded as having joined at height 0. Duplicates and invalid addresses are
// skipped; a board with no members accepts no decisions until one is added, so
// callers normally pass at least one.
func New(founders ...address) *Board {
	b := &Board{members: avl.NewTree(), requests: avl.NewTree(), nextID: 1}
	for _, f := range founders {
		if f.IsValid() {
			b.members.Set(f.String(), int64(0))
		}
	}
	return b
}

// IsMember reports whether addr sits on the board.
func (b *Board) IsMember(addr address) bool { return b.members.Has(addr.String()) }

// MemberCount is the number of addresses on the board.
func (b *Board) MemberCount() int { return b.members.Size() }

// Members lists the board in address order, which is stable across calls.
func (b *Board) Members() []address {
	out := make([]address, 0, b.members.Size())
	b.members.Iterate("", "", func(k string, _ any) bool {
		out = append(out, address(k))
		return false
	})
	return out
}

// JoinedAt returns the height a member joined, or -1 for a non-member.
func (b *Board) JoinedAt(addr address) int64 {
	v := b.members.Get(addr.String())
	if v == nil {
		return -1
	}
	return v.(int64)
}

// Eligible is how many members may vote on a request: everyone but the parties
// the decision is about.
func (b *Board) Eligible(r *Request) int {
	n := 0
	b.members.Iterate("", "", func(k string, _ any) bool {
		if !r.Excludes(address(k)) {
			n++
		}
		return false
	})
	return n
}

// Majority is the number of concurring ballots a decision on r needs. It is
// recomputed on every ballot, so a board that changes size mid-vote moves its
// own bar rather than freezing a stale one.
func (b *Board) Majority(r *Request) int {
	n := b.Eligible(r)
	if n <= 0 {
		return 1 // an unreachable bar beats a bar of zero
	}
	return n/2 + 1
}

// Get returns a request by id, or nil.
func (b *Board) Get(id int) *Request {
	v := b.requests.Get(idKey(id))
	if v == nil {
		return nil
	}
	return v.(*Request)
}

// Size is the number of requests ever filed.
func (b *Board) Size() int { return b.requests.Size() }

// List returns every request in id order.
func (b *Board) List() []*Request {
	out := make([]*Request, 0, b.requests.Size())
	b.requests.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*Request))
		return false
	})
	return out
}

// Committed is what the treasury still owes on approved grants. A realm that
// keeps its balance at or above this number can always pay a released tranche.
func (b *Board) Committed() int64 {
	var n int64
	b.requests.Iterate("", "", func(_ string, v any) bool {
		n += v.(*Request).Outstanding()
		return false
	})
	return n
}

// Disbursed is everything the board has ever released.
func (b *Board) Disbursed() int64 {
	var n int64
	b.requests.Iterate("", "", func(_ string, v any) bool {
		n += v.(*Request).Paid()
		return false
	})
	return n
}

// idKey pads an id so avl iteration is numeric, not lexicographic: unpadded
// keys sort "1","10","2" and every listing would lose its order past nine
// entries. ufmt has no width flags in gno, so the padding is by hand.
func idKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 8 {
		s = "0" + s
	}
	return s
}

package grants

// This file holds every state transition of the board. Each one takes the
// acting address and the block height from the caller rather than reading
// them from the chain, which is what keeps the package pure and the whole
// lifecycle exercisable in a plain unit test.

// NewMilestone is a small constructor so callers do not build the struct (and
// its Attempts slice) by hand.
func NewMilestone(title string, amount int64) *Milestone {
	return &Milestone{Title: title, Amount: amount}
}

// Submit files a grant application for the applicant themselves. Anyone may
// apply; being a member is not required and does not help, since a member is
// barred from voting on their own request.
func (b *Board) Submit(applicant address, title, body string, ms []*Milestone, height int64) (*Request, error) {
	return b.SubmitFor(applicant, applicant, "", title, body, ms, height)
}

// SubmitFor files a grant application whose money goes to beneficiary rather
// than to the applicant, with a reason for the detour.
//
// The reason is required, and it is required because it is the only thing on
// the page that answers the question a reader will have: why is this person
// asking for someone else's money. The usual honest answer is that the payee
// has an empty account and cannot pay the gas to ask, which is exactly the
// case a grant board exists to serve and exactly the case an impersonation
// looks like. Making the claim explicit is what lets a member check it.
//
// Passing the applicant's own address is the same as Submit and needs no
// reason.
func (b *Board) SubmitFor(applicant, beneficiary address, reason, title, body string, ms []*Milestone, height int64) (*Request, error) {
	if !applicant.IsValid() || !beneficiary.IsValid() {
		return nil, ErrBadAddress
	}
	if len(reason) > MaxReason {
		return nil, ErrBadReason
	}
	if beneficiary != applicant && reason == "" {
		return nil, ErrNeedReason
	}
	if err := checkTitle(title); err != nil {
		return nil, err
	}
	if len(body) > MaxBody {
		return nil, ErrBadBody
	}
	if len(ms) == 0 || len(ms) > MaxMilestones {
		return nil, ErrBadMilestones
	}
	for _, m := range ms {
		if m == nil || m.Amount <= 0 {
			return nil, ErrBadAmount
		}
		if err := checkTitle(m.Title); err != nil {
			return nil, err
		}
	}
	return b.file(&Request{
		Kind:        KindGrant,
		Applicant:   applicant,
		Beneficiary: beneficiary,
		Reason:      reason,
		Title:       title,
		Body:        body,
		Milestones:  ms,
		CreatedAt:   height,
	}), nil
}

// SubmitMemberChange files a request to add or remove a board member. Only a
// member may file one: opening the board's own composition to anyone with a
// keypair is how a grant board gets captured.
func (b *Board) SubmitMemberChange(proposer, subject address, add bool, body string, height int64) (*Request, error) {
	if !b.IsMember(proposer) {
		return nil, ErrNotMember
	}
	if !subject.IsValid() {
		return nil, ErrBadAddress
	}
	if len(body) > MaxBody {
		return nil, ErrBadBody
	}
	switch {
	case add && b.IsMember(subject):
		return nil, ErrIsMember
	case !add && !b.IsMember(subject):
		return nil, ErrNotMember
	case !add && b.MemberCount() == 1:
		return nil, ErrLastMember
	}
	title := "Remove " + subject.String()
	if add {
		title = "Add " + subject.String()
	}
	return b.file(&Request{
		Kind:        KindMember,
		Applicant:   proposer,
		Beneficiary: proposer,
		Title:       title,
		Body:        body,
		Subject:     subject,
		Add:         add,
		CreatedAt:   height,
	}), nil
}

func (b *Board) file(r *Request) *Request {
	r.ID = b.nextID
	b.nextID++
	b.requests.Set(idKey(r.ID), r)
	return r
}

// Withdraw lets an applicant pull their own request before it is decided.
func (b *Board) Withdraw(caller address, id int, height int64) error {
	r := b.Get(id)
	if r == nil {
		return ErrNoRequest
	}
	if r.Applicant != caller {
		return ErrNotApplicant
	}
	if r.Status != Pending {
		return ErrNotPending
	}
	r.Status, r.DecidedAt = Withdrawn, height
	return nil
}

// Standing counts only the ballots of addresses that are members right now.
// Decisions use this, not Request.Tally: a ballot is a permanent record of
// what someone said, but it stops carrying weight the moment they leave the
// board. The two numbers differ exactly when a voter has since been removed,
// and a good renderer shows both.
func (b *Board) Standing(r *Request) (yes, no int) { return b.standing(r.Votes) }

// Decides previews what a ballot would do without casting it, so a caller can
// check a precondition it cannot roll back: a realm, for instance, refusing
// to let a grant carry that its treasury cannot cover. It reports false for a
// ballot that would be refused anyway.
func (b *Board) Decides(id int, voter address, approve bool) (bool, Status) {
	r := b.Get(id)
	if r == nil || r.Status != Pending {
		return false, Pending
	}
	if !b.IsMember(voter) || r.Excludes(voter) || r.BallotOf(voter) != nil {
		return false, Pending
	}
	yes, no := b.Standing(r)
	if approve {
		yes++
	} else {
		no++
	}
	switch m := b.Majority(r); {
	case yes >= m:
		return true, Approved
	case no >= m:
		return true, Rejected
	}
	return false, Pending
}

// ReviewDecides is Decides for a proof review: it reports whether this
// verdict would close the attempt under review, and how. A realm uses it to
// check, before recording anything, that it can actually pay a tranche it is
// about to release.
func (b *Board) ReviewDecides(id, idx int, voter address, accept bool) (bool, Outcome) {
	r := b.Get(id)
	if r == nil || r.Kind != KindGrant || r.Status != Approved {
		return false, UnderReview
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return false, UnderReview
	}
	a := r.Milestones[idx].Current()
	if a == nil {
		return false, UnderReview
	}
	if !b.IsMember(voter) || r.Excludes(voter) || find(a.Reviews, voter) != nil {
		return false, UnderReview
	}
	yes, no := b.standing(a.Reviews)
	if accept {
		yes++
	} else {
		no++
	}
	switch m := b.Majority(r); {
	case yes >= m:
		return true, Accepted
	case no >= m:
		return true, Refused
	}
	return false, UnderReview
}

// standing counts ballots from current members only. See Standing.
func (b *Board) standing(bs []Ballot) (yes, no int) {
	for _, v := range bs {
		if !b.IsMember(v.Voter) {
			continue
		}
		if v.Approve {
			yes++
		} else {
			no++
		}
	}
	return yes, no
}

// Vote casts one member's ballot on a request and returns the status it left
// the request in. A member votes once; there is no changing your mind, which
// is the price of every ballot being a permanent public statement.
func (b *Board) Vote(voter address, id int, approve bool, reason string, height int64) (Status, error) {
	r := b.Get(id)
	if r == nil {
		return Pending, ErrNoRequest
	}
	if !b.IsMember(voter) {
		return r.Status, ErrNotMember
	}
	if r.Status != Pending {
		return r.Status, ErrNotPending
	}
	if r.Excludes(voter) {
		return r.Status, ErrConflict
	}
	if r.BallotOf(voter) != nil {
		return r.Status, ErrAlreadyVoted
	}
	if len(reason) > MaxReason {
		return r.Status, ErrBadReason
	}

	r.Votes = append(r.Votes, Ballot{Voter: voter, Approve: approve, Reason: reason, Height: height})

	yes, no := b.Standing(r)
	switch m := b.Majority(r); {
	case yes >= m:
		r.Status, r.DecidedAt = Approved, height
		if r.Kind == KindMember {
			b.applyMemberChange(r, height)
		}
	case no >= m:
		r.Status, r.DecidedAt = Rejected, height
	}
	return r.Status, nil
}

// applyMemberChange is the whole execution engine for KindMember: a carried
// membership request takes effect at once, with nothing to claim afterwards,
// so it goes straight from Approved to Completed.
func (b *Board) applyMemberChange(r *Request, height int64) {
	if r.Add {
		b.members.Set(r.Subject.String(), height)
	} else {
		b.members.Remove(r.Subject.String())
	}
	r.Status = Completed
}

// SubmitProof offers evidence for the next unreleased milestone of an
// approved grant. Milestones are earned in order, and only one proof is under
// review at a time.
//
// Either the applicant or the beneficiary may submit. On a request filed for
// an empty account, the payee cannot transact until the first tranche lands,
// so restricting this to the payee would strand the grant it was filed to
// unstick; restricting it to the filer would leave the payee unable to show
// their own work once they can.
func (b *Board) SubmitProof(caller address, id, idx int, p Proof) error {
	r := b.Get(id)
	if r == nil {
		return ErrNoRequest
	}
	if r.Kind != KindGrant || r.Status != Approved {
		return ErrNotApproved
	}
	if r.Applicant != caller && r.Payee() != caller {
		return ErrNotApplicant
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return ErrNoMilestone
	}
	if idx != r.Next() {
		return ErrOutOfOrder
	}
	if err := checkProof(p); err != nil {
		return err
	}
	m := r.Milestones[idx]
	if m.Current() != nil {
		return ErrProofPending
	}
	m.Attempts = append(m.Attempts, &Attempt{Proof: p, Outcome: UnderReview})
	return nil
}

// Review casts a member's verdict on the proof currently under review and
// returns the outcome that verdict left the attempt in. Accepting it releases
// the tranche, which in this package means marking it Released and nothing
// more; moving the coins is the caller's job, and Request.Paid tells it how
// much it now owes. Refusing closes the attempt and lets the applicant try
// again with better evidence.
func (b *Board) Review(voter address, id, idx int, accept bool, reason string, height int64) (Outcome, error) {
	r := b.Get(id)
	if r == nil {
		return UnderReview, ErrNoRequest
	}
	if !b.IsMember(voter) {
		return UnderReview, ErrNotMember
	}
	if r.Kind != KindGrant || r.Status != Approved {
		return UnderReview, ErrNotApproved
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return UnderReview, ErrNoMilestone
	}
	if r.Excludes(voter) {
		return UnderReview, ErrConflict
	}
	if len(reason) > MaxReason {
		return UnderReview, ErrBadReason
	}
	m := r.Milestones[idx]
	a := m.Current()
	if a == nil {
		return UnderReview, ErrNoProof
	}
	if find(a.Reviews, voter) != nil {
		return UnderReview, ErrAlreadyVoted
	}

	a.Reviews = append(a.Reviews, Ballot{Voter: voter, Approve: accept, Reason: reason, Height: height})

	yes, no := b.standing(a.Reviews)
	switch mj := b.Majority(r); {
	case yes >= mj:
		a.Outcome, a.ClosedAt = Accepted, height
		m.Released, m.ReleasedAt = true, height
		if r.Next() == -1 {
			r.Status = Completed
		}
	case no >= mj:
		a.Outcome, a.ClosedAt = Refused, height
	}
	return a.Outcome, nil
}

func checkTitle(s string) error {
	if len(s) == 0 || len(s) > MaxTitle {
		return ErrBadTitle
	}
	return nil
}

func checkProof(p Proof) error {
	switch p.Kind {
	case "url", "hash", "text":
	default:
		return ErrBadProof
	}
	if len(p.Ref) == 0 || len(p.Ref) > MaxRef || len(p.Note) > MaxNote {
		return ErrBadProof
	}
	return nil
}

package grants

import (
	"strconv"
	"strings"
)

// Program is a Board plus the money that moves around it: what came in, what
// went out, and the denomination it is all counted in.
//
// It still holds no coins and calls no banker. A realm hands it the current
// treasury balance whenever a decision depends on one, and executes the
// Payment it hands back. That split is the whole point: everything a grant
// program decides is testable without a node, and the realm on top is thin
// enough to read in one screen.
type Program struct {
	Board     *Board
	Denom     string
	Donations []Donation
	Payments  []Payment
}

// Donation is one top-up of the treasury, credited to a name.
type Donation struct {
	Height int64
	From   address
	Amount int64
}

// Payment is one released tranche. The ledger of these is a program's answer
// to "where did the money go".
type Payment struct {
	Height    int64
	Request   int
	Milestone int
	To        address
	Amount    int64
}

// NewProgram returns a program whose board is seated with founders. denom is
// the coin everything is counted in ("ugnot" on gno.land); it is carried so a
// renderer can label amounts without the realm telling it twice.
func NewProgram(denom string, founders ...address) *Program {
	return &Program{Board: New(founders...), Denom: denom}
}

// Fund records a top-up. The coins have already moved by the time this is
// called: a realm calls it to put a name next to a transfer that would
// otherwise be anonymous.
func (p *Program) Fund(from address, amount, height int64) error {
	if amount <= 0 {
		return ErrNothingSent
	}
	if !from.IsValid() {
		return ErrBadAddress
	}
	p.Donations = append(p.Donations, Donation{Height: height, From: from, Amount: amount})
	return nil
}

// Apply files a grant request from a milestone spec, "design:100,ship:400".
// See ParseMilestones for the grammar.
func (p *Program) Apply(applicant address, title, body, spec string, height int64) (*Request, error) {
	return p.ApplyFor(applicant, applicant, "", title, body, spec, height)
}

// ApplyFor is Apply for a request whose money goes to someone other than the
// address filing it. See Board.SubmitFor for why the reason is required.
func (p *Program) ApplyFor(applicant, beneficiary address, reason, title, body, spec string, height int64) (*Request, error) {
	ms, err := ParseMilestones(spec)
	if err != nil {
		return nil, err
	}
	return p.Board.SubmitFor(applicant, beneficiary, reason, title, body, ms, height)
}

// Review casts a member's verdict on the proof under review and, when that
// verdict releases the tranche, records the payment and hands it back for the
// caller to execute.
//
// balance is what the treasury holds right now. A verdict that would release
// more than that is refused with ErrUnderfunded and changes NOTHING: no
// ballot, no release, no payment. That ordering is the reason Board.Review is
// not called directly by a realm. A refusal is always free to record, since it
// costs the treasury nothing.
func (p *Program) Review(voter address, id, idx int, accept bool, reason string, height, balance int64) (Outcome, *Payment, error) {
	if releases, out := p.Board.ReviewDecides(id, idx, voter, accept); releases && out == Accepted {
		if amount := p.Board.Get(id).Milestones[idx].Amount; balance < amount {
			return UnderReview, nil, ErrUnderfunded
		}
	}

	out, err := p.Board.Review(voter, id, idx, accept, reason, height)
	if err != nil || out != Accepted {
		return out, nil, err
	}

	r := p.Board.Get(id)
	pay := Payment{
		Height:    height,
		Request:   id,
		Milestone: idx,
		To:        r.Payee(),
		Amount:    r.Milestones[idx].Amount,
	}
	p.Payments = append(p.Payments, pay)
	return out, &pay, nil
}

// Raised is everything ever donated through Fund.
func (p *Program) Raised() int64 {
	var n int64
	for _, d := range p.Donations {
		n += d.Amount
	}
	return n
}

// Disbursed is everything ever released.
func (p *Program) Disbursed() int64 { return p.Board.Disbursed() }

// Committed is what approved grants can still claim.
func (p *Program) Committed() int64 { return p.Board.Committed() }

// Available is balance minus what is already promised. It goes NEGATIVE when
// the board has approved more than the treasury holds, which is allowed on
// purpose: a board that can only approve what it already has cannot approve
// anything before a donor shows up. Renderers say so out loud.
func (p *Program) Available(balance int64) int64 { return balance - p.Committed() }

// ParseMilestones reads "design:100,ship:400" into milestones, amounts in the
// program's denomination, paid in the order written. A title may not contain a
// comma, and the amount is whatever follows the LAST colon, so
// "port gno:land tooling:250" parses the way it reads.
func ParseMilestones(spec string) ([]*Milestone, error) {
	out := []*Milestone{}
	for _, part := range strings.Split(spec, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		i := strings.LastIndex(part, ":")
		if i < 0 {
			return nil, ErrBadSpec
		}
		amount, err := strconv.ParseInt(strings.TrimSpace(part[i+1:]), 10, 64)
		if err != nil {
			return nil, ErrBadSpec
		}
		out = append(out, NewMilestone(strings.TrimSpace(part[:i]), amount))
	}
	if len(out) == 0 {
		return nil, ErrBadSpec
	}
	return out, nil
}

package grants

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Renderer turns a Program into the three markdown pages a grant program
// needs: the board, one request, and the ledger. Everything that differs
// between one program and the next is a field, so a realm's whole Render is
// building this literal and calling it.
//
// Build it INSIDE Render rather than storing it in a realm global: Note is a
// func, and Balance has to be read fresh on every call anyway.
//
// # Escaping
//
// Everything a caller typed (titles, bodies, reasons, proofs, notes) is
// escaped here, once, through p/moul/kit/ui and p/nt/markdown/sanitize. A
// realm does not repeat it and must not pre-escape: escaping twice shows the
// backslashes. The realm's OWN fields below (Title, Intro, Notes, Footer) are
// chrome, are written by whoever deployed the realm, and are emitted as-is so
// they can carry markdown.
type Renderer struct {
	Program  *Program
	Title    string   // page heading
	Intro    string   // markdown under the heading, already wrapped
	Notes    []string // extra paragraphs on the board page: house rules, scope
	Path     string   // package path, for the gnokey examples
	Link     string   // gnoweb route prefix, e.g. "/r/moul/grant/v0"
	Treasury address  // where the money sits
	Balance  int64    // what it holds right now
	Footer   string   // closing paragraph on the board page

	// Note returns an extra callout for one request page, or "". Use it for
	// anything the library cannot know, such as a seeded request whose
	// applicant address has no key behind it.
	Note func(*Request) string
}

// Render serves the board at "", one request at "request/<id>", and the money
// trail at "ledger".
func (rr Renderer) Render(path string) string {
	path = strings.TrimSpace(path)
	switch {
	case path == "" || path == "/":
		return rr.index()
	case path == "ledger":
		return rr.ledger()
	case strings.HasPrefix(path, "request/"):
		return rr.request(strings.TrimPrefix(path, "request/"))
	}
	return "# " + rr.Title + "\n\nNo page " + md.InlineCode(path) + ". Try [the board](" + rr.Link +
		") or [the ledger](" + rr.Link + ":ledger).\n"
}

func (rr Renderer) index() string {
	p := rr.Program
	var b strings.Builder
	b.WriteString("# " + rr.Title + "\n\n")
	if rr.Intro != "" {
		b.WriteString(rr.Intro + "\n\n")
	}
	for _, n := range rr.Notes {
		b.WriteString(n + "\n\n")
	}

	b.WriteString("## Treasury\n\n")
	b.WriteString("| Field | Value |\n|---|---|\n")
	b.WriteString("| Address | " + ui.AddrFull(rr.Treasury) + " |\n")
	b.WriteString("| Balance | " + rr.amount(rr.Balance) + " |\n")
	b.WriteString("| Promised | " + rr.amount(p.Committed()) + " |\n")
	b.WriteString("| Unpromised | " + rr.amount(p.Available(rr.Balance)) + " |\n")
	b.WriteString("| Donated | " + rr.amount(p.Raised()) + " |\n")
	b.WriteString("| Paid out | " + rr.amount(p.Disbursed()) + " |\n\n")
	if short := -p.Available(rr.Balance); short > 0 {
		b.WriteString("The board has promised " + rr.amount(short) + " more than it holds. Approving a\n")
		b.WriteString("grant does not escrow anything, so a tranche can come due against an empty\n")
		b.WriteString("treasury; a review that would release one is refused until the money is there.\n")
		b.WriteString("Top it up with `Fund`, or by sending coins straight to the address above.\n\n")
	}

	b.WriteString("## Board\n\n")
	b.WriteString("A decision needs a majority of the members eligible to cast a ballot on it,\n")
	b.WriteString("recomputed every time: the party a decision is about never votes on it, so an\n")
	b.WriteString("applicant who sits on the board shrinks the room rather than packing it.\n\n")
	b.WriteString("| Member | Joined at height |\n|---|---|\n")
	for _, m := range p.Board.Members() {
		b.WriteString("| " + ui.AddrFull(m) + " | " + i64(p.Board.JoinedAt(m)) + " |\n")
	}
	b.WriteString("\n")

	b.WriteString("## Requests\n\n")
	all := p.Board.List()
	if len(all) == 0 {
		b.WriteString("Nothing has been asked of this board yet. `Apply` is open to anyone.\n\n")
	} else {
		// Finding 325-cost-at-caps-1: this rendered every request ever
		// made, and Apply is open to anyone with nothing that removes one,
		// so the cost every reader of the board pays was set by whoever
		// applied the most. Newest first, because that is what a reader of
		// an open board came for.
		shown := all
		if len(shown) > IndexRequests {
			shown = shown[len(shown)-IndexRequests:]
		}
		b.WriteString("| # | Kind | Title | For | Asking | Status | Ballots |\n|---|---|---|---|---|---|---|\n")
		for _, r := range shown {
			yes, no := p.Board.Standing(r)
			b.WriteString("| [" + strconv.Itoa(r.ID) + "](" + rr.Link + ":request/" + strconv.Itoa(r.ID) + ")" +
				" | " + r.Kind.String() +
				" | " + ui.Cell(r.Title) +
				" | " + rr.who(r) +
				" | " + rr.ask(r) +
				" | " + r.Status.String() +
				" | " + strconv.Itoa(yes) + " for, " + strconv.Itoa(no) + " against" +
				" |\n")
		}
		if len(all) > IndexRequests {
			b.WriteString("\n_Showing the newest " + strconv.Itoa(IndexRequests) + " of " +
				strconv.Itoa(len(all)) + " requests._\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Where the money went\n\n")
	b.WriteString("[The ledger](" + rr.Link + ":ledger) lists every donation in and every tranche\n")
	b.WriteString("out, with the height, the payee and the milestone it paid for.\n\n")

	b.WriteString("## Calling it\n\n")
	b.WriteString("```sh\n")
	b.WriteString("# put money in\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Fund -send 5000000" + p.Denom + " ...\n")
	b.WriteString("# ask for some\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Apply \\\n")
	b.WriteString("  -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...\n")
	b.WriteString("# ask on behalf of someone who cannot pay the gas to ask\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func ApplyFor \\\n")
	b.WriteString("  -args g1... -args 'their account is empty' \\\n")
	b.WriteString("  -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...\n")
	b.WriteString("# decide (members only)\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Vote -args 1 -args true -args 'reason' ...\n")
	b.WriteString("# show your work, then get paid for it\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func SubmitProof \\\n")
	b.WriteString("  -args 1 -args 0 -args url -args 'https://...' -args 'what it is' ...\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Review -args 1 -args 0 -args true -args 'looks done' ...\n")
	b.WriteString("```\n")
	if rr.Footer != "" {
		b.WriteString("\n" + rr.Footer + "\n")
	}
	return b.String()
}

func (rr Renderer) request(raw string) string {
	id, err := strconv.Atoi(raw)
	if err != nil {
		return "# " + rr.Title + "\n\n`" + raw + "` is not a request number.\n"
	}
	r := rr.Program.Board.Get(id)
	if r == nil {
		return "# " + rr.Title + "\n\nThere is no request " + raw + ".\n"
	}
	board := rr.Program.Board

	var b strings.Builder
	b.WriteString("# Request " + strconv.Itoa(r.ID) + ": " + ui.Inline(r.Title) + "\n\n")
	b.WriteString("| Field | Value |\n|---|---|\n")
	b.WriteString("| Kind | " + r.Kind.String() + " |\n")
	b.WriteString("| Applicant | " + ui.AddrFull(r.Applicant) + " |\n")
	if r.OnBehalf() {
		b.WriteString("| Beneficiary | " + ui.AddrFull(r.Beneficiary) + " |\n")
	}
	if r.Kind == KindMember {
		b.WriteString("| Subject | " + ui.AddrFull(r.Subject) + " |\n")
		b.WriteString("| Effect | " + addRemove(r.Add) + " |\n")
	}
	b.WriteString("| Status | " + r.Status.String() + " |\n")
	b.WriteString("| Filed at height | " + i64(r.CreatedAt) + " |\n")
	if r.DecidedAt != 0 {
		b.WriteString("| Decided at height | " + i64(r.DecidedAt) + " |\n")
	}
	if r.Kind == KindGrant {
		b.WriteString("| Asking | " + rr.amount(r.Total()) + " |\n")
		b.WriteString("| Paid so far | " + rr.amount(r.Paid()) + " |\n")
		b.WriteString("| Still owed | " + rr.amount(r.Outstanding()) + " |\n")
	}
	b.WriteString("\n")

	if r.OnBehalf() {
		b.WriteString("## Filed for someone else\n\n")
		b.WriteString("The applicant is not the payee: every tranche of this request pays\n")
		b.WriteString(ui.AddrFull(r.Beneficiary) + ". Both addresses are barred from voting on it, and\n")
		b.WriteString("either may submit a proof. The reason given:\n\n")
		b.WriteString("> " + ui.Inline(r.Reason) + "\n\n")
		b.WriteString("Nothing checks that reason. It is a claim by the applicant, and the point of\n")
		b.WriteString("printing it here is that a member can check it before voting.\n\n")
	}

	if rr.Note != nil {
		if note := rr.Note(r); note != "" {
			b.WriteString(note + "\n\n")
		}
	}

	if r.Body != "" {
		b.WriteString("## The ask\n\n" + block(r.Body) + "\n\n")
	}

	b.WriteString("## Ballots\n\n")
	yes, no := board.Standing(r)
	recorded, against := r.Tally()
	b.WriteString("Needs " + strconv.Itoa(board.Majority(r)) + " of " + strconv.Itoa(board.Eligible(r)) +
		" eligible members. Standing: " + strconv.Itoa(yes) + " for, " + strconv.Itoa(no) + " against.\n")
	if recorded != yes || against != no {
		b.WriteString("On the record: " + strconv.Itoa(recorded) + " for, " + strconv.Itoa(against) +
			" against. The difference is ballots cast by people who have since left the board;\n")
		b.WriteString("they stay on the record and stop counting.\n")
	}
	b.WriteString("\n")
	if len(r.Votes) == 0 {
		b.WriteString("Nobody has voted yet.\n\n")
	} else {
		b.WriteString(rr.ballots(r.Votes, "for", "against"))
	}

	if r.Kind != KindGrant {
		return b.String()
	}

	b.WriteString("## Milestones\n\n")
	b.WriteString("Earned in order. The applicant submits a proof, the board reviews that proof,\n")
	b.WriteString("and the verdict that carries also moves the coins.\n\n")
	for i, m := range r.Milestones {
		b.WriteString("### " + strconv.Itoa(i+1) + ". " + ui.Inline(m.Title) + ": " + rr.amount(m.Amount) + "\n\n")
		b.WriteString(milestoneState(r, i, m) + "\n\n")
		for j, a := range m.Attempts {
			b.WriteString("**Proof " + strconv.Itoa(j+1) + "** (" + a.Proof.Kind + ", height " +
				i64(a.Proof.Height) + ", " + a.Outcome.String() + ")\n\n")
			b.WriteString(fence(a.Proof.Ref) + "\n\n")
			if a.Proof.Note != "" {
				b.WriteString(block(a.Proof.Note) + "\n\n")
			}
			if len(a.Reviews) == 0 {
				b.WriteString("No review yet.\n\n")
				continue
			}
			b.WriteString(rr.ballots(a.Reviews, "accept", "refuse"))
		}
	}
	return b.String()
}

func (rr Renderer) ledger() string {
	p := rr.Program
	var b strings.Builder
	b.WriteString("# " + rr.Title + ": the ledger\n\n")
	b.WriteString("Every coin in and every coin out, in the order it happened. Coins sent\n")
	b.WriteString("straight to " + ui.AddrFull(rr.Treasury) + " land in the treasury\n")
	b.WriteString("without appearing here, which is why `Fund` exists: it is the same transfer\n")
	b.WriteString("with a name attached.\n\n")

	b.WriteString("## In\n\n")
	if len(p.Donations) == 0 {
		b.WriteString("Nothing donated through `Fund` yet.\n\n")
	} else {
		b.WriteString("| Height | From | Amount |\n|---|---|---|\n")
		for _, d := range p.Donations {
			b.WriteString("| " + i64(d.Height) + " | " + ui.AddrFull(d.From) + " | " + rr.amount(d.Amount) + " |\n")
		}
		b.WriteString("\nTotal in: " + rr.amount(p.Raised()) + "\n\n")
	}

	b.WriteString("## Out\n\n")
	if len(p.Payments) == 0 {
		b.WriteString("No tranche has been released yet.\n\n")
	} else {
		b.WriteString("| Height | Request | Milestone | To | Amount |\n|---|---|---|---|---|\n")
		for _, pay := range p.Payments {
			b.WriteString("| " + i64(pay.Height) +
				" | [" + strconv.Itoa(pay.Request) + "](" + rr.Link + ":request/" + strconv.Itoa(pay.Request) + ")" +
				" | " + strconv.Itoa(pay.Milestone+1) +
				" | " + ui.AddrFull(pay.To) +
				" | " + rr.amount(pay.Amount) + " |\n")
		}
		b.WriteString("\nTotal out: " + rr.amount(p.Disbursed()) + "\n\n")
	}

	b.WriteString("Balance now: " + rr.amount(rr.Balance) + ". [Back to the board](" + rr.Link + ").\n")
	return b.String()
}

// ballots renders one decision's ballots, marking anyone who has since left
// the board: their vote stays on the record and stops counting.
func (rr Renderer) ballots(bs []Ballot, forLabel, againstLabel string) string {
	var b strings.Builder
	b.WriteString("| Member | Vote | Height | Reason |\n|---|---|---|---|\n")
	for _, v := range bs {
		who := ui.AddrFull(v.Voter)
		if !rr.Program.Board.IsMember(v.Voter) {
			who += " (left the board)"
		}
		vote := againstLabel
		if v.Approve {
			vote = forLabel
		}
		b.WriteString("| " + who + " | " + vote + " | " + i64(v.Height) + " | " + orDash(ui.Cell(v.Reason)) + " |\n")
	}
	b.WriteString("\n")
	return b.String()
}

func (rr Renderer) amount(n int64) string { return strconv.FormatInt(n, 10) + " " + rr.Program.Denom }

// who is the board index's "For" column: who this request would pay, marked
// when that is not the address that filed it.
func (rr Renderer) who(r *Request) string {
	if r.Kind == KindMember {
		return "-"
	}
	if r.OnBehalf() {
		return ui.Addr(r.Beneficiary) + " (filed by " + ui.AddrText(r.Applicant) + ")"
	}
	return ui.Addr(r.Applicant)
}

func (rr Renderer) ask(r *Request) string {
	if r.Kind == KindMember {
		return "nothing"
	}
	return rr.amount(r.Total())
}

func milestoneState(r *Request, i int, m *Milestone) string {
	switch {
	case m.Released:
		return "Released at height " + i64(m.ReleasedAt) + ", paid to " + ui.AddrFull(r.Payee()) + "."
	case r.Status != Approved:
		return "Locked: the request is " + r.Status.String() + "."
	case m.Current() != nil:
		return "A proof is under review."
	case i == r.Next():
		return "Waiting on a proof from the applicant."
	}
	return "Locked until milestone " + strconv.Itoa(r.Next()+1) + " is released."
}

func addRemove(add bool) string {
	if add {
		return "add to the board"
	}
	return "remove from the board"
}

// block and fence escape a multi-line, user-written string for its slot and
// then trim the sanitizer's own trailing newlines.
//
// The trim is not cosmetic. gno collapses two consecutive blank lines in an
// Example's output the way Go does, so any page that emits one can never be
// pinned by an ExampleRender, and the only test that proves a whole page is
// the one that stops working.
func block(s string) string { return strings.TrimSpace(sanitize.Block(s)) }

func fence(s string) string { return strings.TrimSpace(sanitize.CodeBlock(s)) }

func i64(n int64) string { return strconv.FormatInt(n, 10) }

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

package grants

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var (
	erin  = testutils.TestAddress("erin")  // applicant, mid-delivery
	frank = testutils.TestAddress("frank") // donor
	grace = testutils.TestAddress("grace") // beneficiary of a request she did not file
)

// demo drives a program through every state the renderer has to show: a
// membership change that executed, a donation, a grant carried over one
// dissent, a milestone released and paid, a proof the board refused, a second
// attempt still under review, and a request turned down flat.
//
// It uses the library's own API only, so if a rule changes under it the
// pinned pages below move and the diff says exactly what changed.
func demo() *Program {
	p := NewProgram("ugnot", alice, bob, carol)
	p.Fund(frank, 3000, 100)

	m, _ := p.Board.SubmitMemberChange(alice, dave, true,
		"Reviewed six of the last eight applications from the outside. Give them the seat.", 100)
	p.Board.Vote(alice, m.ID, true, "Proposed it.", 101)
	p.Board.Vote(bob, m.ID, true, "No objection.", 102)

	g, _ := p.Apply(erin, "Port the p/nt/avl benchmarks to gno",
		"Three weeks. A benchmark harness, a report on the tree rebalancing costs, "+
			"and a PR against the monorepo.",
		"harness merged:1200,report published:800", 110)
	p.Board.Vote(alice, g.ID, true, "Cheap for what it tells us.", 111)
	p.Board.Vote(bob, g.ID, false, "The second milestone is vague.", 112)
	p.Board.Vote(carol, g.ID, true, "Vague but bounded. Worth it.", 113)
	p.Board.Vote(dave, g.ID, true, "Agreed with carol.", 114)

	p.Board.SubmitProof(erin, g.ID, 0, Proof{
		Kind: "url", Ref: "https://github.com/gnolang/gno/pull/9999",
		Note: "Harness merged, 14 benchmarks, runs in CI.", Height: 120,
	})
	p.Review(alice, g.ID, 0, true, "Merged, I reviewed it.", 121, 3000)
	p.Review(carol, g.ID, 0, true, "Confirmed.", 122, 3000)
	p.Review(dave, g.ID, 0, true, "Confirmed.", 123, 3000)

	p.Board.SubmitProof(erin, g.ID, 1, Proof{Kind: "text", Ref: "it is basically done", Height: 130})
	p.Review(alice, g.ID, 1, false, "That is not a report.", 131, 1800)
	p.Review(bob, g.ID, 1, false, "Agreed, no numbers.", 132, 1800)
	p.Review(carol, g.ID, 1, false, "Same.", 133, 1800)

	p.Board.SubmitProof(erin, g.ID, 1, Proof{
		Kind: "url", Ref: "https://example.com/avl-rebalancing-costs",
		Note: "Rewritten with the measurements.", Height: 140,
	})
	p.Review(alice, g.ID, 1, true, "Much better.", 141, 1800)

	o, _ := p.ApplyFor(erin, grace, "Her account is empty, so she cannot pay the gas to file this herself.",
		"Translate the onboarding guide to Portuguese",
		"One pass over the eight pages, reviewed by a second speaker.",
		"translation merged:600", 145)
	p.Board.Vote(alice, o.ID, true, "Cheap, and we have no pt-BR page at all.", 146)
	p.Board.Vote(bob, o.ID, true, "Fine.", 147)
	p.Board.Vote(carol, o.ID, true, "Fine.", 148)

	n, _ := p.Apply(mallory, "Rewrite gnoweb in a different framework",
		"Six months, one person, no migration plan.", "the rewrite:250000", 150)
	p.Board.Vote(alice, n.ID, false, "No migration plan and no second maintainer.", 151)
	p.Board.Vote(bob, n.ID, false, "Out of scope for this board.", 152)
	p.Board.Vote(carol, n.ID, false, "Same.", 153)
	return p
}

