// injected is every dangerous markdown sequence a caller can type, in one
// string, so a slot that forgets to escape shows up as a live link or a
// gnoweb tag in the assertions below rather than on a deployed page.
const injected = "[click](https://evil.example) ![x](https://evil.example/p.png) " +
	"<gno-columns> | fake | cell | ```\nsecond line\n"

// injectedShort is the same attack inside the 100-character limit a title and
// a milestone name are held to.
const injectedShort = "[click](https://evil.example) <gno-columns>|x|\nnext"

// TestEveryCallerSuppliedStringIsEscaped drives one board through every slot
// a caller controls and asserts that none of them can reshape the page.
//
// The bar is not the same in every slot, on purpose. A one-line slot (a
// title, a milestone name, the reason on a ballot, the reason for filing on
// someone else's behalf) is chrome the page lays out, so nothing a caller
// typed may survive as markup there. A prose slot (the body of an
// application, the note on a proof) goes through sanitize.Block, which
// PRESERVES inline links and emphasis by design: a grant application whose
// link to the merged PR renders as literal text is a worse page, and the
// sanitizer's own contract is that prose formats. What Block still kills is
// everything structural, so the paragraph cannot leave its paragraph.
//
// Assertions are on the dangerous SEQUENCE, never on the exact escaped bytes:
// those belong to the sanitizer, they change when it changes, and a test that
// pins them fails for the wrong reason.
func TestEveryCallerSuppliedStringIsEscaped(t *testing.T) {
	p := NewProgram("ugnot", alice, bob)
	r, err := p.ApplyFor(erin, grace, injected, injectedShort, injected, injectedShort+":100", 10)
	urequire.NoError(t, err)
	p.Board.Vote(alice, r.ID, true, injected, 11)
	p.Board.Vote(bob, r.ID, true, injected, 12)
	urequire.NoError(t, p.Board.SubmitProof(erin, r.ID, 0, Proof{
		Kind: "url", Ref: injected, Note: injected, Height: 13,
	}))
	p.Board.Review(alice, r.ID, 0, false, injected, 14)

	v := Renderer{Program: p, Title: "Board", Path: "gno.land/r/x/v0", Link: "/r/x/v0", Balance: 0}

	// Every structural line of every page: a table row, a heading, a
	// blockquote. Nothing a caller typed may render as markup in one.
	for _, page := range []string{"", "request/1", "ledger"} {
		for _, line := range strings.Split(v.Render(page), "\n") {
			if !strings.HasPrefix(line, "|") && !strings.HasPrefix(line, "#") &&
				!strings.HasPrefix(line, ">") {
				continue
			}
			for _, dead := range []string{"](http", "![", "<gno-"} {
				uassert.False(t, strings.Contains(line, dead),
					"page "+page+" line still carries "+dead+": "+line)
			}
		}
	}

	// A table row keeps exactly its own cells: an unescaped pipe would open a
	// column and an unescaped newline would end the row early, and both
	// reshape the table silently rather than failing.
	for _, line := range strings.Split(v.Render("request/1"), "\n") {
		if !strings.HasPrefix(line, "| `"+alice.String()+"`") {
			continue
		}
		uassert.Equal(t, 5, strings.Count(line, "|")-strings.Count(line, "\\|"),
			"the ballot row kept its four cells: "+line)
	}

	// An escaper that ate the content would pass every assertion above.
	out := v.Render("request/1")
	uassert.True(t, strings.Contains(out, "click"), "the readable text survived")
	uassert.True(t, strings.Contains(out, "second line"), "the second line survived")

	// The structural attack is dead in the prose slots too, even though the
	// link in them is deliberately alive.
	body := out[strings.Index(out, "## The ask"):strings.Index(out, "## Ballots")]
	uassert.False(t, strings.Contains(body, "\n<gno-"), "no gnoweb tag at a line start")
	uassert.False(t, strings.Contains(body, "\n| "), "prose cannot open a table")
	uassert.False(t, strings.Contains(body, "\n#"), "prose cannot forge a heading")
}

package reactions

// The palette: the closed set of reactions, and the only moderation policy
// this package has.
//
// It is closed on purpose. A free-text reaction is a comment, a comment needs
// moderation, and moderation is the thing worth not building. Six is enough to
// say something and few enough to fit on one line on a phone.
//
// Every glyph here is a SINGLE codepoint with no variation selector (no
// U+FE0F) and no zero-width joiner. That is a constraint, not a coincidence:
// these strings pass through a markdown escaper that strips zero-width and
// bidi characters, and a glyph that needs U+FE0F to render would come out the
// other side as its bare monochrome form. ❤️ is the obvious casualty, which is
// why "heart" is 💜 (U+1F49C), a codepoint that is a colour emoji on its own.
const (
	// KeyUp is the default, first in the strip.
	KeyUp = "up"
	// KeyHeart is affection rather than agreement.
	KeyHeart = "heart"
	// KeyFire is "this is good".
	KeyFire = "fire"
	// KeyParty is a congratulation.
	KeyParty = "party"
	// KeyRocket is "ship it".
	KeyRocket = "rocket"
	// KeyEyes is "I am watching this", the only one that is not praise.
	KeyEyes = "eyes"
)

// order is the display order of the palette, which is also the order the
// strip renders in. A slice and not a map range: gno map iteration order is
// unspecified, and a Render that reshuffles between identical calls is a
// consensus bug.
var order = []string{KeyUp, KeyHeart, KeyFire, KeyParty, KeyRocket, KeyEyes}

// palette maps a key to its glyph. Written as \U escapes rather than literal
// emoji so that the source says exactly which codepoint it means and a review
// diff cannot hide a lookalike.
var palette = map[string]string{
	KeyUp:     "\U0001F44D", // 👍
	KeyHeart:  "\U0001F49C", // 💜
	KeyFire:   "\U0001F525", // 🔥
	KeyParty:  "\U0001F389", // 🎉
	KeyRocket: "\U0001F680", // 🚀
	KeyEyes:   "\U0001F440", // 👀
}

// Keys returns the palette keys in display order. The returned slice is a copy,
// so a caller cannot reorder the palette for everyone else.
func Keys() []string {
	out := make([]string, len(order))
	copy(out, order)
	return out
}

// Valid reports whether key names a reaction in the palette.
func Valid(key string) bool {
	_, ok := palette[key]
	return ok
}

// Emoji returns the glyph for a palette key, or "" when the key is not one.
func Emoji(key string) string { return palette[key] }

// Package reactions is the engine behind an embeddable reaction block: the
// one-click "👍 3 · 🔥 1" strip a realm drops into its own Render, keyed on
// the PAGE it is showing rather than on the realm that stores it.
//
// That indirection is the whole idea, and it is the one the web already
// settled on: a single hosted widget, embedded verbatim everywhere, deciding
// what to show from the page identifier it is handed. One realm holds every
// tally, every host realm ships the same two lines, and no host realm stores
// anything.
//
// # The model
//
// A [Board] maps a page key to a [Page]. A page holds three things and
// deliberately nothing else:
//
//   - a count per palette key,
//   - the CURRENT reaction of each address, so a tally counts addresses and
//     not clicks, and so a reader can change their mind,
//   - the last reaction: which key, from whom, at what height.
//
// There is no text anywhere, which is the point. Text needs moderation;
// a closed palette of six emoji does not.
//
// # Keys are names, not glyphs
//
// A reaction is stored and addressed as an ASCII name ("up", "fire"), and the
// glyph is presentation. A name survives a URL query parameter, an avl key and
// a markdown escaper without a single encoding question, and the palette can
// gain a glyph without rewriting stored state.
//
// # Page keys
//
// A page key is a package path (the full one, chain domain included, as
// unsafe.CurrentRealm().PkgPath() reports it). [ValidPage] is what bounds this
// package's exposure: a key is path-shaped, ASCII, and at most [MaxPageLen]
// bytes, so a stored key can never be a markdown payload, a bidi run or an
// unbounded blob. This package only ever puts it in a URL; a realm that shows
// the key as text escapes it there, because a validator and an escaper protect
// against different mistakes.
package reactions

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/avl/v0"
)

// MaxPageLen is the longest page key accepted. Comfortably past the longest
// real package path (the deepest in moul/gno-contracts is 34 bytes) and short
// enough that a key can never be a payload.
const MaxPageLen = 120

// Board is a set of pages, each with its own tally. The zero value is not
// usable; call [NewBoard].
type Board struct {
	pages *avl.Tree // page key -> *Page
}

// NewBoard returns an empty board.
func NewBoard() *Board { return &Board{pages: avl.NewTree()} }

// Page is one page's tally.
//
// Every read method is nil-safe and answers as if the page were empty, so a
// caller can hand [Board.Page]'s result straight to [Block] without checking.
type Page struct {
	counts  *avl.Tree // palette key -> int
	by      *avl.Tree // address string -> palette key
	lastKey string
	lastWho address
	lastAt  int64
}

// React records who's reaction on page, replacing whatever they had there
// before. It reports whether anything was stored: false means the page key or
// the palette key was rejected, and nothing changed.
//
// height is passed in rather than read from the chain, so this package stays
// testable without a realm and so the caller decides what "when" means.
func (b *Board) React(page string, who address, key string, height int64) bool {
	if !ValidPage(page) || !Valid(key) {
		return false
	}
	p := b.page(page)

	// Replacing a reaction decrements the old bucket first. Without this a
	// reader who clicks twice counts twice, and the tally stops meaning
	// "how many addresses", which is the only thing it is allowed to mean.
	if prev := p.Of(who); prev != "" {
		if prev == key {
			// Same key again: still record it as the last reaction, since the
			// click happened, but leave the counts alone.
			p.lastKey, p.lastWho, p.lastAt = key, who, height
			return true
		}
		p.add(prev, -1)
	}
	p.by.Set(who.String(), key)
	p.add(key, 1)
	p.lastKey, p.lastWho, p.lastAt = key, who, height
	return true
}

// Unreact removes who's reaction from page. It reports whether there was one.
//
// The last-reaction line is deliberately NOT rewound: it records an event that
// happened, and recomputing it would mean walking every address on the page.
// [Page.Last] therefore keeps naming a reaction nobody holds any more, which is
// the honest answer to "what happened here last". What is shown is a separate
// decision, and [Summary] makes it: a page with no reactors left renders as
// empty, not as a withdrawn reaction.
func (b *Board) Unreact(page string, who address) bool {
	p := b.Page(page)
	if p == nil {
		return false
	}
	prev := p.Of(who)
	if prev == "" {
		return false
	}
	p.by.Remove(who.String())
	p.add(prev, -1)
	return true
}

// Page returns the tally for a page, or nil when nothing was ever recorded
// there. The nil is safe to use: every [Page] read method handles it.
func (b *Board) Page(page string) *Page {
	v := b.pages.Get(page)
	if v == nil {
		return nil
	}
	return v.(*Page)
}

// page returns the tally for a page, creating it if needed.
func (b *Board) page(key string) *Page {
	if p := b.Page(key); p != nil {
		return p
	}
	p := &Page{counts: avl.NewTree(), by: avl.NewTree()}
	b.pages.Set(key, p)
	return p
}

// Pages reports how many pages have ever been reacted to.
func (b *Board) Pages() int { return b.pages.Size() }

// Each visits every page in key order until fn returns true.
func (b *Board) Each(fn func(page string, p *Page) bool) {
	b.pages.Iterate("", "", func(key string, value any) bool {
		return fn(key, value.(*Page))
	})
}

// add changes a bucket by delta, dropping it when it reaches zero so an
// emptied page leaves no residue behind.
func (p *Page) add(key string, delta int) {
	n := p.Count(key) + delta
	if n <= 0 {
		p.counts.Remove(key)
		return
	}
	p.counts.Set(key, n)
}

// Count reports how many addresses currently hold this reaction.
func (p *Page) Count(key string) int {
	if p == nil {
		return 0
	}
	v := p.counts.Get(key)
	if v == nil {
		return 0
	}
	return v.(int)
}

// Total is the number of addresses reacting to this page. It equals the sum of
// every bucket, because an address holds at most one reaction.
func (p *Page) Total() int {
	if p == nil {
		return 0
	}
	return p.by.Size()
}

// Of returns who's current reaction key, or "" when they have none.
func (p *Page) Of(who address) string {
	if p == nil {
		return ""
	}
	v := p.by.Get(who.String())
	if v == nil {
		return ""
	}
	return v.(string)
}

// Last returns the most recent reaction: its palette key, who made it, and the
// height it was made at. The key is "" when the page has never been reacted to.
//
// It can name a reaction that is no longer counted, because [Board.Unreact]
// does not rewind it. That is the honest answer to "what happened here last",
// which is the question the line under the block asks.
func (p *Page) Last() (key string, who address, height int64) {
	if p == nil {
		return "", "", 0
	}
	return p.lastKey, p.lastWho, p.lastAt
}

// ValidPage reports whether page is an acceptable key.
//
// The rule is "a gnoweb render path, and nothing that is not one": at least one
// "/", no empty element, no leading or trailing "/", and only lowercase ASCII
// letters, digits, ".", "-", "_", ":" and "/". That excludes every character a
// markdown escaper exists for, plus every byte above ASCII, so a stored key
// cannot carry a bidi run, a zero-width joiner or an image.
//
// Two of the exclusions are STRUCTURAL and not about markdown, so widening this
// set is not free. gnoweb parses a render path as `<path>[:<args>][$<webargs>]`
// and cuts on "$" BEFORE it cuts on ":" (gno.land/pkg/gnoweb/weburl/url.go,
// ParseFromURL, read 2026-09-28), so a "$" in a key would truncate it on the
// way back in, and a "%" would be eaten by the unescape that follows. ":" is
// safe only because that second cut takes the FIRST colon, which leaves the
// rest of the key intact however many it carries.
//
// ":" is in the set because a host realm keying the block per article wants the
// path it already serves: "gno.land/r/you/blog:hello-world".
func ValidPage(page string) bool {
	if page == "" || len(page) > MaxPageLen {
		return false
	}
	if strings.HasPrefix(page, "/") || strings.HasSuffix(page, "/") ||
		strings.Contains(page, "//") || !strings.Contains(page, "/") {
		return false
	}
	for i := 0; i < len(page); i++ {
		c := page[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '/' || c == '.' || c == '-' || c == '_' || c == ':':
		default:
			return false
		}
	}
	return true
}

// Block renders the embeddable widget: the clickable palette with its counts,
// then one line saying what happened here last.
//
// realmPath is the realm that owns React, given as the full package path from
// its gnomod.toml module line. It is a parameter and not a constant because
// this package is the engine and not the deployment: a second reactions realm,
// on another chain or in a test, renders through the same code.
//
// page appears only in URL positions here: as a txlink query argument, which
// txlink percent-encodes, and inside [PageURL]. Nothing renders it as text, and
// [ValidPage]'s charset is what keeps the [PageURL] form safe. A realm showing
// the key itself must still run it through ui.Inline.
//
// The result ends with a single newline and contains exactly one blank line,
// so it drops into a host realm's Render between two sections without a
// separator of its own.
func Block(realmPath, page string, p *Page) string {
	var b strings.Builder
	for i, key := range order {
		if i > 0 {
			b.WriteString(" ")
		}
		title := palette[key]
		if n := p.Count(key); n > 0 {
			title += " " + strconv.Itoa(n)
		}
		b.WriteString(ui.ActionIn(realmPath, title, "React", "page", page, "key", key))
	}
	b.WriteString("\n\n")
	b.WriteString(md.Italic(Summary(realmPath, page, p)))
	b.WriteString("\n")
	return b.String()
}

// Summary is the one line under the block: the last reaction, and a link to
// the page's own view on the reactions realm. Plain markdown, no wrapper, so a
// caller can put it somewhere else.
func Summary(realmPath, page string, p *Page) string {
	key, who, _ := p.Last()
	n := p.Total()

	// Two different ways to have nothing to say, and both have to be checked.
	// key == "" is a page nobody ever touched. n == 0 is a page whose reactors
	// have all left: [Board.Unreact] deliberately does not rewind the last
	// reaction, so key still names one. Gating on key alone would print
	// "last <emoji> by <addr> - 0 reactions" above an empty strip, which
	// contradicts itself and keeps attributing a reaction its author took back.
	if key == "" || n == 0 {
		return "no reactions yet"
	}
	label := strconv.Itoa(n) + " reaction"
	if n != 1 {
		label += "s"
	}
	return "last " + palette[key] + " by " + ui.Addr(who) + " · " +
		md.Link(label, PageURL(realmPath, page))
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it. Derived here rather than read from chain/runtime so this
// package keeps no chain import of its own and the rule stays in one place.
// Returns "" for something that is not a package path.
func RealmURL(realmPath string) string {
	i := strings.Index(realmPath, "/")
	if i < 0 {
		return ""
	}
	return realmPath[i:]
}

// PageURL is the link to one page's view on the reactions realm: [RealmURL]
// with the page as the gnoweb render argument after a colon.
func PageURL(realmPath, page string) string {
	base := RealmURL(realmPath)
	if base == "" {
		return ""
	}
	return base + ":" + page
}

package reactions

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const (
	realmPath = "gno.land/r/test/reactions/v0"
	homePage  = "gno.land/r/moul/home"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

func TestValidPage(t *testing.T) {
	cases := []struct {
		page string
		want bool
	}{
		{"gno.land/r/moul/home", true},
		{"gno.land/p/moul/kit/ui/v0", true},
		{"gno.land/r/moul/x/daily/b58demo", true},
		{"a/b", true},
		{"gno.land/r/you/blog:hello-world", true}, // one page per article
		{"", false},
		{"nolslash", false},
		{"/leading", false},
		{"trailing/", false},
		{"double//slash", false},
		{"gno.land/r/MOUL/home", false},                   // uppercase is not a path here
		{"gno.land/r/moul/home ", false},                  // a space is not path-shaped
		{"gno.land/r/[x](http://e.vil)", false},           // a markdown link cannot be a key
		{"gno.land/r/‮moul/home", false},             // bidi override
		{strings.Repeat("a/", MaxPageLen) + "b", false},   // over the cap
		{strings.Repeat("a", MaxPageLen-2) + "/b", true},  // exactly at the cap
		{strings.Repeat("a", MaxPageLen-1) + "/b", false}, // one byte over
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidPage(tc.page), tc.page)
	}
}

func TestPaletteIsClosed(t *testing.T) {
	uassert.Equal(t, 6, len(Keys()))
	for _, k := range Keys() {
		uassert.True(t, Valid(k), k)
		uassert.NotEqual(t, "", Emoji(k), k)
	}
	uassert.False(t, Valid("poop"))
	uassert.Equal(t, "", Emoji("poop"))

	// Keys returns a copy: reordering it must not reorder the palette.
	ks := Keys()
	ks[0] = "clobbered"
	uassert.Equal(t, KeyUp, Keys()[0])
}

// TestNilPageReadsAsEmpty is what lets a host realm render the block without
// ever checking whether the page exists.
func TestNilPageReadsAsEmpty(t *testing.T) {
	var p *Page
	uassert.Equal(t, 0, p.Count(KeyUp))
	uassert.Equal(t, 0, p.Total())
	uassert.Equal(t, "", p.Of(alice))
	key, who, at := p.Last()
	uassert.Equal(t, "", key)
	uassert.Equal(t, address(""), who)
	uassert.Equal(t, int64(0), at)
}

func TestReactCountsAddressesNotClicks(t *testing.T) {
	b := NewBoard()

	uassert.True(t, b.React(homePage, alice, KeyUp, 100))
	uassert.True(t, b.React(homePage, alice, KeyUp, 101))
	uassert.True(t, b.React(homePage, alice, KeyUp, 102))

	p := b.Page(homePage)
	uassert.Equal(t, 1, p.Count(KeyUp), "three clicks from one address is one reaction")
	uassert.Equal(t, 1, p.Total())

	// The repeat still counts as the last event, because it happened.
	_, _, at := p.Last()
	uassert.Equal(t, int64(102), at)
}

func TestChangingReactionMovesTheCount(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	b.React(homePage, bob, KeyUp, 101)
	b.React(homePage, alice, KeyFire, 102)

	p := b.Page(homePage)
	uassert.Equal(t, 1, p.Count(KeyUp))
	uassert.Equal(t, 1, p.Count(KeyFire))
	uassert.Equal(t, 2, p.Total(), "changing a reaction never changes the head count")
	uassert.Equal(t, KeyFire, p.Of(alice))
	uassert.Equal(t, KeyUp, p.Of(bob))
}

func TestUnreact(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)

	uassert.False(t, b.Unreact("gno.land/r/never/touched", alice), "no page")
	uassert.False(t, b.Unreact(homePage, bob), "no reaction of bob's")
	uassert.True(t, b.Unreact(homePage, alice))
	uassert.False(t, b.Unreact(homePage, alice), "removing twice is not an error, just false")

	p := b.Page(homePage)
	uassert.Equal(t, 0, p.Count(KeyUp), "an emptied bucket leaves no residue")
	uassert.Equal(t, 0, p.Total())

	// Last is deliberately not rewound: it records what happened.
	key, who, _ := p.Last()
	uassert.Equal(t, KeyUp, key)
	uassert.Equal(t, alice, who)
}

func TestReactRejects(t *testing.T) {
	b := NewBoard()
	uassert.False(t, b.React("not a path", alice, KeyUp, 1), "bad page")
	uassert.False(t, b.React(homePage, alice, "poop", 1), "key outside the palette")
	uassert.Equal(t, 0, b.Pages(), "a rejected reaction creates no page")
}

func TestPagesAreIndependentAndOrdered(t *testing.T) {
	b := NewBoard()
	b.React("gno.land/r/moul/home", alice, KeyUp, 1)
	b.React("gno.land/r/moul/blog", bob, KeyFire, 2)
	b.React("gno.land/r/moul/blog", carol, KeyFire, 3)

	uassert.Equal(t, 2, b.Pages())
	uassert.Equal(t, 1, b.Page("gno.land/r/moul/home").Total())
	uassert.Equal(t, 2, b.Page("gno.land/r/moul/blog").Total())

	var seen []string
	b.Each(func(page string, p *Page) bool {
		seen = append(seen, page)
		return false
	})
	uassert.Equal(t, "gno.land/r/moul/blog,gno.land/r/moul/home", strings.Join(seen, ","),
		"Each walks in key order, so a Render built from it is stable")
}

func TestEachStopsOnTrue(t *testing.T) {
	b := NewBoard()
	b.React("gno.land/r/a/one", alice, KeyUp, 1)
	b.React("gno.land/r/b/two", alice, KeyUp, 2)

	n := 0
	b.Each(func(page string, p *Page) bool {
		n++
		return true
	})
	uassert.Equal(t, 1, n)
}

func TestRealmAndPageURL(t *testing.T) {
	uassert.Equal(t, "/r/test/reactions/v0", RealmURL(realmPath))
	uassert.Equal(t, "", RealmURL("nodomain"))
	uassert.Equal(t, "/r/test/reactions/v0:gno.land/r/moul/home",
		PageURL(realmPath, homePage))
	uassert.Equal(t, "", PageURL("nodomain", homePage))
}

// TestBlockShape pins the embed byte for byte. It is a Test and not an Example
// because the block contains a blank line, and gno collapses consecutive blank
// lines inside an // Output: block.
func TestBlockShape(t *testing.T) {
	b := NewBoard()

	empty := "[\U0001F44D](/r/test/reactions/v0$help&func=React&key=up&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F49C](/r/test/reactions/v0$help&func=React&key=heart&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F525](/r/test/reactions/v0$help&func=React&key=fire&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F389](/r/test/reactions/v0$help&func=React&key=party&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F680](/r/test/reactions/v0$help&func=React&key=rocket&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F440](/r/test/reactions/v0$help&func=React&key=eyes&page=gno.land%2Fr%2Fmoul%2Fhome)" +
		"\n\n*no reactions yet*\n"
	uassert.Equal(t, empty, Block(realmPath, homePage, b.Page(homePage)),
		"a page nobody has reacted to still renders the whole strip")

	b.React(homePage, alice, KeyUp, 100)
	b.React(homePage, bob, KeyUp, 101)
	b.React(homePage, carol, KeyFire, 102)

	got := Block(realmPath, homePage, b.Page(homePage))
	uassert.True(t, strings.Contains(got, "[\U0001F44D 2]"), "the count rides in the link title")
	uassert.True(t, strings.Contains(got, "[\U0001F525 1]"))
	uassert.True(t, strings.Contains(got, "[\U0001F389]"), "an empty bucket shows no zero")
	uassert.True(t, strings.Contains(got, "last \U0001F525 by "))
	uassert.True(t, strings.Contains(got, "[3 reactions](/r/test/reactions/v0:gno.land/r/moul/home)"))
	uassert.True(t, strings.HasSuffix(got, "*\n"), "one trailing newline, so it drops into a Render")
}

func TestSummaryPluralises(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	uassert.True(t, strings.Contains(Summary(realmPath, homePage, b.Page(homePage)), "[1 reaction]"))

	b.React(homePage, bob, KeyUp, 101)
	uassert.True(t, strings.Contains(Summary(realmPath, homePage, b.Page(homePage)), "[2 reactions]"))
}

// TestEmojiSurviveTheEscaper is the reason the palette holds no U+FE0F and no
// zero-width joiner: ui.ActionIn escapes the link title, and that escaper
// strips exactly those. A glyph that does not survive it renders as a
// monochrome box on every page that embeds the block.
func TestEmojiSurviveTheEscaper(t *testing.T) {
	b := NewBoard()
	for _, k := range Keys() {
		got := Block(realmPath, homePage, b.Page(homePage))
		uassert.True(t, strings.Contains(got, "["+Emoji(k)+"]"), k)
	}
}

// TestSummaryGoesEmptyWhenEveryoneLeaves is the interaction between the two
// halves of Last: it is deliberately not rewound by Unreact, so the summary has
// to decide for itself whether there is anything left to summarise. Gating on
// the last key alone would print "last 👍 by g1… · 0 reactions" above an empty
// strip, which contradicts itself and keeps attributing a reaction its author
// took back.
func TestSummaryGoesEmptyWhenEveryoneLeaves(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	b.Unreact(homePage, alice)

	p := b.Page(homePage)
	uassert.Equal(t, 0, p.Total(), "the tally is empty")

	key, _, _ := p.Last()
	uassert.Equal(t, KeyUp, key, "and Last still records the event, by design")

	uassert.Equal(t, "no reactions yet", Summary(realmPath, homePage, p),
		"so the summary shows the empty state rather than a withdrawn reaction")

	uassert.True(t, strings.HasSuffix(Block(realmPath, homePage, p), "*no reactions yet*\n"))
}

package toolbox

import "gno.land/p/nt/bptree/v0"

// Catalog is the directory itself: tools keyed by slug, ordered by it.
//
// The zero value is an empty, usable catalog. A Catalog is a HANDLE: copying
// one shares the directory, and a write through either copy is seen through
// both, the way copying a map does. A copy of a zero value that was never
// written is a separate empty catalog.
//
// # Why a tree and not a sorted slice
//
// A sorted slice is cheaper to READ at the size a directory actually reaches:
// at n = 100 one cold operation costs 92,571 gas against a fanout-128 tree's
// 230,754 (`gnobench`, gno master 1fc4c140e, 2026-09-29). It is still the
// wrong structure, for two reasons that outlive the gas.
//
// A slice is ONE persisted object, so every write rewrites all of it: O(n) per
// transaction and O(n^2) over n of them. That costs nothing for a hub whose
// catalog is compiled in and never written after deploy, and it is the whole
// bill for one that accepts registration, which is the other half of what this
// package is for. Removing is worse than writing: shortening a slice in place
// keeps the peak allocation charged and refunds no deposit at all.
//
// And the ordering comes free. A slug-keyed tree iterates in slug order, which
// is the order every listing here wants, rather than a hand-rolled binary
// search that has to be kept correct.
type Catalog struct {
	s *state
}

// state is everything a Catalog holds, behind one pointer so that a copy of
// the handle cannot split the tree from the counter that describes it.
//
// Embedding [bptree.BPTree] by value was the first shape here and it is wrong
// for exactly that reason: the tree's root is a pointer and its size is an int,
// so `b := a; b.Set(x)` would thread the new node onto the tree both of them
// see while incrementing only b's size. a.Len() would say 1 while a.Get(x)
// found the entry. One pointer, or two readers of the same directory disagree
// about how big it is.
type state struct {
	tools *bptree.BPTree
}

// Fanout is the B+ tree fanout this package uses.
//
// 32 rather than 128 because a tool can be unregistered, and wide nodes lose
// most on removal: a removal shifts every later value in its leaf and rewrites
// each one. Same choice, and the same reason, as
// [gno.land/p/moul/kit/index](/p/moul/kit/index/v0).
const Fanout = 32

// New returns an empty catalog. It is the zero value, spelled out for a caller
// who prefers a constructor.
func New() *Catalog { return &Catalog{} }

// init materialises the state. Called by every mutating method, so the zero
// value works without a constructor. The tree is created with the state, so a
// non-nil state always has one.
func (c *Catalog) init() {
	if c.s == nil {
		c.s = &state{tools: bptree.NewBPTreeN(Fanout)}
	}
}

// Set inserts t, replacing any tool already under its slug.
//
// Replacing rather than refusing is what makes a hub's init idempotent: a
// compiled-in catalog is rebuilt from source on every redeploy, and a second
// Set of the same slug is a corrected description rather than a collision.
func (c *Catalog) Set(t Tool) error {
	if err := t.Validate(); err != nil {
		return err
	}
	c.init()
	c.s.tools.Set(t.Slug, copyTool(t))
	return nil
}

// Remove deletes the tool under slug. It returns [ErrUnknownSlug] when there
// is none, so a realm removing an entry it believes in learns that it is gone.
func (c *Catalog) Remove(slug string) error {
	if c.s == nil {
		return ErrUnknownSlug
	}
	if _, removed := c.s.tools.Remove(slug); !removed {
		return ErrUnknownSlug
	}
	return nil
}

// Get returns the tool under slug.
func (c *Catalog) Get(slug string) (Tool, bool) {
	if c.s == nil {
		return Tool{}, false
	}
	v := c.s.tools.Get(slug)
	if v == nil {
		return Tool{}, false
	}
	return copyTool(v.(Tool)), true
}

// Has reports whether slug is in the catalog.
func (c *Catalog) Has(slug string) bool {
	return c.s != nil && c.s.tools.Has(slug)
}

// Len is how many tools the catalog holds.
func (c *Catalog) Len() int {
	if c.s == nil {
		return 0
	}
	return c.s.tools.Size()
}

// List returns every tool, in slug order.
func (c *Catalog) List() []Tool {
	if c.s == nil {
		return nil
	}
	out := make([]Tool, 0, c.s.tools.Size())
	c.s.tools.Iterate("", "", func(_ string, v any) bool {
		out = append(out, copyTool(v.(Tool)))
		return false
	})
	return out
}

// ByTag returns every tool carrying tag, in slug order. An empty tag matches
// nothing rather than everything: it is almost always an unset field.
func (c *Catalog) ByTag(tag string) []Tool {
	if tag == "" || c.s == nil {
		return nil
	}
	var out []Tool
	c.s.tools.Iterate("", "", func(_ string, v any) bool {
		if t := v.(Tool); t.HasTag(tag) {
			out = append(out, copyTool(t))
		}
		return false
	})
	return out
}

// Tags returns every tag used by any tool, each once, in first-seen order
// within slug order. Deterministic, which iterating a map would not be.
func (c *Catalog) Tags() []string {
	if c.s == nil {
		return nil
	}
	var out []string
	c.s.tools.Iterate("", "", func(_ string, v any) bool {
		for _, tag := range v.(Tool).Tags {
			if !contains(out, tag) {
				out = append(out, tag)
			}
		}
		return false
	})
	return out
}

// copyTool deep-copies the one field that is not a scalar.
//
// A Tool is a value, so handing one out already copies Slug, Path, Title and
// Desc. Tags is a slice: the struct copy duplicates the header and shares the
// backing array, so `c.List()[0].Tags[0] = "x"` would reach into the catalog
// and change what every later read returns. Copied on the way in as well as on
// the way out, or the caller of Set keeps a handle on stored state.
func copyTool(t Tool) Tool {
	if t.Tags == nil {
		return t
	}
	tags := make([]string, len(t.Tags))
	copy(tags, t.Tags)
	t.Tags = tags
	return t
}

func contains(haystack []string, needle string) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

package toolbox

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func tool(slug string, tags ...string) Tool {
	return Tool{
		Slug:  slug,
		Path:  "gno.land/r/moul/toolbox/" + slug + "/v0",
		Title: slug,
		Desc:  "the " + slug + " tool",
		Tags:  tags,
	}
}

func slugs(tools []Tool) []string {
	out := make([]string, len(tools))
	for i, t := range tools {
		out[i] = t.Slug
	}
	return out
}

// TestCatalogCopyIsAHandle is the shape bug the state pointer exists to stop.
// With the tree embedded by value, the root is a pointer and the size an int,
// so a write through a copy threaded the node onto the tree both of them saw
// while incrementing only the copy's counter: a.Len() said 1 while a.Get found
// the second entry.
func TestCatalogCopyIsAHandle(t *testing.T) {
	a := New()
	uassert.NoError(t, a.Set(tool("amm")))

	b := *a
	uassert.NoError(t, b.Set(tool("usernames")))

	uassert.Equal(t, 2, a.Len())
	uassert.Equal(t, 2, b.Len())
	uassert.Equal(t, a.Len(), len(a.List()))
	uassert.True(t, a.Has("usernames"))

	uassert.NoError(t, b.Remove("amm"))
	uassert.Equal(t, 1, a.Len())
	uassert.False(t, a.Has("amm"))
}

// TestCatalogCopyOfAZeroValueIsSeparate: nothing has been allocated yet, so
// there is no directory to share. Stated because it is the one case where
// copying does NOT alias, and a reader would otherwise have to guess.
func TestCatalogCopyOfAZeroValueIsSeparate(t *testing.T) {
	var a Catalog
	b := a
	uassert.NoError(t, b.Set(tool("usernames")))

	uassert.Equal(t, 0, a.Len())
	uassert.Equal(t, 1, b.Len())
}

func TestCatalogZeroValue(t *testing.T) {
	var c Catalog
	uassert.Equal(t, 0, c.Len())
	uassert.Equal(t, 0, len(c.List()))
	uassert.False(t, c.Has("usernames"))
	uassert.ErrorIs(t, c.Remove("usernames"), ErrUnknownSlug)
}

// TestCatalogSortsBySlug checks the only ordering guarantee the type makes,
// against an insertion order that is reverse, interleaved and duplicated.
func TestCatalogSortsBySlug(t *testing.T) {
	var c Catalog
	for _, s := range []string{"zones", "amm", "usernames", "base64", "amm"} {
		uassert.NoError(t, c.Set(tool(s)))
	}
	uassert.Equal(t, 4, c.Len())
	want := []string{"amm", "base64", "usernames", "zones"}
	got := slugs(c.List())
	uassert.Equal(t, len(want), len(got))
	for i := range want {
		uassert.Equal(t, want[i], got[i])
	}
}

func TestCatalogSetReplaces(t *testing.T) {
	var c Catalog
	uassert.NoError(t, c.Set(tool("usernames")))
	updated := tool("usernames")
	updated.Desc = "resolve a username or an address"
	uassert.NoError(t, c.Set(updated))

	uassert.Equal(t, 1, c.Len())
	got, ok := c.Get("usernames")
	uassert.True(t, ok)
	uassert.Equal(t, "resolve a username or an address", got.Desc)
}

func TestCatalogSetRejectsInvalid(t *testing.T) {
	var c Catalog
	uassert.ErrorIs(t, c.Set(Tool{Path: "p", Title: "t"}), ErrEmptySlug)
	uassert.ErrorIs(t, c.Set(Tool{Slug: "A", Path: "p", Title: "t"}), ErrBadSlug)
	uassert.ErrorIs(t, c.Set(Tool{Slug: "a", Title: "t"}), ErrEmptyPath)
	uassert.ErrorIs(t, c.Set(Tool{Slug: "a", Path: "p"}), ErrEmptyTitle)
	uassert.Equal(t, 0, c.Len())
}

func TestCatalogGetAndRemove(t *testing.T) {
	var c Catalog
	for _, s := range []string{"amm", "base64", "usernames"} {
		uassert.NoError(t, c.Set(tool(s)))
	}

	got, ok := c.Get("base64")
	uassert.True(t, ok)
	uassert.Equal(t, "gno.land/r/moul/toolbox/base64/v0", got.Path)

	_, ok = c.Get("nope")
	uassert.False(t, ok)

	uassert.NoError(t, c.Remove("base64"))
	uassert.False(t, c.Has("base64"))
	uassert.Equal(t, 2, c.Len())
	uassert.ErrorIs(t, c.Remove("base64"), ErrUnknownSlug)

	// The two survivors are still in order around the hole.
	got2 := slugs(c.List())
	uassert.Equal(t, "amm", got2[0])
	uassert.Equal(t, "usernames", got2[1])
}

// TestCatalogListIsACopy: a caller rewriting what List handed back must not
// reach the directory through it. The struct copy covers the string fields on
// its own; Tags is a slice, so without copyTool the header is duplicated and
// the backing array is shared, and the write below would land in the catalog.
func TestCatalogListIsACopy(t *testing.T) {
	var c Catalog
	uassert.NoError(t, c.Set(tool("usernames", "identity")))

	got := c.List()
	got[0].Title = "hijacked"
	got[0].Tags[0] = "hijacked"

	kept, ok := c.Get("usernames")
	uassert.True(t, ok)
	uassert.Equal(t, "usernames", kept.Title)
	uassert.Equal(t, "identity", kept.Tags[0])
}

// TestCatalogDoesNotAliasTheCallersTags is the same hole from the other side:
// Set must not keep a handle on the slice the caller still holds.
func TestCatalogDoesNotAliasTheCallersTags(t *testing.T) {
	var c Catalog
	tags := []string{"identity"}
	uassert.NoError(t, c.Set(Tool{
		Slug:  "usernames",
		Path:  "gno.land/r/moul/toolbox/usernames",
		Title: "Usernames",
		Tags:  tags,
	}))

	tags[0] = "hijacked"

	kept, ok := c.Get("usernames")
	uassert.True(t, ok)
	uassert.Equal(t, "identity", kept.Tags[0])
	uassert.Equal(t, 1, len(c.ByTag("identity")))
	uassert.Equal(t, 0, len(c.ByTag("hijacked")))
}

// TestCatalogGetIsACopyToo: ByTag and Get hand out the same values List does.
func TestCatalogGetIsACopyToo(t *testing.T) {
	var c Catalog
	uassert.NoError(t, c.Set(tool("usernames", "identity")))

	got, ok := c.Get("usernames")
	uassert.True(t, ok)
	got.Tags[0] = "hijacked"

	byTag := c.ByTag("identity")
	uassert.Equal(t, 1, len(byTag))
	byTag[0].Tags[0] = "hijacked-again"

	kept, _ := c.Get("usernames")
	uassert.Equal(t, "identity", kept.Tags[0])
}

func TestCatalogByTagAndTags(t *testing.T) {
	var c Catalog
	uassert.NoError(t, c.Set(tool("usernames", "identity", "read")))
	uassert.NoError(t, c.Set(tool("amm", "defi")))
	uassert.NoError(t, c.Set(tool("whois", "identity")))

	identity := slugs(c.ByTag("identity"))
	uassert.Equal(t, 2, len(identity))
	uassert.Equal(t, "usernames", identity[0])
	uassert.Equal(t, "whois", identity[1])

	uassert.Equal(t, 0, len(c.ByTag("nope")))
	uassert.Equal(t, 0, len(c.ByTag("")))

	tags := c.Tags()
	uassert.Equal(t, 3, len(tags))
	uassert.Equal(t, "defi", tags[0])
	uassert.Equal(t, "identity", tags[1])
	uassert.Equal(t, "read", tags[2])
}

package toolbox

import "strings"

// Query builds the gnoweb form a read-only tool needs: a text box whose
// submission navigates to one of the realm's own Render paths, with the typed
// values as query parameters.
//
// This is the "template of a query" a toolbox page is for. Rendered by gnoweb,
//
//	NewQuery("lookup").Field("q", "username or g1 address").String()
//
// posts to the realm and redirects to `/r/moul/toolbox/usernames:lookup?q=moul`
// (`gno.land/pkg/gnoweb/handler_http.go`, `Post`: the `path` attribute travels
// as the hidden `__gno_path` field and becomes the render args, every other
// field becomes a query parameter). Nothing is signed and no transaction is
// built: the result is a `Render` call, which is exactly what
// `gnokey query vm/qrender` would have done from a terminal.
//
// A form whose fields should CALL a function instead is a different element,
// `<gno-form exec="Fn">`, and it is not what this type builds. A query form is
// free and a call is not, so the two are deliberately not one constructor with
// a flag.
type Query struct {
	path   string
	fields []queryField
}

type queryField struct {
	name        string
	placeholder string
}

// NewQuery starts a form submitting to the Render path args.
//
// Pass "" to submit to the realm's root page. Do not include a leading colon
// or the realm path itself: gnoweb supplies both, and a value that looks like
// a URL is percent-encoded into one path element rather than followed.
func NewQuery(path string) *Query {
	return &Query{path: path}
}

// Field adds a text input. name is the query parameter the realm will read;
// placeholder is the grey text in the empty box.
//
// A field with an empty name is ignored: gnoweb rejects the whole form for it,
// and losing one input beats losing the page.
func (q *Query) Field(name, placeholder string) *Query {
	if name == "" {
		return q
	}
	q.fields = append(q.fields, queryField{name: name, placeholder: placeholder})
	return q
}

// Len is how many fields the form carries.
func (q *Query) Len() int { return len(q.fields) }

// String renders the form as the markdown-embedded HTML gnoweb parses.
//
// A form with no field renders as the empty string rather than as a submit
// button with nothing to submit.
func (q *Query) String() string {
	if len(q.fields) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString(`<gno-form`)
	if q.path != "" {
		b.WriteString(` path="` + attr(q.path) + `"`)
	}
	b.WriteString(">\n")
	for _, f := range q.fields {
		b.WriteString(`<gno-input name="` + attr(f.name) + `" type="text"`)
		if f.placeholder != "" {
			b.WriteString(` placeholder="` + attr(f.placeholder) + `"`)
		}
		b.WriteString(" />\n")
	}
	b.WriteString("</gno-form>\n")
	return b.String()
}

// attr escapes a value for an HTML attribute in double quotes.
//
// gnoweb parses these with a real HTML tokenizer, so an unescaped quote does
// not merely look wrong: it ends the attribute and whatever follows becomes
// further attributes of the same tag. Ampersand first, or the escapes of the
// later replacements would themselves be escaped.
func attr(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

package toolbox

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestQueryString(t *testing.T) {
	got := NewQuery("lookup").Field("q", "username or g1 address").String()
	want := "<gno-form path=\"lookup\">\n" +
		"<gno-input name=\"q\" type=\"text\" placeholder=\"username or g1 address\" />\n" +
		"</gno-form>\n"
	uassert.Equal(t, want, got)
}

func TestQueryNoPathNoPlaceholder(t *testing.T) {
	got := NewQuery("").Field("q", "").String()
	want := "<gno-form>\n<gno-input name=\"q\" type=\"text\" />\n</gno-form>\n"
	uassert.Equal(t, want, got)
}

func TestQueryTwoFields(t *testing.T) {
	q := NewQuery("compare").Field("a", "first").Field("b", "second")
	uassert.Equal(t, 2, q.Len())
	got := q.String()
	uassert.True(t, strings.Contains(got, `name="a"`))
	uassert.True(t, strings.Contains(got, `name="b"`))
	uassert.Equal(t, 1, strings.Count(got, "<gno-form"))
}

// TestQueryEmptyRendersNothing: a form with no input is a submit button with
// nothing to submit, so it is not rendered at all.
func TestQueryEmptyRendersNothing(t *testing.T) {
	uassert.Equal(t, "", NewQuery("lookup").String())
	uassert.Equal(t, "", NewQuery("lookup").Field("", "ignored").String())
}

// TestQueryEscapesAttributes: gnoweb parses these with a real HTML tokenizer,
// so an unescaped quote ends the attribute and everything after it becomes
// further attributes of the same tag.
func TestQueryEscapesAttributes(t *testing.T) {
	got := NewQuery(`a"b`).Field("q", `<script>&"`).String()
	uassert.True(t, strings.Contains(got, `path="a&quot;b"`))
	uassert.True(t, strings.Contains(got, `placeholder="&lt;script&gt;&amp;&quot;"`))
	uassert.False(t, strings.Contains(got, "<script>"))
}

func TestAttr(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"plain", "username", "username"},
		{"quote", `a"b`, "a&quot;b"},
		{"ampersand", "a&b", "a&amp;b"},
		{"angle", "<b>", "&lt;b&gt;"},
		{"ampersand before quote", `&"`, "&amp;&quot;"},
		{"already escaped stays literal", "&amp;", "&amp;amp;"},
		{"empty", "", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, attr(tc.in))
		})
	}
}

package toolbox

import (
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
)

// Index renders a catalog as a markdown table: tool, what it does, tags.
//
// Every cell that came from a [Tool] is escaped exactly once, with the helper
// for the slot it lands in. A tool description is written by whoever wrote the
// entry, which in a hub that accepts runtime registration is not necessarily
// whoever owns the hub, and a pipe or a backtick in one would otherwise
// rewrite the table around it.
//
// The title link is built by hand rather than with [md.Link], which is the one
// place the obvious call is wrong: md.Link runs its text through
// sanitize.InlineText itself, so md.Link(ui.Cell(title), url) escapes twice and
// a title with an asterisk in it renders as a backslash. The slot here is link
// text INSIDE a table cell, and the helper for that is [ui.Cell] (InlineText
// plus the pipe escape InlineText deliberately leaves alone), with the URL
// escaped once by [md.EscapeURL].
func Index(tools []Tool) string {
	t := ui.NewTable("Tool", "What it does", "Tags")
	for _, tool := range tools {
		t.Row(
			"["+ui.Cell(tool.Title)+"]("+md.EscapeURL(tool.URL())+")",
			ui.Cell(tool.Desc),
			ui.Cell(strings.Join(tool.Tags, ", ")),
		)
	}
	return t.OrEmpty("No tools yet.")
}

// Card renders one tool on its own: the title as a link, the description, the
// package path, and the two ways to reach it.
func Card(tool Tool) string {
	var b strings.Builder
	b.WriteString(md.H2(ui.Inline(tool.Title)))
	if tool.Desc != "" {
		b.WriteString("\n" + ui.Inline(tool.Desc) + "\n")
	}
	b.WriteString("\n" + md.BulletList([]string{
		"Open: " + md.Link(tool.URL(), tool.URL()),
		"Path: " + md.InlineCode(tool.Path),
	}))
	if len(tool.Tags) > 0 {
		b.WriteString("\nTags: " + ui.Inline(strings.Join(tool.Tags, ", ")) + "\n")
	}
	return b.String()
}

// Nav renders the one line every tool page carries above its content: a link
// back to the hub, then the tool's own title.
//
// hubURL is a gnoweb path ("/r/moul/toolbox"), not a package path. A tool
// cannot import the hub to ask, so it states it, and this is the one place the
// two have to agree.
func Nav(hubURL, title string) string {
	return md.Link("toolbox", hubURL) + " / " + md.Bold(ui.Inline(title)) + "\n"
}

package toolbox

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestIndex(t *testing.T) {
	var c Catalog
	uassert.NoError(t, c.Set(Tool{
		Slug:  "usernames",
		Path:  "gno.land/r/moul/toolbox/usernames",
		Title: "Usernames",
		Desc:  "resolve a username or an address",
		Tags:  []string{"identity", "read"},
	}))

	got := Index(c.List())
	uassert.True(t, strings.Contains(got, "[Usernames](/r/moul/toolbox/usernames)"))
	uassert.True(t, strings.Contains(got, "resolve a username or an address"))
	uassert.True(t, strings.Contains(got, "identity, read"))
}

func TestIndexEmpty(t *testing.T) {
	uassert.True(t, strings.Contains(Index(nil), "No tools yet."))
}

// TestIndexEscapesCells pins the escaping contract: a description is written
// by whoever wrote the entry, and a pipe in one would otherwise add a column to
// every row below it. The title is link text inside a cell, so it needs the
// pipe escaped there too.
func TestIndexEscapesCells(t *testing.T) {
	got := Index([]Tool{{
		Slug:  "evil",
		Path:  "gno.land/r/moul/toolbox/evil",
		Title: "Ev|il",
		Desc:  "a | b",
		Tags:  []string{"x|y"},
	}})
	uassert.False(t, strings.Contains(got, "a | b"))
	uassert.True(t, strings.Contains(got, `[Ev\|il](/r/moul/toolbox/evil)`))
	uassert.True(t, strings.Contains(got, `x\|y`))
}

// TestIndexEscapesTitleExactlyOnce is the double-wrap regression, and the
// values are copied from what the escapers actually produce rather than
// guessed: md.Link runs its text through sanitize.InlineText itself, so
// md.Link(ui.Cell(title), url) yields `[a\\\*b]` where one pass yields
// `[a\*b]`, and the reader sees a stray backslash.
func TestIndexEscapesTitleExactlyOnce(t *testing.T) {
	got := Index([]Tool{{
		Slug:  "star",
		Path:  "gno.land/r/moul/toolbox/star",
		Title: "a*b",
		Desc:  "c*d",
	}})
	uassert.True(t, strings.Contains(got, `[a\*b](/r/moul/toolbox/star)`))
	uassert.False(t, strings.Contains(got, `a\\`))
	uassert.True(t, strings.Contains(got, `c\*d`))
}

func TestCard(t *testing.T) {
	got := Card(Tool{
		Slug:  "usernames",
		Path:  "gno.land/r/moul/toolbox/usernames",
		Title: "Usernames",
		Desc:  "resolve a username or an address",
		Tags:  []string{"identity"},
	})
	uassert.True(t, strings.Contains(got, "## Usernames"))
	uassert.True(t, strings.Contains(got, "resolve a username or an address"))
	uassert.True(t, strings.Contains(got, "`gno.land/r/moul/toolbox/usernames`"))
	uassert.True(t, strings.Contains(got, "/r/moul/toolbox/usernames"))
	uassert.True(t, strings.Contains(got, "Tags: identity"))
}

