// Package toolbox is the directory model behind
// [r/moul/toolbox](/r/moul/toolbox): a list of small gno.land utilities,
// each one a realm of its own, rendered as a single index.
//
// A tool is a [Tool]: a slug, the realm path that serves it, a title and one
// line of description. A [Catalog] holds them sorted by slug and answers the
// three questions a directory gets asked: what is here, what is this one, and
// what is tagged X.
//
// # Why a package and not just a realm
//
// The hub realm is `private = true`, which buys redeploy-in-place at a stable
// path and costs the ability to be imported at all: the type checker refuses
// any realm importing a private one (`ImportPrivateError`). So the hub cannot
// share a single line of code with its tools by importing them, and they
// cannot import it either. Everything both sides must agree about (what a tool
// entry looks like, how the index is rendered, how a query form is spelled)
// has to live in a `p/`, which is this one.
//
// # Nesting is checked on the base path, not on the full one
//
// [p/moul/nestedpkg](/p/moul/nestedpkg/v0) decides "is the caller below me" by
// prefixing one package path with the other. That is exactly right when
// neither path carries a version, which is the case for a private hub: it is
// redeployable, so its version could never increment and it does not carry
// one. It breaks the moment either side does, because
// `gno.land/r/moul/toolbox/usernames/v0` does not begin with
// `gno.land/r/moul/toolbox/v0`.
//
// [BasePath] removes a trailing `/vN` so the comparison is about the family
// rather than the version, and [IsUnder] and [SlugOf] are built on it. A hub
// and a tool may each be versioned or not, independently, and all four
// combinations answer the same.
//
// Live: [r/moul/toolbox](/r/moul/toolbox).
package toolbox

import (
	"errors"
	"strings"
)

// Errors a [Tool] or a [Catalog] returns. A /p/ package returns errors and
// lets the realm decide whether they are fatal; all of these are a mistake in
// the realm's own source rather than a value a user chose, so panicking on
// them is the normal handling.
var (
	// ErrEmptySlug is returned for a tool with no slug. The slug is the key
	// and the URL segment, so there is nothing to list it under.
	ErrEmptySlug = errors.New("toolbox: the slug is empty")

	// ErrBadSlug is returned for a slug carrying anything but lowercase
	// letters, digits and dashes. A slug travels in a URL path and in a
	// markdown link, and those are the characters that need no escaping in
	// either.
	ErrBadSlug = errors.New("toolbox: the slug has a character outside [a-z0-9-]")

	// ErrEmptyPath is returned for a tool with no package path. A directory
	// entry nobody can open is worse than no entry.
	ErrEmptyPath = errors.New("toolbox: the path is empty")

	// ErrEmptyTitle is returned for a tool with no title.
	ErrEmptyTitle = errors.New("toolbox: the title is empty")

	// ErrUnknownSlug is returned by [Catalog.Remove] for a slug it does not
	// hold.
	ErrUnknownSlug = errors.New("toolbox: no tool with that slug")
)

// Tool is one entry of the directory.
//
// Every field is a string or a slice of strings on purpose. A tool realm that
// registers itself into a public hub hands these values across a realm
// boundary, and a struct allocated by the caller would be the caller's object:
// persisting it panics with `cannot persist object from the private realm`
// when the caller is private. Scalars are copied, so the hub owns everything
// it stores whichever side built the entry.
type Tool struct {
	// Slug is the key, the URL segment and the sort order: "usernames".
	Slug string

	// Path is the package path serving the tool, with its version if it has
	// one: "gno.land/r/moul/toolbox/usernames".
	Path string

	// Title is the human name: "Usernames".
	Title string

	// Desc is one line about what the tool does. It is rendered inside a
	// table cell, so [Index] escapes it rather than trusting it.
	Desc string

	// Tags group tools in the index. Order is preserved as written.
	Tags []string
}

// Validate reports the first thing wrong with t, or nil.
func (t Tool) Validate() error {
	switch {
	case t.Slug == "":
		return ErrEmptySlug
	case !ValidSlug(t.Slug):
		return ErrBadSlug
	case t.Path == "":
		return ErrEmptyPath
	case t.Title == "":
		return ErrEmptyTitle
	}
	return nil
}

// HasTag reports whether t carries tag, compared exactly.
func (t Tool) HasTag(tag string) bool {
	for _, got := range t.Tags {
		if got == tag {
			return true
		}
	}
	return false
}

// URL is the gnoweb path of the tool, the package path with the chain domain
// removed: "/r/moul/toolbox/usernames".
//
// It is derived rather than stored so an entry cannot carry a link that
// disagrees with its own path.
func (t Tool) URL() string {
	if i := strings.Index(t.Path, "/"); i >= 0 && !strings.HasPrefix(t.Path, "/") {
		return t.Path[i:]
	}
	return t.Path
}

// ValidSlug reports whether s is a usable slug: non-empty, and lowercase
// letters, digits and dashes only.
//
// It is deliberately narrower than what a package path allows. A slug ends up
// in a URL and in markdown link syntax, and this is the set that survives both
// untouched, so nothing downstream has to escape it.
func ValidSlug(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= '0' && c <= '9':
		case c == '-':
		default:
			return false
		}
	}
	return true
}

// BasePath returns pkgPath with a trailing version element removed:
// "gno.land/p/moul/toolbox/v0" becomes "gno.land/p/moul/toolbox".
//
// A path with no version element is returned unchanged, so calling it twice is
// the same as calling it once.
func BasePath(pkgPath string) string {
	i := strings.LastIndex(pkgPath, "/")
	if i < 0 {
		return pkgPath
	}
	if !isVersion(pkgPath[i+1:]) {
		return pkgPath
	}
	return pkgPath[:i]
}

// isVersion reports whether elem is a "vN" path element: a 'v' followed by at
// least one digit and nothing else.
func isVersion(elem string) bool {
	if len(elem) < 2 || elem[0] != 'v' {
		return false
	}
	for i := 1; i < len(elem); i++ {
		if elem[i] < '0' || elem[i] > '9' {
			return false
		}
	}
	return true
}

// IsUnder reports whether pkgPath is a tool of the hub at hubPath, ignoring
// both paths' versions.
//
// The hub itself is not under itself, and neither is a sibling whose name
// merely starts with the hub's: "toolboxtwo" is not under "toolbox", because
// the comparison is against the base plus a slash.
func IsUnder(hubPath, pkgPath string) bool {
	base := BasePath(hubPath)
	if base == "" {
		return false
	}
	return strings.HasPrefix(BasePath(pkgPath), base+"/")
}

// SlugOf returns the slug a tool at pkgPath would have under the hub at
// hubPath, or "" when pkgPath is not under it.
//
// A tool nested deeper than one element has no slug: the directory is one
// level by design, so "toolbox/a/b" is reported as not a tool rather than
// silently listed as "a".
func SlugOf(hubPath, pkgPath string) string {
	if !IsUnder(hubPath, pkgPath) {
		return ""
	}
	rest := strings.TrimPrefix(BasePath(pkgPath), BasePath(hubPath)+"/")
	if strings.Contains(rest, "/") {
		return ""
	}
	return rest
}

package toolbox

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestValidSlug(t *testing.T) {
	cases := []struct {
		name string
		slug string
		want bool
	}{
		{"plain", "usernames", true},
		{"dashed", "gov-dao", true},
		{"digits", "base64", true},
		{"all dashes", "--", true},
		{"empty", "", false},
		{"uppercase", "Usernames", false},
		{"underscore", "gov_dao", false},
		{"slash", "a/b", false},
		{"space", "gov dao", false},
		{"dot", "v0.1", false},
		{"percent", "a%2Fb", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, ValidSlug(tc.slug))
		})
	}
}

func TestBasePath(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"versioned realm", "gno.land/r/moul/toolbox/v0", "gno.land/r/moul/toolbox"},
		{"two digit version", "gno.land/r/moul/toolbox/v12", "gno.land/r/moul/toolbox"},
		{"nested tool", "gno.land/r/moul/toolbox/usernames/v0", "gno.land/r/moul/toolbox/usernames"},
		{"unversioned", "gno.land/r/moul/home", "gno.land/r/moul/home"},
		{"idempotent", "gno.land/r/moul/toolbox", "gno.land/r/moul/toolbox"},
		{"v with no digit", "gno.land/r/moul/v", "gno.land/r/moul/v"},
		{"v with a letter", "gno.land/r/moul/v0a", "gno.land/r/moul/v0a"},
		{"no slash", "toolbox", "toolbox"},
		{"empty", "", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, BasePath(tc.in))
		})
	}
}

func TestIsUnderAndSlugOf(t *testing.T) {
	const hub = "gno.land/r/moul/toolbox/v0"
	cases := []struct {
		name      string
		path      string
		wantUnder bool
		wantSlug  string
	}{
		{"direct tool", "gno.land/r/moul/toolbox/usernames/v0", true, "usernames"},
		{"unversioned tool", "gno.land/r/moul/toolbox/usernames", true, "usernames"},
		{"tool at another version", "gno.land/r/moul/toolbox/usernames/v3", true, "usernames"},
		{"nested deeper", "gno.land/r/moul/toolbox/a/b/v0", true, ""},
		{"the hub itself", hub, false, ""},
		{"hub unversioned", "gno.land/r/moul/toolbox", false, ""},
		{"prefix sibling", "gno.land/r/moul/toolboxtwo/v0", false, ""},
		{"unrelated realm", "gno.land/r/moul/home", false, ""},
		{"empty", "", false, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.wantUnder, IsUnder(hub, tc.path))
			uassert.Equal(t, tc.wantSlug, SlugOf(hub, tc.path))
		})
	}
}

// TestIsUnderIgnoresEitherSideVersion is the claim the package doc makes: a
// hub and a tool may each carry a version or not, independently, and all four
// combinations answer the same. The live shape is the unversioned one, since a
// private realm is redeployable and its version could never increment.
func TestIsUnderIgnoresEitherSideVersion(t *testing.T) {
	hubs := []string{"gno.land/r/moul/toolbox", "gno.land/r/moul/toolbox/v0"}
	tools := []string{"gno.land/r/moul/toolbox/usernames", "gno.land/r/moul/toolbox/usernames/v2"}
	for _, hub := range hubs {
		for _, tool := range tools {
			t.Run(hub+" <- "+tool, func(t *testing.T) {
				uassert.True(t, IsUnder(hub, tool))
				uassert.Equal(t, "usernames", SlugOf(hub, tool))
				uassert.False(t, IsUnder(hub, hub))
			})
		}
	}
}

// TestIsUnderEmptyHub pins the one input that would otherwise make every path
// a tool: an empty hub path has no family to be below.
func TestIsUnderEmptyHub(t *testing.T) {
	uassert.False(t, IsUnder("", "gno.land/r/moul/toolbox/usernames/v0"))
	uassert.Equal(t, "", SlugOf("", "gno.land/r/moul/toolbox/usernames/v0"))
}

func TestToolValidate(t *testing.T) {
	ok := Tool{Slug: "usernames", Path: "gno.land/r/moul/toolbox/usernames/v0", Title: "Usernames"}
	cases := []struct {
		name string
		tool Tool
		want error
	}{
		{"complete", ok, nil},
		{"no slug", Tool{Path: ok.Path, Title: ok.Title}, ErrEmptySlug},
		{"bad slug", Tool{Slug: "User Names", Path: ok.Path, Title: ok.Title}, ErrBadSlug},
		{"no path", Tool{Slug: ok.Slug, Title: ok.Title}, ErrEmptyPath},
		{"no title", Tool{Slug: ok.Slug, Path: ok.Path}, ErrEmptyTitle},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.tool.Validate()
			if tc.want == nil {
				uassert.NoError(t, got)
				return
			}
			uassert.ErrorIs(t, got, tc.want)
		})
	}
}

func TestToolURL(t *testing.T) {
	cases := []struct {
		name string
		path string
		want string
	}{
		{"chain path", "gno.land/r/moul/toolbox/usernames/v0", "/r/moul/toolbox/usernames/v0"},
		{"other domain", "example.com/r/x/v0", "/r/x/v0"},
		{"already a url", "/r/moul/toolbox/v0", "/r/moul/toolbox/v0"},
		{"no slash", "toolbox", "toolbox"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, Tool{Path: tc.path}.URL())
		})
	}
}

func TestToolHasTag(t *testing.T) {
	tool := Tool{Tags: []string{"identity", "read"}}
	uassert.True(t, tool.HasTag("identity"))
	uassert.True(t, tool.HasTag("read"))
	uassert.False(t, tool.HasTag("Identity"))
	uassert.False(t, tool.HasTag(""))
	uassert.False(t, Tool{}.HasTag("identity"))
}

// Package rc is a small shell over a Plan 9 namespace.
//
// It exists because a namespace you cannot inspect is a namespace you cannot
// trust. Everything here operates on a gno.land/p/moul/x/plan9/ns namespace
// and returns text, so one realm's Render becomes a file browser and one
// transaction becomes a shell command:
//
//	Exec("bind -a /srv/dev /dev; echo hello > /tmp/greeting")
//
// The mode split is the security model. A Shell in ReadOnly mode refuses every
// mutating command, which is what lets a realm expose the shell through
// Render, where mutating anything would be a bug, while the same code backs a
// crossing Exec that may write.
//
// Quoting follows rc: single quotes, with ” inside a quoted string standing
// for one literal quote. Commands are separated by ';' or newlines, and
// quoting is respected when splitting them.
//
// On the first error the run STOPS and returns it. A realm should let that
// error panic, so a half-applied command line reverts with the transaction
// rather than leaving the namespace in a state nobody asked for.
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This package is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package rc

import (
	"errors"
	"strconv"
	"strings"

	memfs "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/memfs/v0"
	ninep "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/ninep/v0"
	ns "gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/plan9/ns/v0"
)

// Mode decides whether mutating commands are allowed.
type Mode uint8

// Shell modes.
const (
	ReadOnly  Mode = 0
	ReadWrite Mode = 1
)

var (
	// ErrReadOnly is returned when a mutating command runs in ReadOnly mode.
	ErrReadOnly = errors.New("read-only shell")
	// ErrUsage reports a malformed command line.
	ErrUsage = errors.New("usage")
	// ErrUnknown reports a command this shell does not have.
	ErrUnknown = errors.New("command not found")
	// ErrQuote reports an unterminated quoted string.
	ErrQuote = errors.New("unterminated '")
)

// MaxCommands bounds one run, so a single call cannot loop the VM.
const MaxCommands = 32

// Shell runs commands against one namespace.
type Shell struct {
	ns   *ns.Ns
	mode Mode
	now  func() int64
}

// New returns a shell over n. now supplies the block height stamped on writes
// and may be nil in ReadOnly mode.
func New(n *ns.Ns, mode Mode, now func() int64) *Shell {
	return &Shell{ns: n, mode: mode, now: now}
}

// Ns returns the namespace the shell operates on.
func (s *Shell) Ns() *ns.Ns { return s.ns }

func (s *Shell) clock() int64 {
	if s.now == nil {
		return 0
	}
	return s.now()
}

func (s *Shell) writable() error {
	if s.mode != ReadWrite {
		return ErrReadOnly
	}
	return nil
}

// Run executes a command line and returns its output. Execution stops at the
// first error.
func (s *Shell) Run(line string) (string, error) {
	cmds, err := splitCommands(line)
	if err != nil {
		return "", err
	}
	if len(cmds) > MaxCommands {
		return "", errors.New("too many commands in one line")
	}
	var out strings.Builder
	for _, c := range cmds {
		toks, err := tokenize(c)
		if err != nil {
			return out.String(), err
		}
		if len(toks) == 0 {
			continue
		}
		text, err := s.run1(toks)
		out.WriteString(text)
		if err != nil {
			return out.String(), errors.New(toks[0] + ": " + err.Error())
		}
	}
	return out.String(), nil
}

func (s *Shell) run1(toks []string) (string, error) {
	cmd, args := toks[0], toks[1:]
	switch cmd {
	case "help":
		return help, nil
	case "pwd":
		return s.ns.Cwd() + "\n", nil
	case "cd":
		return "", s.cd(args)
	case "ns":
		return s.ns.String(), nil
	case "ls":
		return s.ls(args)
	case "cat":
		return s.cat(args)
	case "stat":
		return s.stat(args)
	case "walk":
		return s.walk(args)
	case "bind", "mount":
		return "", s.bind(cmd, args)
	case "unmount", "unbind":
		return "", s.unmount(args)
	case "mkdir":
		return "", s.mkdir(args)
	case "rm":
		return "", s.rm(args)
	case "echo":
		return s.echo(args)
	}
	return "", ErrUnknown
}

const help = `bind [-a|-b|-c] new old   make new visible at old (-b before, -a after, -c creates)
cat file...               print files
cd [dir]                  change directory
echo [-n] word... [>|>> file]
ls [-l] [-u] [path...]    list; -l long, -u collapse union duplicates
mkdir path...             create directories
mount                     synonym for bind
ns                        print the namespace
pwd                       print the working directory
rm path...                remove files and empty directories
stat path...              print the 9P stat of each path
unmount [new] old         undo a binding
walk path                 show how each element of path resolves
`

func (s *Shell) cd(args []string) error {
	if len(args) == 0 {
		return s.ns.Cd("/")
	}
	if len(args) > 1 {
		return ErrUsage
	}
	return s.ns.Cd(args[0])
}

func (s *Shell) ls(args []string) (string, error) {
	long, unique, paths := false, false, []string{}
	for _, a := range args {
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			for _, r := range a[1:] {
				switch r {
				case 'l':
					long = true
				case 'u':
					unique = true
				default:
					return "", ErrUsage
				}
			}
			continue
		}
		paths = append(paths, a)
	}
	if len(paths) == 0 {
		paths = []string{s.ns.Cwd()}
	}
	var out strings.Builder
	for i, p := range paths {
		st, err := s.ns.Stat(p)
		if err != nil {
			return out.String(), err
		}
		if len(paths) > 1 {
			if i > 0 {
				out.WriteString("\n")
			}
			out.WriteString(s.ns.Abs(p) + ":\n")
		}
		if !st.IsDir() {
			out.WriteString(entryLine(st, long))
			continue
		}
		ents, err := s.ns.ReadDir(p, unique)
		if err != nil {
			return out.String(), err
		}
		for _, e := range ents {
			out.WriteString(entryLine(e, long))
		}
	}
	return out.String(), nil
}

func entryLine(st ninep.Stat, long bool) string {
	if long {
		return st.Line() + "\n"
	}
	name := st.Name
	if st.IsDir() && name != "/" {
		name += "/"
	}
	return name + "\n"
}

func (s *Shell) cat(args []string) (string, error) {
	if len(args) == 0 {
		return "", ErrUsage
	}
	var out strings.Builder
	for _, p := range args {
		data, err := s.ns.ReadFile(p)
		if err != nil {
			return out.String(), err
		}
		out.WriteString(data)
	}
	return out.String(), nil
}

func (s *Shell) stat(args []string) (string, error) {
	if len(args) == 0 {
		args = []string{s.ns.Cwd()}
	}
	var out strings.Builder
	for _, p := range args {
		st, err := s.ns.Stat(p)
		if err != nil {
			return out.String(), err
		}
		members, err := s.ns.Resolve(p)
		if err != nil {
			return out.String(), err
		}
		out.WriteString(s.ns.Abs(p) + " " + st.Qid.String() +
			" " + st.Mode.String() +
			" uid=" + st.Uid +
			" length=" + strconv.FormatInt(st.Length, 10) +
			" mtime=" + strconv.FormatInt(st.Mtime, 10) +
			" union=" + strconv.Itoa(len(members)) + "\n")
	}
	return out.String(), nil
}

// walk shows the resolution of each element, which is where a namespace stops
// being magic: the union width column says exactly when a bind took effect.
func (s *Shell) walk(args []string) (string, error) {
	if len(args) != 1 {
		return "", ErrUsage
	}
	abs := s.ns.Abs(args[0])
	var out strings.Builder
	prefix := "/"
	report := func(p string) error {
		st, err := s.ns.Stat(p)
		if err != nil {
			return err
		}
		members, err := s.ns.Resolve(p)
		if err != nil {
			return err
		}
		out.WriteString(pad(p, 24) + " " + st.Qid.String() + " " +
			st.Mode.String() + " union=" + strconv.Itoa(len(members)) + "\n")
		return nil
	}
	if err := report("/"); err != nil {
		return out.String(), err
	}
	for _, e := range ninep.Elems(abs) {
		prefix = ninep.Join(prefix, e)
		if err := report(prefix); err != nil {
			return out.String(), err
		}
	}
	return out.String(), nil
}

func pad(s string, n int) string {
	for len(s) < n {
		s += " "
	}
	return s
}

func (s *Shell) bind(verb string, args []string) error {
	if err := s.writable(); err != nil {
		return err
	}
	flag := ns.MREPL
	rest := []string{}
	for _, a := range args {
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			for _, r := range a[1:] {
				switch r {
				case 'b':
					flag = flag&^0x3 | ns.MBEFORE
				case 'a':
					flag = flag&^0x3 | ns.MAFTER
				case 'c':
					flag |= ns.MCREATE
				default:
					return ErrUsage
				}
			}
			continue
		}
		rest = append(rest, a)
	}
	if len(rest) != 2 {
		return ErrUsage
	}
	return s.ns.BindVerb(verb, rest[0], rest[1], flag)
}

func (s *Shell) unmount(args []string) error {
	if err := s.writable(); err != nil {
		return err
	}
	switch len(args) {
	case 1:
		return s.ns.Unmount("", args[0])
	case 2:
		return s.ns.Unmount(args[0], args[1])
	}
	return ErrUsage
}

func (s *Shell) mkdir(args []string) error {
	if err := s.writable(); err != nil {
		return err
	}
	if len(args) == 0 {
		return ErrUsage
	}
	for _, p := range args {
		abs := s.ns.Abs(p)
		target, err := s.ns.CreateTarget(ninep.Dir(abs))
		if err != nil {
			return err
		}
		if _, err := target.Create(ninep.Base(abs), ninep.DirPerm, s.clock()); err != nil {
			return err
		}
	}
	return nil
}

func (s *Shell) rm(args []string) error {
	if err := s.writable(); err != nil {
		return err
	}
	if len(args) == 0 {
		return ErrUsage
	}
	for _, p := range args {
		abs := s.ns.Abs(p)
		name := ninep.Base(abs)
		members, err := s.ns.Resolve(ninep.Dir(abs))
		if err != nil {
			return err
		}
		found, removed := false, false
		for _, m := range members {
			if _, err := m.Walk(name); err != nil {
				continue
			}
			found = true
			mu, ok := m.(ninep.Mutable)
			if !ok {
				continue // a read-only server: try the next union member
			}
			if err := mu.Remove(name); err != nil {
				return err
			}
			removed = true
			break
		}
		switch {
		case removed:
		case found:
			return ninep.ErrReadOnly
		default:
			return ninep.ErrNotExist
		}
	}
	return nil
}

func (s *Shell) echo(args []string) (string, error) {
	newline := true
	words := []string{}
	redirect, appendTo, dest := false, false, ""
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "-n" && len(words) == 0 && !redirect:
			newline = false
		case a == ">" || a == ">>":
			if i+1 >= len(args) {
				return "", ErrUsage
			}
			redirect, appendTo, dest = true, a == ">>", args[i+1]
			i++
		default:
			words = append(words, a)
		}
		i++
	}
	text := strings.Join(words, " ")
	if newline {
		text += "\n"
	}
	if !redirect {
		return text, nil
	}
	if err := s.writable(); err != nil {
		return "", err
	}
	return "", s.writeTo(dest, text, appendTo)
}

// writeTo creates or opens dest and writes text, honouring the namespace's
// MCREATE rules when the file has to be created.
func (s *Shell) writeTo(dest, text string, appendTo bool) error {
	abs := s.ns.Abs(dest)
	f, err := s.ns.Open(abs)
	if err == ninep.ErrNotExist {
		target, terr := s.ns.CreateTarget(ninep.Dir(abs))
		if terr != nil {
			return terr
		}
		created, cerr := target.Create(ninep.Base(abs), ninep.FilePerm, s.clock())
		if cerr != nil {
			return cerr
		}
		f = created
	} else if err != nil {
		return err
	}
	mu, ok := f.(ninep.Mutable)
	if !ok {
		return ninep.ErrReadOnly
	}
	off := int64(0)
	if appendTo {
		off = mu.Stat().Length
	} else if err := mu.Truncate(0, s.clock()); err != nil {
		return err
	}
	_, err = mu.Write(off, text, s.clock())
	return err
}

// splitCommands splits on ';' and newlines, respecting rc quoting.
func splitCommands(line string) ([]string, error) {
	out := []string{}
	var b strings.Builder
	quoted := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if c == '\'' {
			quoted = !quoted
		}
		if !quoted && (c == ';' || c == '\n') {
			out = append(out, b.String())
			b.Reset()
			continue
		}
		b.WriteByte(c)
	}
	if quoted {
		return nil, ErrQuote
	}
	out = append(out, b.String())
	return out, nil
}

// tokenize splits one command into words using rc's quoting rules.
func tokenize(s string) ([]string, error) {
	toks := []string{}
	i := 0
	for i < len(s) {
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			break
		}
		var b strings.Builder
		quoted := false
		for i < len(s) {
			c := s[i]
			if c == '\'' {
				if quoted && i+1 < len(s) && s[i+1] == '\'' {
					b.WriteByte('\'')
					i += 2
					continue
				}
				quoted = !quoted
				i++
				continue
			}
			if !quoted && (c == ' ' || c == '\t') {
				break
			}
			b.WriteByte(c)
			i++
		}
		if quoted {
			return nil, ErrQuote
		}
		toks = append(toks, b.String())
	}
	return toks, nil
}

// NewMemShell is the convenience a realm or a test wants: a fresh ram root,
// a namespace over it, and a shell. It exists here rather than in ns so that
// ns keeps no dependency on a particular file server.
func NewMemShell(uid string, mode Mode, now func() int64) (*Shell, *memfs.FS) {
	h := int64(0)
	if now != nil {
		h = now()
	}
	fs := memfs.New(uid, h)
	return New(ns.New(fs.Root()), mode, now), fs
}

