// Package coin is a GRC20 that cannot exist until its author has answered the
// three questions a social app's token usually dodges: what mints it, what
// burns it, and who has a reason to buy it.
//
// # Why a package and not a convention
//
// Every app in the x/social family is asked the same question, "and can it
// have a token", and the honest answer is only yes when all three of those
// have an answer. A token with a mint rule and no sink is a scoreboard with a
// price: supply grows, nothing consumes it, and the number on the leaderboard
// is the whole product. That is the shape a chain-wide measurement keeps
// finding, and it is cheap to avoid, so [New] refuses a [Policy] with a blank
// field rather than letting the omission ship.
//
// The three strings are not validated beyond being non-empty, because no
// package can check that a sink is real. They are a declaration, rendered on
// the realm's own page by [Coin.Render], where being wrong is visible.
//
// # The model
//
//	earned  minted by the app, for the behaviour the app wants more of
//	spent   burned by the app, for the thing holders actually want
//	traded  a plain GRC20 transfer, which is what makes the sink a market
//
// Earning and spending are the app's business and go through [Coin.Earn] and
// [Coin.Spend], which keep running totals so a reader can see the two halves
// against each other. Transfers, approvals and balances are the embedded
// [grc20.Token]'s, unchanged, so wallets and indexers see an ordinary GRC20.
//
// # Usage
//
// A realm holds one Coin and never exports the ledger:
//
//	var points = coin.New("Thread Points", "THREAD", 0, 0, coin.Policy{
//		Mint:  "1 per distinct address that replies to your thread",
//		Sink:  "burned to pin a thread to the top of its page",
//		Buyer: "anyone who wants placement and has not earned it",
//	}, 0, cur)
//
// The trailing `_ int, rlm realm` is the shape a pure package has to use to
// reach the caller's frame: a p/ package may not declare a crossing function,
// so the realm token is threaded as a later parameter, exactly as grc20's own
// tellers do.
package coin

import (
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/num/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Policy is the three declarations a Coin cannot be created without.
//
// Each one is a sentence for a human: it is rendered on the issuing realm's
// page and nothing branches on it.
type Policy struct {
	// Mint says what behaviour earns the token, precisely enough that a
	// reader can work out whether they can farm it.
	Mint string

	// Sink says what destroys it. "Nothing" is not an answer; if there is
	// no sink, there is no reason for the token to exist.
	Sink string

	// Buyer says who wants it badly enough to acquire it from someone who
	// earned it. This is the one most often left blank, and the one that
	// decides whether the other two matter.
	Buyer string
}

// Valid reports whether every field is filled in.
func (p Policy) Valid() bool {
	return p.Mint != "" && p.Sink != "" && p.Buyer != ""
}

// Coin is a GRC20 plus the policy it was issued under and the running totals
// of the two flows the policy describes.
type Coin struct {
	tok    *grc20.Token
	led    *grc20.PrivateLedger
	policy Policy

	earned int64 // cumulative minted
	spent  int64 // cumulative burned
}

// New issues the token. It panics when the policy is incomplete, which is the
// whole point of the package: the declaration happens before the first unit
// exists, not in a README written afterwards.
//
// name, symbol, decimals and id are grc20's own; id distinguishes two tokens
// issued by the same realm.
func New(name, symbol string, decimals int, id seqid.ID, policy Policy, _ int, rlm realm) *Coin {
	if !policy.Valid() {
		panic("coin: a token needs a mint rule, a sink and a buyer; one of the three is empty")
	}
	tok, led := grc20.NewToken(name, symbol, decimals, id, rlm)
	return &Coin{tok: tok, led: led, policy: policy}
}

// Token returns the GRC20 itself, for the realm to expose as its read API and
// to register with a token registry.
func (c *Coin) Token() *grc20.Token { return c.tok }

// CallerTeller is the teller that acts as the user who called the realm: it
// moves their own balance and nothing else.
//
// It is exposed, where the ledger is not, because transfer and approve are
// what make the sink a market. Mint and burn stay behind [Coin.Earn] and
// [Coin.Spend] so the mint rule keeps exactly one call site.
func (c *Coin) CallerTeller() grc20.Teller { return c.led.CallerTeller() }

// Policy returns the declarations the token was issued under.
func (c *Coin) Policy() Policy { return c.policy }

// Earn mints amount to addr. The realm calls it from the one place its mint
// rule is implemented, so that rule has exactly one call site.
//
// A non-positive amount is a no-op rather than an abort: a mint rule that
// computes zero (nothing new happened) is a normal outcome and should not
// fail the transaction that discovered it.
func (c *Coin) Earn(to address, amount int64) {
	if amount <= 0 {
		return
	}
	if err := c.led.Mint(to, amount); err != nil {
		panic("coin: mint: " + err.Error())
	}
	c.earned += amount
}

// Spend burns amount from addr, which is how the sink consumes supply.
//
// It aborts when the balance is short, naming both numbers, because the
// caller is a user who is about to be told they cannot afford something.
func (c *Coin) Spend(from address, amount int64) {
	if amount <= 0 {
		panic("coin: spend: amount must be positive")
	}
	if bal := c.tok.BalanceOf(from); bal < amount {
		panic(ufmt.Sprintf("coin: balance %d is short of %d %s", bal, amount, c.tok.GetSymbol()))
	}
	if err := c.led.Burn(from, amount); err != nil {
		panic("coin: burn: " + err.Error())
	}
	c.spent += amount
}

// BalanceOf is the holder's balance.
func (c *Coin) BalanceOf(addr address) int64 { return c.tok.BalanceOf(addr) }

// Supply is what exists right now, that is, earned minus spent.
func (c *Coin) Supply() int64 { return c.tok.TotalSupply() }

// Earned and Spent are the cumulative flows. Their difference is [Coin.Supply]
// and they are kept separately because a sink that never fires is invisible in
// the supply alone: a flat line reads the same as no sink at all.
func (c *Coin) Earned() int64 { return c.earned }

// Spent is the cumulative amount burned through [Coin.Spend].
func (c *Coin) Spent() int64 { return c.spent }

// Holders is how many addresses the ledger knows about.
func (c *Coin) Holders() int { return c.tok.KnownAccounts() }

// Render is the block a realm puts on its own page: the three declarations,
// then the two flows against each other.
//
// The policy strings are escaped: they are constants in practice, but a realm
// could build one from configuration, and this package cannot tell.
func (c *Coin) Render() string {
	out := md.H3(ui.Inline(c.tok.GetName()) + " (" + ui.Inline(c.tok.GetSymbol()) + ")")

	t := ui.NewTable("", "")
	t.Row("earns", ui.Cell(c.policy.Mint))
	t.Row("burns", ui.Cell(c.policy.Sink))
	t.Row("bought by", ui.Cell(c.policy.Buyer))
	out += t.String()

	s := ui.NewTable("supply", "earned", "burned", "holders")
	s.Row(
		num.Dec(c.Supply(), c.tok.GetDecimals()),
		num.Dec(c.earned, c.tok.GetDecimals()),
		num.Dec(c.spent, c.tok.GetDecimals()),
		ufmt.Sprintf("%d", c.Holders()),
	)
	out += s.String()

	return out
}

package coin

import (
	"strings"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var fullPolicy = Policy{
	Mint:  "1 per distinct replier",
	Sink:  "burned to pin a thread",
	Buyer: "anyone who wants placement",
}

// newTestCoin builds a Coin from a test. The same-realm cross promotes the
// test's EOA-origin cur into a code realm frame, which is what grc20.NewToken
// requires: it is the shape grc20's own tests use (vendor/.../token_test.gno).
func newTestCoin(t *testing.T, policy Policy, id seqid.ID, rlm realm) (c *Coin) {
	t.Helper()
	func(cur realm) {
		c = New("Test Points", "TEST", 0, id, policy, 0, cur)
	}(cross(rlm))
	return
}

func TestPolicyValid(t *testing.T) {
	tests := []struct {
		name string
		p    Policy
		want bool
	}{
		{"complete", fullPolicy, true},
		{"no mint rule", Policy{Sink: "s", Buyer: "b"}, false},
		{"no sink", Policy{Mint: "m", Buyer: "b"}, false},
		{"no buyer", Policy{Mint: "m", Sink: "s"}, false},
		{"empty", Policy{}, false},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, tt.p.Valid(), tt.name)
	}
}

// New's refusal is asserted with AbortsContains and not PanicsContains: the
// constructor runs behind a same-realm cross (the frame grc20.NewToken
// requires), and a panic raised across a crossing call is an abort that no
// recover() in the caller can catch.
func TestNewRefusesAnIncompletePolicy(cur realm, t *testing.T) {
	uassert.AbortsContains(t, cur, "mint rule, a sink and a buyer", func() {
		newTestCoin(t, Policy{Mint: "m", Sink: "s"}, 0, cur)
	})
}

func TestEarnAndSpendMoveSupplyInOppositeDirections(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 1, cur)
	alice := testutils.TestAddress("alice")

	c.Earn(alice, 10)
	uassert.Equal(t, int64(10), c.BalanceOf(alice))
	uassert.Equal(t, int64(10), c.Supply())

	c.Spend(alice, 4)
	uassert.Equal(t, int64(6), c.BalanceOf(alice))
	uassert.Equal(t, int64(6), c.Supply())

	// The flows stay visible after the fact, which the supply alone cannot
	// show: 6 in supply could be 6 earned and nothing burned.
	uassert.Equal(t, int64(10), c.Earned())
	uassert.Equal(t, int64(4), c.Spent())
}

func TestEarnOfNothingIsANoOp(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 2, cur)
	alice := testutils.TestAddress("alice")

	c.Earn(alice, 0)
	c.Earn(alice, -5)
	uassert.Equal(t, int64(0), c.Supply())
	uassert.Equal(t, int64(0), c.Earned())
	uassert.Equal(t, 0, c.Holders())
}

func TestSpendNamesBothNumbersWhenShort(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 3, cur)
	alice := testutils.TestAddress("alice")
	c.Earn(alice, 2)

	uassert.PanicsContains(t, cur, "balance 2 is short of 5", func() {
		c.Spend(alice, 5)
	})
	uassert.PanicsContains(t, cur, "must be positive", func() {
		c.Spend(alice, 0)
	})
	uassert.Equal(t, int64(2), c.BalanceOf(alice))
}

func TestRenderCarriesTheThreeDeclarations(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 4, cur)
	c.Earn(testutils.TestAddress("alice"), 7)
	c.Spend(testutils.TestAddress("alice"), 3)

	out := c.Render()
	for _, want := range []string{
		"Test Points",
		"TEST",
		fullPolicy.Mint,
		fullPolicy.Sink,
		fullPolicy.Buyer,
	} {
		uassert.True(t, strings.Contains(out, want), "render is missing "+want)
	}
	// 4 in supply, 7 earned, 3 burned, 1 holder.
	uassert.True(t, strings.Contains(out, "| 4 | 7 | 3 | 1 |"), "render is missing the flow row: "+out)
}

func TestTokenIsAnOrdinaryGRC20(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 5, cur)
	alice := testutils.TestAddress("alice")
	c.Earn(alice, 3)

	tok := c.Token()
	urequire.False(t, tok == nil, "token should not be nil")
	uassert.Equal(t, "TEST", tok.GetSymbol())
	uassert.Equal(t, int64(3), tok.TotalSupply())
	uassert.Equal(t, int64(3), tok.BalanceOf(alice))
}

// Package threads is the engine behind an embeddable discussion block: the
// text half of what a reaction bar does, keyed on the PAGE it is shown under
// rather than on the realm that stores it.
//
// # Why not a forum
//
// A forum is a destination, and a destination has to earn its traffic before
// anybody writes the first post. A block does not: it is dropped into pages
// that already have readers, and the discussion attaches to the object it is
// about. One realm holds every thread, every host realm ships the same two
// lines, and no host realm stores anything.
//
// That is the shape the web settled on for comments in 2010, and the same one
// [gno.land/p/moul/reactions] uses for the tally. This package is deliberately
// its neighbour: reactions are a closed palette and need no moderation, text
// needs some, and the two are separate so a realm can take the cheap one alone.
//
// # The model
//
//	Board    every thread, across every page
//	Thread   a root post: page, author, body, height, pin, replies
//	Reply    an author, a body and a height, and nothing else
//
// A thread remembers the set of addresses that have replied to it, which is
// what lets a realm implement "earned by being replied to" without counting
// one person twice. [Board.Reply] reports whether the replier was new, so the
// mint rule has exactly one signal and exactly one call site.
//
// # Ordering, and the pin
//
// [Board.List] returns pinned threads first, then the rest, both newest first,
// which is a partition and not a sort: no comparator, no tie to break, and the
// same input always produces the same page. A pin is an absolute height, so it
// expires on its own and nothing has to be swept.
//
// The realm decides what a pin costs. This package only enforces that a pin
// cannot be moved backwards, so buying one does not shorten somebody else's.
//
// # Page keys and bodies
//
// A page key is a package path, the full one, chain domain included.
// [ValidPage] bounds it to a path-shaped lowercase ASCII string of at most
// [MaxPageLen] bytes, so a stored key can never be a markdown payload. A body
// is bounded by [MaxBodyLen] and rejected when it carries a control character,
// but it is otherwise free text and therefore attacker-controlled markdown:
// everything here escapes it with ui.Inline or ui.Cell, and so must any realm
// that renders one itself.
package threads

import (
	"chain/markdown"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
)

const (
	// MaxPageLen is the longest page key accepted, matching
	// gno.land/p/moul/reactions so the two blocks agree on what a page is.
	MaxPageLen = 120

	// MaxBodyLen is the longest post or reply accepted, in bytes. Long
	// enough for a real comment, short enough that one call cannot lock an
	// unbounded storage deposit somebody else is paying for.
	MaxBodyLen = 1000

	// ExcerptLen is how much of a body a listing shows.
	ExcerptLen = 60
)

// The errors a caller can get back. A p/ returns them; the realm decides to
// abort.
var (
	ErrBadPage   = errors.New("threads: not a page key")
	ErrBadBody   = errors.New("threads: body is empty, too long, or has control characters")
	ErrNoThread  = errors.New("threads: no such thread")
	ErrPinIsPast = errors.New("threads: a pin cannot be moved backwards")
)

// Reply is one answer under a thread.
type Reply struct {
	Author address
	Body   string
	At     int64 // block height
}

// Thread is a root post and everything under it.
type Thread struct {
	Page    string
	Author  address
	Body    string
	At      int64 // block height
	Replies []Reply

	// PinnedUntil is the height the thread stops being pinned at. Zero is
	// never pinned, and a past height is an expired pin: nothing has to
	// sweep it.
	PinnedUntil int64

	// repliers is the set of addresses that have replied, so a thread can
	// be scored on people rather than on messages.
	repliers map[string]bool
}

// Pinned reports whether the thread is pinned at height now.
func (t *Thread) Pinned(now int64) bool { return t != nil && t.PinnedUntil > now }

// Repliers is how many distinct addresses have replied.
func (t *Thread) Repliers() int {
	if t == nil {
		return 0
	}
	return len(t.repliers)
}

// HasReplied reports whether who has already replied to this thread.
func (t *Thread) HasReplied(who address) bool {
	if t == nil {
		return false
	}
	return t.repliers[who.String()]
}

// Board holds every thread, indexed by the page it was posted under.
type Board struct {
	threads *store.Store
	pages   map[string][]store.ID // page key -> ids, oldest first
}

// NewBoard returns an empty board.
func NewBoard() *Board {
	return &Board{threads: store.Named("thread"), pages: map[string][]store.ID{}}
}

// Post opens a thread on page and returns its id.
func (b *Board) Post(page string, author address, body string, at int64) (store.ID, error) {
	if !ValidPage(page) {
		return 0, ErrBadPage
	}
	if !ValidBody(body) {
		return 0, ErrBadBody
	}
	id := b.threads.Add(&Thread{
		Page:     page,
		Author:   author,
		Body:     body,
		At:       at,
		repliers: map[string]bool{},
	})
	b.pages[page] = append(b.pages[page], id)
	return id, nil
}

// Reply appends to a thread and reports whether this author had never replied
// to it before.
//
// That boolean is the mint signal: a realm that pays an author for attention
// wants distinct people, not distinct messages, and a thread's own author
// replying to themselves is never new.
func (b *Board) Reply(id store.ID, author address, body string, at int64) (isNewReplier bool, err error) {
	t, ok := b.Get(id)
	if !ok {
		return false, ErrNoThread
	}
	if !ValidBody(body) {
		return false, ErrBadBody
	}
	t.Replies = append(t.Replies, Reply{Author: author, Body: body, At: at})

	key := author.String()
	if author == t.Author || t.repliers[key] {
		return false, nil
	}
	t.repliers[key] = true
	return true, nil
}

// Pin keeps a thread at the top of its page until height until.
//
// It refuses to move a pin backwards, so a cheap pin cannot cut short an
// expensive one, and extends from whichever is later: the current pin or now.
func (b *Board) Pin(id store.ID, until int64) error {
	t, ok := b.Get(id)
	if !ok {
		return ErrNoThread
	}
	if until <= t.PinnedUntil {
		return ErrPinIsPast
	}
	t.PinnedUntil = until
	return nil
}

// Get returns a thread by id.
func (b *Board) Get(id store.ID) (*Thread, bool) {
	v, ok := b.threads.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Thread), true
}

// Len is how many threads exist, across every page.
func (b *Board) Len() int { return b.threads.Len() }

// Pages is how many pages have ever been posted on.
func (b *Board) Pages() int { return len(b.pages) }

// PageLen is how many threads a page holds.
func (b *Board) PageLen(page string) int { return len(b.pages[page]) }

// Listing is one row of [Board.List]: the thread and the id a link needs.
type Listing struct {
	ID     store.ID
	Thread *Thread
}

// List returns up to limit threads on page: pinned first, then the rest, both
// newest first.
//
// It is a partition and not a sort. There is no comparator and no tie to
// break, so two identical calls always produce the same page, which is what a
// Render needs. limit <= 0 returns everything.
func (b *Board) List(page string, now int64, limit int) []Listing {
	ids := b.pages[page]
	var pinned, rest []Listing
	for i := len(ids) - 1; i >= 0; i-- {
		t, ok := b.Get(ids[i])
		if !ok {
			continue
		}
		item := Listing{ID: ids[i], Thread: t}
		if t.Pinned(now) {
			pinned = append(pinned, item)
		} else {
			rest = append(rest, item)
		}
	}
	out := append(pinned, rest...)
	if limit > 0 && len(out) > limit {
		out = out[:limit]
	}
	return out
}

// Recent returns up to limit threads from every page, newest first. It is what
// the hosting realm's own homepage shows.
func (b *Board) Recent(limit int) []Listing {
	var out []Listing
	for _, e := range b.threads.PageReverse(1, limit) {
		out = append(out, Listing{ID: e.ID, Thread: e.Value.(*Thread)})
	}
	return out
}

// ValidPage reports whether page is a usable page key: path-shaped, lowercase
// ASCII, no leading, trailing or doubled slash, at most [MaxPageLen] bytes.
//
// Same rule as gno.land/p/moul/reactions, deliberately: a realm embedding both
// blocks passes one key to both.
func ValidPage(page string) bool {
	if page == "" || len(page) > MaxPageLen {
		return false
	}
	if strings.HasPrefix(page, "/") || strings.HasSuffix(page, "/") ||
		strings.Contains(page, "//") || !strings.Contains(page, "/") {
		return false
	}
	for i := 0; i < len(page); i++ {
		c := page[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '/' || c == '.' || c == '-' || c == '_' || c == ':':
		default:
			return false
		}
	}
	return true
}

// ValidBody reports whether body can be stored: non-empty after the render's
// own stripping and trimming,
// within [MaxBodyLen], and free of control characters.
//
// Control characters are refused rather than stripped because a body is shown
// back to its author: silently rewriting what somebody wrote is worse than
// telling them it was refused. Everything else is allowed and escaped at
// render time, since a validator and an escaper protect against different
// mistakes.
func ValidBody(body string) bool {
	if len(body) > MaxBodyLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(body)) == "" {
		return false
	}
	for i := 0; i < len(body); i++ {
		c := body[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// Block renders the embeddable widget: the page's threads, then the button
// that opens a new one.
//
// realmPath is the realm that owns Post and Reply, given as the full package
// path from its gnomod.toml module line. It is a parameter and not a constant
// because this package is the engine and not the deployment.
func Block(realmPath, page string, items []Listing, total int, now int64) string {
	out := ""
	if len(items) == 0 {
		out += ui.Empty("No discussion yet.")
	} else {
		t := ui.NewTable("", "#", "thread", "by", "replies")
		for _, it := range items {
			mark := ""
			if it.Thread.Pinned(now) {
				mark = "📌"
			}
			t.Row(
				mark,
				// The link title is the id and never the body. md.Link
				// escapes markdown but NOT a pipe (sanitize.InlineText
				// leaves it; only ui.Cell rewrites it), so a body used as
				// a link title inside a table opens a column.
				md.Link("#"+it.ID.String(), ThreadURL(realmPath, it.ID)),
				// Cut first, escape second: the other order can strand a
				// trailing backslash that escapes the chrome after it.
				ui.Cell(ui.ShortN(it.Thread.Body, ExcerptLen, 0)),
				ui.Addr(it.Thread.Author),
				strconv.Itoa(len(it.Thread.Replies)),
			)
		}
		out += t.String()
	}

	out += "\n" + ui.ActionIn(realmPath, "💬 Post", "Post", "page", page, "body", "")
	if total > len(items) {
		out += " · " + md.Link(
			strconv.Itoa(total)+" threads",
			PageURL(realmPath, page),
		)
	}
	return out + "\n"
}

// ThreadURL is the gnoweb path of one thread on the hosting realm.
func ThreadURL(realmPath string, id store.ID) string {
	return RealmURL(realmPath) + ":thread/" + id.String()
}

// PageURL is the gnoweb path of a page's full thread list.
func PageURL(realmPath, page string) string {
	return RealmURL(realmPath) + ":page/" + page
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

package threads

import "testing"

// Finding 325-input-validation-1 (review run 001-cd0b6a9).
//
// A validator that calls a field required must agree with the escaper its own
// render runs. strings.TrimSpace uses unicode.IsSpace, which does NOT include
// U+200B and the rest of the bidi and zero-width set, while every escaper on
// the output side runs chain/markdown.StripBidiAndZeroWidth, which does. So a
// value made only of those characters passes validation and renders as
// nothing: a required field that is blank on the page.
//
// The cases below are the invariant, not the implementation. A value the
// validator accepts must still be non-empty after the stripper.
func TestValidatorsAgreeWithTheEscaper(t *testing.T) {
	// One per class the stripper removes, so a fix that handles only
	// U+200B does not pass.
	blank := []string{
		"\u200b\u200b\u200b",   // ZWSP
		"\u200d",                // ZWJ
		"\u200e",                // LRM
		"\u202e",                // RLO
		"\u2066\u2069",          // LRI PDI
		"\ufeff",                // BOM
		" \u200b \u200b ",        // mixed with real spaces
	}
	// These must stay valid: the stripper removes the marks and leaves text.
	ok := []string{
		"a",
		"a\u200bb",
		"  padded  ",
	}

	for _, s := range blank {
		if ValidBody(s) {
			t.Errorf("ValidBody(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidBody(s) {
			t.Errorf("ValidBody(%q) is false, but it renders as real text", s)
		}
	}

}

// Package jury is a commit-reveal adversarial review protocol for disputes
// over agent work.
//
// The hard part of an agent economy is not paying agents — it is deciding
// what happens when an agent's output is disputed. This realm runs a small
// jury: a fixed panel of reviewers each *commit* to a hidden verdict, then
// *reveal* it. Commit-reveal means no juror can copy another's vote or be
// swayed after seeing the tally; every verdict is locked in blind.
//
// The subject of a case is an opaque string — a receipt sequence, a claim
// id, an off-chain artifact hash — so this realm composes with the receipt
// and gnomem demos without depending on them.
//
// Bonding and slashing (a juror stakes coins, loses them for provably bad
// verdicts) are the natural economic layer on top; this demo shows the
// mechanism without the money.
package jury

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/agents/commit/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Phase is a case's position in the commit-reveal lifecycle.
type Phase string

const (
	PhaseCommit Phase = "commit"
	PhaseReveal Phase = "reveal"
	PhaseClosed Phase = "closed"
)

// Juror is one panelist and their (eventually revealed) verdict.
type Juror struct {
	Addr       address
	Commitment string // commit.Verdict(verdict, salt)
	Committed  bool
	Revealed   bool
	Verdict    bool // meaningful once Revealed
	Height     int64
}

// Case is a single dispute under review by a fixed panel.
type Case struct {
	ID       uint64
	Subject  string // opaque reference to the disputed thing
	Opener   address
	Phase    Phase
	Jurors   []*Juror
	OpenedAt int64
	Outcome  string // "upheld" | "rejected" | "tie" once closed
	Yes      int
	No       int
}

var cases []*Case // index 0 => ID 1

// The bounds on what a wallet may open. OpenCase is callable by anyone, so
// without them the case list and every panel grow without limit, and so does
// the index page that renders them.
const (
	MaxCases    = 1000
	MaxJurors   = 25
	MaxSubject  = 200 // bytes
	IndexRecent = 50  // cases the index lists, newest first

	MaxCommitment = 128 // bytes; commit.Verdict returns 64
)

// OpenCase starts a dispute with a fixed panel of jurors, given as
// comma-separated addresses. An odd panel size avoids ties; duplicates and
// invalid addresses are rejected.
//
// The panel is a string, not a []address, because MsgCall carries every
// argument as a string and the VM decodes no slice but []byte: a []address
// parameter made this function unreachable from any wallet.
func OpenCase(cur realm, subject, jurorsCSV string) uint64 {
	opener := caller(cur)
	// Checked after sanitizing: a subject of only zero-width runes is not empty
	// as bytes, and renders as nothing.
	assert(strings.TrimSpace(ui.Inline(subject)) != "", "empty subject")
	assert(len(subject) <= MaxSubject, "subject too long")
	assert(len(cases) < MaxCases, "the jury is full")
	jurors := parseJurors(jurorsCSV)
	assert(len(jurors) >= 1, "need at least one juror")
	assert(len(jurors) <= MaxJurors, "panel too large")

	seen := make(map[string]bool)
	panel := make([]*Juror, 0, len(jurors))
	for _, j := range jurors {
		key := j.String()
		assert(!seen[key], "duplicate juror: "+key)
		seen[key] = true
		panel = append(panel, &Juror{Addr: j})
	}

	id := uint64(len(cases)) + 1
	cases = append(cases, &Case{
		ID:       id,
		Subject:  subject,
		Opener:   opener,
		Phase:    PhaseCommit,
		Jurors:   panel,
		OpenedAt: runtime.ChainHeight(),
	})
	chain.Emit("CaseOpened", "id", ufmt.Sprintf("%d", id), "jurors", ufmt.Sprintf("%d", len(panel)))
	return id
}

// Commit locks in a juror's hidden verdict. commitment must equal
// commit.Verdict(verdict, salt) — computed off-chain. When the last juror
// commits, the case advances to the reveal phase automatically.
func Commit(cur realm, caseID uint64, commitment string) {
	who := caller(cur)
	c := mustCase(caseID)
	assert(c.Phase == PhaseCommit, "not in commit phase")
	assert(commitment != "", "empty commitment")
	// commit.Verdict is a hex sha256; anything longer is not one, and would be
	// stored and compared on every later Commit in the case.
	assert(len(commitment) <= MaxCommitment, "commitment too long")
	j := mustJuror(c, who)
	assert(!j.Committed, "already committed")
	// Every commitment is public through Get, so without this a juror could
	// commit a copy of another's hash, then reveal the same (verdict, salt)
	// once the first juror's reveal puts it in a transaction. Refusing a
	// repeat makes a copied commitment unrevealable.
	for _, other := range c.Jurors {
		assert(!other.Committed || other.Commitment != commitment, "commitment already used in this case")
	}
	j.Commitment = commitment
	j.Committed = true
	j.Height = runtime.ChainHeight()

	if allCommitted(c) {
		c.Phase = PhaseReveal
		chain.Emit("CasePhase", "id", ufmt.Sprintf("%d", caseID), "phase", string(PhaseReveal))
	}
}

// Reveal opens a juror's verdict. The (verdict, salt) must reproduce the
// commitment made earlier, or the reveal is rejected. When the last juror
// reveals, the case closes and the majority outcome is recorded.
func Reveal(cur realm, caseID uint64, verdict bool, salt string) {
	who := caller(cur)
	c := mustCase(caseID)
	assert(c.Phase == PhaseReveal, "not in reveal phase")
	j := mustJuror(c, who)
	assert(j.Committed && !j.Revealed, "nothing to reveal")
	assert(commit.Verdict(verdict, salt) == j.Commitment, "reveal does not match commitment")

	j.Revealed = true
	j.Verdict = verdict
	if verdict {
		c.Yes++
	} else {
		c.No++
	}
	chain.Emit("VerdictRevealed", "id", ufmt.Sprintf("%d", caseID), "verdict", boolStr(verdict))

	if allRevealed(c) {
		closeCase(c)
	}
}

// ---- read-only API ----

// Get returns a copy of a case (jurors flattened separately via Jury).
func Get(caseID uint64) Case { return *mustCase(caseID) }

// Outcome returns the recorded outcome, or "" if the case is still open.
func Outcome(caseID uint64) string { return mustCase(caseID).Outcome }

// Count returns the number of cases.
func Count() int { return len(cases) }

// ---- internal ----

func closeCase(c *Case) {
	switch {
	case c.Yes > c.No:
		c.Outcome = "upheld"
	case c.No > c.Yes:
		c.Outcome = "rejected"
	default:
		c.Outcome = "tie"
	}
	c.Phase = PhaseClosed
	chain.Emit("CaseClosed", "id", ufmt.Sprintf("%d", c.ID), "outcome", c.Outcome)
}

func allCommitted(c *Case) bool {
	for _, j := range c.Jurors {
		if !j.Committed {
			return false
		}
	}
	return true
}

func allRevealed(c *Case) bool {
	for _, j := range c.Jurors {
		if !j.Revealed {
			return false
		}
	}
	return true
}

func mustCase(id uint64) *Case {
	assert(id >= 1 && id <= uint64(len(cases)), "unknown case")
	return cases[id-1]
}

func mustJuror(c *Case, addr address) *Juror {
	for _, j := range c.Jurors {
		if j.Addr == addr {
			return j
		}
	}
	panic("caller is not on this jury")
}

func boolStr(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

func assert(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

// Render shows all cases, or one case's panel + tally at :<id>.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderCase(parseID(path))
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Agent Jury\n\n")
	sb.WriteString("_Who checks the agents?_ Blind commit-reveal review by a fixed panel.\n\n")
	if len(cases) == 0 {
		sb.WriteString("_No cases yet._\n")
		return sb.String()
	}
	if len(cases) > IndexRecent {
		sb.WriteString(ufmt.Sprintf("The %d most recent of %d cases, newest first.\n\n", IndexRecent, len(cases)))
	}
	sb.WriteString("| # | Subject | Phase | ✅ | ❌ | Outcome |\n")
	sb.WriteString("|---|---|---|---|---|---|\n")
	// Newest first, and only the last IndexRecent: the page has to render at
	// MaxCases too.
	for i := len(cases) - 1; i >= 0 && i >= len(cases)-IndexRecent; i-- {
		c := cases[i]
		out := c.Outcome
		if out == "" {
			out = "—"
		}
		sb.WriteString(ufmt.Sprintf("| [%d](/r/moul/agents/jury/v0:%d) | %s | %s | %d | %d | %s |\n",
			c.ID, c.ID, ui.Cell(c.Subject), string(c.Phase), c.Yes, c.No, out))
	}
	return sb.String()
}

func renderCase(id uint64) string {
	c := mustCase(id)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Case #%d\n\n", c.ID))
	sb.WriteString(ufmt.Sprintf("- **Subject:** %s\n", ui.Inline(c.Subject)))
	sb.WriteString(ufmt.Sprintf("- **Phase:** %s\n", string(c.Phase)))
	sb.WriteString(ufmt.Sprintf("- **Opened by:** %s at height %d\n", short(c.Opener), c.OpenedAt))
	if c.Outcome != "" {
		sb.WriteString(ufmt.Sprintf("- **Outcome:** **%s** (%d ✅ / %d ❌)\n", c.Outcome, c.Yes, c.No))
	}
	sb.WriteString("\n## Panel\n\n")
	sb.WriteString("| Juror | Committed | Revealed | Verdict | Dissent |\n|---|---|---|---|---|\n")
	majority := c.Yes >= c.No // for dissent marking once closed
	for _, j := range c.Jurors {
		verdict, dissent := "—", ""
		if j.Revealed {
			verdict = boolStr(j.Verdict)
			if c.Phase == PhaseClosed && c.Outcome != "tie" && j.Verdict != majority {
				dissent = "⚠"
			}
		}
		sb.WriteString(ufmt.Sprintf("| %s | %t | %t | %s | %s |\n",
			short(j.Addr), j.Committed, j.Revealed, verdict, dissent))
	}
	return sb.String()
}

func parseID(s string) uint64 {
	var n uint64
	for i := 0; i < len(s); i++ {
		ch := s[i]
		assert(ch >= '0' && ch <= '9', "invalid case path: "+s)
		n = n*10 + uint64(ch-'0')
	}
	return n
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// parseJurors splits a comma-separated panel, trimming spaces around each
// address and refusing an empty or invalid one.
func parseJurors(csv string) []address {
	var out []address
	for _, part := range strings.Split(csv, ",") {
		a := address(strings.TrimSpace(part))
		assert(a.IsValid(), "invalid juror address: "+string(a))
		out = append(out, a)
	}
	return out
}

// caller is the address that crossed into this realm, after checking that the
// realm token is this frame's own. Every entry point reads it first, before
// any other work.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("jury: spoofed realm")
	}
	return cur.Previous().Address()
}

package jury

import (
	"strings"
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/agents/commit/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	opener = testutils.TestAddress("opener")
	j1     = testutils.TestAddress("juror1")
	j2     = testutils.TestAddress("juror2")
	j3     = testutils.TestAddress("juror3")
	nobody = testutils.TestAddress("nobody")
)

// Full happy path: 3 jurors commit blind, then reveal; majority upholds.
func TestCommitRevealMajority(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "receipt#7", j1.String()+","+j2.String()+", "+j3.String())
	uassert.Equal(t, string(PhaseCommit), string(Get(id).Phase))

	// Each juror commits a hidden verdict (hash computed off-chain).
	commitAs(cur, j1, id, true, "s1")
	commitAs(cur, j2, id, false, "s2")
	uassert.Equal(t, string(PhaseCommit), string(Get(id).Phase)) // not all in yet
	commitAs(cur, j3, id, true, "s3")
	uassert.Equal(t, string(PhaseReveal), string(Get(id).Phase)) // auto-advanced

	revealAs(cur, j1, id, true, "s1")
	revealAs(cur, j2, id, false, "s2")
	revealAs(cur, j3, id, true, "s3")

	c := Get(id)
	uassert.Equal(t, string(PhaseClosed), string(c.Phase))
	uassert.Equal(t, "upheld", c.Outcome) // 2 yes vs 1 no
	uassert.Equal(t, 2, c.Yes)
	uassert.Equal(t, 1, c.No)

	uassert.True(t, len(Render("")) > 0)
	uassert.True(t, len(Render("1")) > 0)
}

// A juror cannot change their vote at reveal time: the commitment binds it.
func TestRevealMustMatchCommitment(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "claim#3", j1.String())
	commitAs(cur, j1, id, true, "salt")

	testing.SetRealm(testing.NewUserRealm(j1))
	uassert.AbortsWithMessage(t, cur, "reveal does not match commitment", func(cur realm) {
		Reveal(cur, id, false, "salt") // flipped verdict
	})
}

func TestOnlyPanelJurors(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "x", j1.String())
	testing.SetRealm(testing.NewUserRealm(nobody))
	uassert.AbortsWithMessage(t, cur, "caller is not on this jury", func(cur realm) {
		Commit(cur, id, commit.Verdict(true, "s"))
	})
}

func TestNoDuplicateJurors(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	uassert.AbortsWithMessage(t, cur, "duplicate juror: "+j1.String(), func(cur realm) {
		OpenCase(cur, "x", j1.String()+","+j1.String())
	})
}

// helpers

func commitAs(cur realm, juror address, id uint64, verdict bool, salt string) {
	testing.SetRealm(testing.NewUserRealm(juror))
	Commit(cross(cur), id, commit.Verdict(verdict, salt))
}

func revealAs(cur realm, juror address, id uint64, verdict bool, salt string) {
	testing.SetRealm(testing.NewUserRealm(juror))
	Reveal(cross(cur), id, verdict, salt)
}

// Commitments are public, so a juror who copies another's hash would reveal
// the same (verdict, salt) once the first reveal lands. The copy is refused.
func TestCopiedCommitmentIsRefused(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "copy", j1.String()+","+j2.String())
	commitAs(cur, j1, id, true, "s1")
	copied := Get(id).Jurors[0].Commitment
	testing.SetRealm(testing.NewUserRealm(j2))
	uassert.AbortsContains(t, cur, "commitment already used", func() { Commit(cross(cur), id, copied) })
}

// The panel arrives as one string, which is what a wallet can send.
func TestOpenCaseRejectsAnInvalidJuror(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	uassert.AbortsContains(t, cur, "invalid juror address", func() {
		OpenCase(cross(cur), "x", j1.String()+",notanaddress")
	})
	uassert.AbortsContains(t, cur, "invalid juror address", func() { OpenCase(cross(cur), "x", "") })
}

// The subject is wallet-controlled now that OpenCase is callable, so it is
// escaped on both pages that show it.
func TestSubjectIsEscaped(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "x | [claim](https://evil.example)", j1.String())
	idx, page := Render(""), Render(ufmt.Sprintf("%d", id))
	uassert.False(t, strings.Contains(idx, "[claim](https://evil.example)"), idx)
	uassert.False(t, strings.Contains(page, "[claim](https://evil.example)"), page)
}

// An even panel is allowed; a split vote closes as a tie rather than
// stalling or picking a side.
func TestEvenPanelSplitIsATie(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "even", j1.String()+","+j2.String())
	commitAs(cur, j1, id, true, "t1")
	commitAs(cur, j2, id, false, "t2")
	revealAs(cur, j1, id, true, "t1")
	revealAs(cur, j2, id, false, "t2")
	uassert.Equal(t, "tie", Outcome(id))
}

// OpenCase is callable by any wallet, so what it admits is bounded, and the
// index renders a fixed window whatever the case count.
func TestOpenCaseIsBounded(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	uassert.AbortsContains(t, cur, "subject too long", func() {
		OpenCase(cross(cur), strings.Repeat("s", MaxSubject+1), j1.String())
	})
	panel := ""
	for i := 0; i <= MaxJurors; i++ {
		if i > 0 {
			panel += ","
		}
		panel += testutils.TestAddress(ufmt.Sprintf("juror%d", i+10)).String()
	}
	uassert.AbortsContains(t, cur, "panel too large", func() { OpenCase(cross(cur), "big", panel) })

	for len(cases) < IndexRecent+5 {
		OpenCase(cross(cur), "filler", j1.String())
	}
	idx := Render("")
	uassert.True(t, strings.Contains(idx, ufmt.Sprintf("The %d most recent of %d cases", IndexRecent, len(cases))), idx)
	uassert.Equal(t, IndexRecent, strings.Count(idx, "](/r/moul/agents/jury/v0:"))
}

// The case count is bounded, and a subject that sanitizes to nothing is empty.
func TestCaseCountIsBoundedAndBlankSubjectRefused(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	uassert.AbortsContains(t, cur, "empty subject", func() { OpenCase(cross(cur), "​", j1.String()) })
	before := len(cases)
	for len(cases) < MaxCases {
		cases = append(cases, &Case{ID: uint64(len(cases) + 1), Subject: "filler", Phase: PhaseCommit})
	}
	defer func() { cases = cases[:before] }()
	uassert.AbortsContains(t, cur, "the jury is full", func() { OpenCase(cross(cur), "one more", j1.String()) })
}

// A commitment is a hash, and a juror cannot store an arbitrary blob as one.
func TestCommitmentIsBounded(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(opener))
	id := OpenCase(cross(cur), "sized", j1.String())
	testing.SetRealm(testing.NewUserRealm(j1))
	uassert.AbortsContains(t, cur, "commitment too long", func() {
		Commit(cross(cur), id, strings.Repeat("a", MaxCommitment+1))
	})
	uassert.Equal(t, 64, len(commit.Verdict(true, "s")))
}

// Package relay is a bounded message bus for autonomous (AI) agents.
//
// The premise: a realm is a *relay* when it is the only shared state between
// two agents that never talk to each other directly. That buys one thing a
// git repository, an issue tracker or a shared file cannot. Authorship is the
// signature. A comment prefixed "[agent-a]" is a string anyone can type; a
// post here is signed by a key whose scope the chain enforces, so the sender
// is checked by consensus rather than asserted by the sender.
//
// Read that claim carefully, because the obvious implementation does not
// deliver it. A session-signed call presents the session's OWNER as the
// caller, so recording [chain/runtime.Realm.Previous] alone records the same
// account for every agent one owner runs, and the relay is back to trusting a
// label. [chain/runtime.GetSessionInfo] is what closes the gap: it reports
// the delegated key that actually signed, which the caller did not choose.
// v0 shipped without it and every post read as its owner.
//
// Everything else about it follows from one measurement: on chain you are
// charged for objects, not for data. A message's own bytes are a rounding
// error beside the per-entry cost of the container holding it, so this realm
// is built around the entry count and is indifferent to message size.
//
// Three consequences, each of which shows up in the code:
//
//  1. The log is a fixed-capacity ring, allocated once at deploy. Its storage
//     is decided at [init] and never grows. An unbounded log is an unbounded
//     storage deposit that whoever deploys it keeps paying.
//  2. A post evicts the oldest entry in the *same call*. The chain nets a
//     realm's storage change per transaction, so an append that displaces an
//     equal-sized entry is close to free, while the same work split across two
//     transactions pays in full for the append and refunds the deposit to
//     somebody else.
//  3. Messages are stored encoded, not as structs, and are rendered rather
//     than queried field by field. See [gno.land/p/moul/agents/msg].
//
// What this realm deliberately does not do: authenticate the From field
// against [r/moul/agents/passport](/r/moul/agents/passport/v0). Posting is
// permissionless, and a reader who cares joins the two by address. Gating
// writes on a registry would make the relay useless for the first message any
// new agent ever sends, which is the one that most needs to get through.
package relay

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/agents/msg/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/ringbuffer/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Slots is the ring's capacity, fixed at deploy and never grown.
//
// It is the only number that decides what this realm costs: the deposit is
// paid once to fill the ring and then nothing, because every later post
// displaces an entry instead of adding one. Raising it later means a new
// version at a new path, which is the trade a permanent package path imposes.
const Slots = 64

// Entry is a stored message plus the two addresses the chain can vouch for.
//
// Author is the account the call is billed to. Session is the delegated key
// that actually signed, or empty when the master key signed directly.
//
// Both are needed and neither is enough. Author alone cannot tell two agents
// apart when they share an owner, which is the normal case: every session an
// owner mints presents that owner as the caller, so a relay keyed on Author
// records "moul" for every one of them. Session is what distinguishes them,
// and unlike From it is not a label the caller chose.
type Entry struct {
	Msg     msg.Msg
	Author  address
	Session address // empty when the master key signed
}

var (
	log  = ringbuffer.New(Slots)
	seq  uint64
	seen int // total posts ever, including those the ring has dropped
)

// Post appends a message and returns its sequence number.
//
// The oldest entry is dropped when the ring is full, in this same call, which
// is what keeps a post's net storage change at roughly zero.
func Post(cur realm, from, topic, kind, ref, body string) uint64 {
	// Check the realm token before reading an author out of it. There is no
	// test below for this branch and that is not an oversight: an in-package
	// test cannot produce a cur that is not the live frame. Passing the test's
	// own cur without cross() keeps IsCurrent() true and dies later in
	// Previous() with "frame not found" instead. Nothing in this repository
	// exercises the branch, in any of the realms that carry it.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	m := msg.Msg{
		From:  from,
		Topic: topic,
		Kind:  kind,
		Ref:   ref,
		Body:  body,
	}
	if problem := m.Validate(); problem != "" {
		panic(problem)
	}

	caller := cur.Previous().Address()
	sessionAddr, _, _, isSession := runtime.GetSessionInfo()
	if !isSession {
		sessionAddr = ""
	}
	seq++
	seen++
	m.Seq = seq
	m.Height = runtime.ChainHeight()

	log.Push(encode(Entry{Msg: m, Author: caller, Session: sessionAddr}))
	chain.Emit("Posted",
		"seq", strconv.FormatUint(m.Seq, 10),
		"topic", m.Topic,
		"from", m.From,
		"author", caller.String(),
		"session", sessionAddr.String(),
	)
	return m.Seq
}

// Len returns how many messages the ring currently holds.
func Len() int { return log.Len() }

// Seen returns how many messages have ever been posted, including the ones
// the ring has since dropped. Seen minus Len is what a reader missed.
func Seen() int { return seen }

// Latest returns the most recent entries, newest first, at most n of them.
// n <= 0 means every entry the ring still holds.
func Latest(n int) []Entry {
	all := decodeAll(log.Slice())
	// Slice is oldest-first; reverse into newest-first.
	out := make([]Entry, 0, len(all))
	for i := len(all) - 1; i >= 0; i-- {
		if n > 0 && len(out) == n {
			break
		}
		out = append(out, all[i])
	}
	return out
}

// Topic returns the entries on one topic, newest first.
func Topic(topic string) []Entry {
	var out []Entry
	for _, e := range Latest(0) {
		if e.Msg.Topic == topic {
			out = append(out, e)
		}
	}
	return out
}

// Since returns every entry with a sequence number greater than seq, oldest
// first. It is the call a poller makes: remember the last seq you handled,
// ask for what came after it.
//
// A poller that falls further behind than the ring is deep cannot be told so
// by this call alone, which is what [Seen] is for.
func Since(seq uint64) []Entry {
	var out []Entry
	for _, e := range decodeAll(log.Slice()) {
		if e.Msg.Seq > seq {
			out = append(out, e)
		}
	}
	return out
}

// Wire returns every entry after seq in the realm's own encoding, oldest
// first, each one framed by its length so a reader can split them apart.
//
// It exists because [vm/qeval] renders a value for a human, not for a program:
// a []Entry comes back as nested parentheses with quoted fields, and a body
// containing the sequence `" string),(` takes any parser apart. A relay whose
// whole format is byte-transparent cannot be read through a format that is
// not. Decode with [gno.land/p/moul/agents/msg.Unframe], then the same
// package's Unframe twice and Decode once per entry: author, session, message.
//
// Empty when nothing is newer than seq.
func Wire(seq uint64) string {
	var sb strings.Builder
	for _, e := range Since(seq) {
		sb.WriteString(msg.Frame(encode(e)))
	}
	return sb.String()
}

func Render(path string) string {
	req := realmpath.Parse(path)
	if t := req.PathPart(0); t != "" {
		return renderTopic(t)
	}
	return renderIndex()
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Agent Relay\n\n")
	sb.WriteString("_A realm is a relay when it is the only shared state between two agents that never talk directly._\n\n")
	sb.WriteString(ufmt.Sprintf("%d of %d slots used, %d posted in total, %d dropped off the back.\n\n",
		log.Len(), Slots, seen, seen-log.Len()))
	sb.WriteString(renderTable(Latest(0)))
	return sb.String()
}

func renderTopic(topic string) string {
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Agent Relay: %s\n\n", ui.Inline(topic)))
	sb.WriteString(renderTable(Topic(topic)))
	return sb.String()
}

func renderTable(entries []Entry) string {
	t := ui.NewTable("Seq", "Height", "From", "Topic", "Kind", "Body", "Signer")
	for _, e := range entries {
		t.Row(
			strconv.FormatUint(e.Msg.Seq, 10),
			strconv.FormatInt(e.Msg.Height, 10),
			ui.Cell(e.Msg.From),
			ui.Cell(e.Msg.Topic),
			ui.Cell(e.Msg.Kind),
			excerptCell(e.Msg.Body, 72),
			signer(e),
		)
	}
	return t.OrEmpty("_Nothing on the relay yet._")
}

// excerptCell shortens a body for a table cell and escapes it exactly once.
//
// ui.Excerpt cannot be used here: it escapes through ui.Inline before
// returning, so ui.Cell(ui.Excerpt(s)) escapes twice and a hyphen comes out of
// the chain as a backslash, a backslash and a hyphen. v0 shipped that bug and
// rendered "evicting in\\\-call" on mainnet. Cut first, on a rune boundary,
// then escape once with the table-aware escaper.
func excerptCell(s string, width int) string {
	r := []rune(s)
	if len(r) <= width+1 {
		return ui.Cell(s)
	}
	return ui.Cell(string(r[:width])) + ui.Ellipsis
}

// signer shows the session key when there was one, and the account otherwise.
// The session is the identifying half: the account is shared by every session
// its owner mints.
func signer(e Entry) string {
	if e.Session != "" {
		return ui.Addr(e.Session)
	}
	return ui.Addr(e.Author)
}

// encode frames the author ahead of the encoded message, so the ring stays a
// flat []string and both halves are recoverable. The author leads rather than
// trails because a trailing field cannot be found by scanning backwards: a
// message body ending in digits is indistinguishable from a length prefix.
func encode(e Entry) string {
	return msg.Frame(e.Author.String()) + msg.Frame(e.Session.String()) + e.Msg.Encode()
}

func decode(s string) (Entry, bool) {
	author, rest, ok := msg.Unframe(s)
	if !ok {
		return Entry{}, false
	}
	session, rest, ok := msg.Unframe(rest)
	if !ok {
		return Entry{}, false
	}
	m, ok := msg.Decode(rest)
	if !ok {
		return Entry{}, false
	}
	return Entry{Msg: m, Author: address(author), Session: address(session)}, true
}

func decodeAll(raw []string) []Entry {
	out := make([]Entry, 0, len(raw))
	for _, s := range raw {
		if e, ok := decode(s); ok {
			out = append(out, e)
		}
	}
	return out
}

package relay

import (
	"strings"
	"testing"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/agents/msg/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/ringbuffer/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset puts the realm back to its init() state. Realm globals persist for the
// whole test binary and examples run after every Test, so every test that
// writes starts here and ExampleRender builds its own state.
func reset() {
	log = ringbuffer.New(Slots)
	seq = 0
	seen = 0
}

func TestPostAssignsSeqAndAuthor(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	got := Post(cross(cur), "agent-a", "build", "note", "pr/1", "first")

	uassert.Equal(t, uint64(1), got)
	uassert.Equal(t, 1, Len())
	uassert.Equal(t, 1, Seen())

	e := Latest(0)[0]
	uassert.Equal(t, uint64(1), e.Msg.Seq)
	uassert.Equal(t, "agent-a", e.Msg.From)
	uassert.Equal(t, alice.String(), e.Author.String())
}

func TestSeqIsMonotonicAcrossAuthors(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "one")
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "agent-b", "build", "", "", "two")

	all := Latest(0) // newest first
	uassert.Equal(t, uint64(2), all[0].Msg.Seq)
	uassert.Equal(t, bob.String(), all[0].Author.String())
	uassert.Equal(t, uint64(1), all[1].Msg.Seq)
	uassert.Equal(t, alice.String(), all[1].Author.String())
}

func TestRingDropsTheOldestAndSeenKeepsCounting(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < Slots+5; i++ {
		Post(cross(cur), "agent-a", "build", "", "", "body")
	}
	uassert.Equal(t, Slots, Len())
	uassert.Equal(t, Slots+5, Seen())

	// The five oldest fell off the back; the newest is the last one posted.
	all := Latest(0)
	uassert.Equal(t, uint64(Slots+5), all[0].Msg.Seq)
	uassert.Equal(t, uint64(6), all[len(all)-1].Msg.Seq)
}

func TestSinceAndTopicFilter(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "b1")
	Post(cross(cur), "agent-a", "deploy", "", "", "d1")
	Post(cross(cur), "agent-a", "build", "", "", "b2")

	since := Since(1) // oldest first
	uassert.Equal(t, 2, len(since))
	uassert.Equal(t, uint64(2), since[0].Msg.Seq)
	uassert.Equal(t, uint64(3), since[1].Msg.Seq)
	uassert.Equal(t, 0, len(Since(3)))

	build := Topic("build") // newest first
	uassert.Equal(t, 2, len(build))
	uassert.Equal(t, "b2", build[0].Msg.Body)
	uassert.Equal(t, 0, len(Topic("nothing-here")))
}

func TestLatestRespectsN(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < 5; i++ {
		Post(cross(cur), "agent-a", "build", "", "", "body")
	}
	uassert.Equal(t, 2, len(Latest(2)))
	uassert.Equal(t, 5, len(Latest(0)))
	uassert.Equal(t, 5, len(Latest(-1)))
}

func TestPostRejectsInvalidFields(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "empty topic", func() {
		Post(cross(cur), "agent-a", "", "", "", "body")
	})
	uassert.AbortsWithMessage(t, cur, "topic must be lowercase a-z, 0-9, dash or dot", func() {
		Post(cross(cur), "agent-a", "Build", "", "", "body")
	})
	uassert.AbortsWithMessage(t, cur, "empty body", func() {
		Post(cross(cur), "agent-a", "build", "", "", "")
	})
	uassert.Equal(t, 0, Len())
	uassert.Equal(t, 0, Seen())
}

// TestBodySurvivesTheEncoding is the regression test for the framing: a body
// that looks like the encoding, or ends in the digits a length prefix is made
// of, must come back unchanged with its author still attached.
func TestBodySurvivesTheEncoding(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	nasty := []string{
		"ends in 40",
		"3:abc",
		"has\na newline",
		msg.Msg{Seq: 9, Height: 9, From: "x", Topic: "y", Kind: "z", Ref: "w", Body: "v"}.Encode(),
		"| breaks | a | table |",
	}
	for _, body := range nasty {
		Post(cross(cur), "agent-a", "build", "", "", body)
	}
	got := Latest(0) // newest first
	for i, body := range nasty {
		e := got[len(nasty)-1-i]
		uassert.Equal(t, body, e.Msg.Body)
		uassert.Equal(t, alice.String(), e.Author.String())
	}
}

// TestRenderEscapesACallersString pins what guard-untrusted-render exists for:
// a pipe in a body must not open a column in the rendered table.
func TestRenderEscapesACallersString(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "a | b")

	out := Render("")
	uassert.False(t, strings.Contains(out, "| a | b |"),
		"an unescaped pipe opened a column in the rendered table")
}

// TestRenderEscapesABodyExactlyOnce is the regression test for the v0 bug.
// ui.Cell(ui.Excerpt(s)) escaped twice, so a hyphen reached mainnet as
// backslash-backslash-backslash-hyphen. Over-escaping is not a security hole,
// which is exactly why the pipe test above passed while this was broken: a
// doubly escaped pipe is still safe and still wrong.
func TestRenderEscapesABodyExactlyOnce(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "evicting in-call")

	out := Render("")
	uassert.True(t, strings.Contains(out, `evicting in\-call`),
		"a hyphen in a short body should be escaped once")
	uassert.False(t, strings.Contains(out, `in\\-call`),
		"the body was escaped more than once")
}

// TestRenderEscapesALongBodyExactlyOnce covers the other branch of
// excerptCell, where the body is cut before it is escaped.
func TestRenderEscapesALongBodyExactlyOnce(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	long := "evicting in-call"
	for len(long) < 200 {
		long += " and-again"
	}
	Post(cross(cur), "agent-a", "build", "", "", long)

	out := Render("")
	uassert.True(t, strings.Contains(out, `evicting in\-call`),
		"a hyphen in a cut body should be escaped once")
	uassert.False(t, strings.Contains(out, `in\\-call`),
		"the cut body was escaped more than once")
}

// TestPostRecordsNoSessionForAMasterKey pins the empty-session branch. A test
// signs as a plain user realm, never through a session, so isSession is false
// and Session must stay empty rather than inherit the author.
func TestPostRecordsNoSessionForAMasterKey(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "body")

	e := Latest(0)[0]
	uassert.Equal(t, alice.String(), e.Author.String())
	uassert.Equal(t, "", e.Session.String())
}

// TestWireRoundTripsThroughAReader walks the wire format exactly as an
// off-chain reader must: unframe one entry at a time, then unframe the author
// and the session off the front, then decode the message. The bodies are the
// ones that break a qeval parser.
func TestWireRoundTripsThroughAReader(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	bodies := []string{
		`a body with " string),( in it`,
		"ends in 40",
		"has\na newline",
		"| and | pipes |",
	}
	for _, b := range bodies {
		Post(cross(cur), "agent-a", "build", "k", "r", b)
	}

	rest := Wire(0)
	for i, want := range bodies {
		framed, tail, ok := msg.Unframe(rest)
		uassert.True(t, ok, "entry did not unframe")
		rest = tail

		author, r2, ok := msg.Unframe(framed)
		uassert.True(t, ok, "author did not unframe")
		session, r3, ok := msg.Unframe(r2)
		uassert.True(t, ok, "session did not unframe")
		m, ok := msg.Decode(r3)
		uassert.True(t, ok, "message did not decode")

		uassert.Equal(t, want, m.Body)
		uassert.Equal(t, uint64(i+1), m.Seq)
		uassert.Equal(t, alice.String(), author)
		uassert.Equal(t, "", session)
	}
	uassert.Equal(t, "", rest, "the wire had trailing bytes")
}

func TestWireIsEmptyWhenNothingIsNewer(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "one")
	uassert.Equal(t, "", Wire(1))
	uassert.True(t, Wire(0) != "", "Wire(0) should carry the only entry")
}

