package gallery

import "strings"

// doc builds the plain-text target: a document that reads well as-is, rather
// than markdown with the syntax characters deleted.
//
// This is a prototype, deliberately small and deliberately here rather than in
// a p/ package. Porting one realm is not enough to know what the shared
// document model should be; porting the fifth will be. What it already pins is
// the set of rules that make text good instead of merely stripped:
//
//  1. A link prints its text inline and collects the URL into a numbered
//     footnote. Never "[text](url)", which is the single worst thing markdown
//     does to a terminal reader.
//  2. A heading is underlined, not prefixed with '#'.
//  3. Art is emitted verbatim: never wrapped, never escaped, never fenced.
//  4. Prose is wrapped at a fixed width; art and fields are not.
type doc struct {
	b     strings.Builder
	links []string
}

// width is where prose wraps. 72 leaves room for a quoting prefix in an email
// or a diff without re-wrapping.
const width = 72

func (d *doc) H1(s string) {
	d.blank()
	d.b.WriteString(s + "\n" + strings.Repeat("=", runeLen(s)) + "\n")
}

func (d *doc) H2(s string) {
	d.blank()
	d.b.WriteString(s + "\n" + strings.Repeat("-", runeLen(s)) + "\n")
}

func (d *doc) Para(s string) {
	if s == "" {
		return
	}
	d.blank()
	d.b.WriteString(wrap(s, width) + "\n")
}

func (d *doc) Item(s string) {
	d.b.WriteString("  - " + s + "\n")
}

// Table writes columns padded to their widest cell, under a rule. An unpadded
// pipe table is the other thing markdown does to a terminal reader that no
// amount of character-stripping fixes: the columns stop lining up and the table
// stops being a table.
//
// Cells are laid out by rune count, not byte count, so a box-drawing glyph or
// an accent does not shift the column.
func (d *doc) Table(headers []string, rows [][]string) {
	if len(headers) == 0 {
		return
	}
	w := make([]int, len(headers))
	for i, h := range headers {
		w[i] = runeLen(h)
	}
	for _, r := range rows {
		for i, c := range r {
			if i < len(w) && runeLen(c) > w[i] {
				w[i] = runeLen(c)
			}
		}
	}

	d.blank()
	d.b.WriteString("  " + joinPadded(headers, w) + "\n")

	rule := make([]string, len(headers))
	for i := range rule {
		rule[i] = strings.Repeat("-", w[i])
	}
	d.b.WriteString("  " + joinPadded(rule, w) + "\n")

	for _, r := range rows {
		d.b.WriteString("  " + joinPadded(r, w) + "\n")
	}
}

// joinPadded pads every cell but the last, which would only add trailing space.
func joinPadded(cells []string, w []int) string {
	var b strings.Builder
	for i, c := range cells {
		if i > 0 {
			b.WriteString("  ")
		}
		b.WriteString(c)
		if i < len(cells)-1 && i < len(w) {
			b.WriteString(strings.Repeat(" ", w[i]-runeLen(c)))
		}
	}
	return b.String()
}

func (d *doc) Field(k, v string) {
	d.b.WriteString("  " + k + ": " + v + "\n")
}

// Art writes a block verbatim. No fence, no indent, no escaping: a consumer
// that asked for text asked for the picture as it is.
func (d *doc) Art(s string) {
	d.blank()
	d.b.WriteString(s + "\n")
}

// Link prints the text inline and defers the URL to the footnote block.
func (d *doc) Link(text, url string) {
	d.links = append(d.links, url)
	d.b.WriteString("  " + text + " [" + itoa(len(d.links)) + "]\n")
}

func (d *doc) String() string {
	out := d.b.String()
	if len(d.links) == 0 {
		return out
	}
	var b strings.Builder
	b.WriteString(out)
	b.WriteString("\nLinks:\n")
	for i, u := range d.links {
		b.WriteString("  [" + itoa(i+1) + "] " + u + "\n")
	}
	return b.String()
}

// blank writes a separating newline unless the document is empty or already
// ends in one, so no block has to know what came before it.
func (d *doc) blank() {
	s := d.b.String()
	if s == "" || strings.HasSuffix(s, "\n\n") {
		return
	}
	d.b.WriteString("\n")
}

// wrap breaks on spaces at w runes. A word longer than w is left alone rather
// than cut: a URL or a realm path is worse broken than wide.
func wrap(s string, w int) string {
	var out strings.Builder
	line := 0
	for i, word := range strings.Fields(s) {
		n := runeLen(word)
		switch {
		case i == 0:
			out.WriteString(word)
			line = n
		case line+1+n > w:
			out.WriteString("\n" + word)
			line = n
		default:
			out.WriteString(" " + word)
			line += 1 + n
		}
	}
	return out.String()
}

func runeLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

package vesting

import (
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/realmpath/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/vesting/v0"
)

// Render serves three shapes:
//
//	/r/moul/vesting/v0                     the seeded schedules
//	/r/moul/vesting/v0:g1...               one address, its declared schedule
//	/r/moul/vesting/v0:g1...?o=&s=&e=&d=   one address, a schedule you supply
//
// The query form stores nothing. It exists so an address that has not declared
// anything can still get a real answer: paste the schedule out of
// `gnokey query auth/accounts/<addr>` and the balance is still read from chain.
func Render(path string) string {
	req := realmpath.Parse(path)
	target := strings.TrimSpace(req.PathPart(0))

	if target == "" {
		curPage = 1
		if p, err := strconv.Atoi(req.Query.Get("page")); err == nil && p > 1 {
			curPage = p
		}
		return renderIndex()
	}
	if !isAddr(target) {
		return header() + ui.Empty(md.InlineCode(target)+" is not a gno.land address.") +
			"\n" + lookupForm()
	}
	addr := address(target)

	// An ad-hoc schedule in the query beats a declared one, and is labelled as
	// coming from the caller.
	if raw := req.Query.Get("o"); raw != "" {
		sch, err := scheduleFromQuery(req)
		if err != "" {
			return header() + ui.Empty(err) + "\n" + lookupForm()
		}
		return header() + renderAccount(addr, sch, sourceQuery, "") + "\n" + lookupForm()
	}

	if e, ok := lookup(addr); ok {
		src := sourceDeclared
		if e.seeded {
			src = sourceSeeded
		}
		return header() + renderAccount(addr, e.schedule, src, e.label) + "\n" + lookupForm()
	}
	return header() + renderUnknown(addr) + "\n" + lookupForm()
}

// Where a schedule came from. This is the distinction the whole page turns on,
// so it is a value and not a boolean buried in a branch.
type source int

const (
	sourceSeeded   source = iota // a source constant in this realm
	sourceDeclared               // written by the address itself
	sourceQuery                  // typed into the URL by whoever is looking
	sourceNone                   // there is none
)

func (s source) label() string {
	switch s {
	case sourceSeeded:
		return "seeded in this realm's source"
	case sourceDeclared:
		return "declared by the address itself"
	case sourceQuery:
		return "supplied in the URL by you"
	}
	return "unknown"
}

func header() string {
	return "# Vesting\n\n" +
		"How much of an account's balance can actually move right now.\n\n"
}

// pageSize bounds the declared table. vm/qrender runs on a gas meter and a
// large return value fails with OutOfGasError{Descriptor:"CPUCycles"} rather
// than answering slowly, so an unbounded index is a page that eventually stops
// rendering for everyone. Anyone may Declare, so "eventually" is somebody
// else's choice unless it is capped here.
const pageSize = 25

func renderIndex() string {
	var b strings.Builder
	b.WriteString(header())

	// Seeded rows always render in full: there are as many as this realm's
	// source says and no caller can add one.
	t := ui.NewTable("account", "balance", "spendable", "locked", "vested")
	seedIndex.Iterate("", "", func(key string, v any) bool {
		t.Row(rowFor(address(key), v.(*entry))...)
		return false
	})
	b.WriteString(t.String())

	if n := declared.Size(); n > 0 {
		b.WriteString("\n## Declared\n\n")
		b.WriteString(ufmt.Sprintf("%d address(es) have put their own schedule on file.\n\n", n))

		d := ui.NewTable("account", "balance", "spendable", "locked", "vested")
		declared.IterateByOffset(pageOffset(curPage)*pageSize, pageSize, func(key string, v any) bool {
			d.Row(rowFor(address(key), v.(*entry))...)
			return false
		})
		b.WriteString(d.String())
		b.WriteString("\n")
		b.WriteString(pager(n))
	}

	b.WriteString("\n")
	b.WriteString(lookupForm())
	b.WriteString("\n## What is real here, and what is not\n\n")
	b.WriteString("| figure | where it comes from |\n|---|---|\n")
	b.WriteString("| balance | read from the chain every render, `banker.GetCoins` |\n")
	b.WriteString("| the clock | read from the chain every render, the block time |\n")
	b.WriteString("| the schedule | **supplied**, because no realm can read one |\n\n")
	b.WriteString("A realm's whole view of an account is its TOTAL balance, locked coins ")
	b.WriteString("included. `std.VestingSchedule` lives in the auth store and no native ")
	b.WriteString("reaches it, so the curve has to be told to this realm rather than found.\n\n")
	b.WriteString("That is safe to cache because a schedule can never change: it is set ")
	b.WriteString("once, at genesis, and no message type creates or modifies one. A ")
	b.WriteString("schedule declared correctly today is correct forever.\n")
	return b.String()
}

// curPage is the page renderIndex is currently building, set by Render before
// it delegates. A parameter would be cleaner; Render's signature is fixed by
// the VM, and threading it through every helper for one value is worse.
var curPage = 1

func pageOffset(page int) int {
	if page < 1 {
		return 0
	}
	return page - 1
}

// rowFor builds one table row. Shared so the seeded and declared tables cannot
// drift apart in what they show.
func rowFor(addr address, e *entry) []string {
	bal := balanceOf(addr)
	n := now()
	name := ui.AddrText(addr)
	if e.label != "" {
		name = ui.Inline(e.label) + " " + ui.Addr(addr)
	}
	return []string{
		name,
		gnot(bal),
		gnot(e.schedule.Spendable(bal, n)),
		gnot(lockedCapped(e.schedule, bal, n)),
		permille(e.schedule.PermilleVested(n)),
	}
}

// pager renders the page links, and nothing at all when everything fits.
func pager(total int) string {
	pages := (total + pageSize - 1) / pageSize
	if pages <= 1 {
		return ""
	}
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("Page %d of %d.", curPage, pages))
	if curPage > 1 {
		b.WriteString(ufmt.Sprintf(" [previous](%s?page=%d)", Link, curPage-1))
	}
	if curPage < pages {
		b.WriteString(ufmt.Sprintf(" [next](%s?page=%d)", Link, curPage+1))
	}
	b.WriteString("\n")
	return b.String()
}

func renderAccount(addr address, s vesting.Schedule, src source, label string) string {
	var b strings.Builder
	n := now()
	bal := balanceOf(addr)

	b.WriteString("## ")
	if label != "" {
		b.WriteString(ui.Inline(label))
		b.WriteString(" ")
	}
	b.WriteString(ui.AddrText(addr))
	b.WriteString("\n\n")

	if s.IsZero() {
		b.WriteString("No vesting schedule, so the whole balance moves.\n\n")
		b.WriteString("| | |\n|---|---|\n")
		b.WriteString("| balance | **" + gnot(bal) + "** |\n")
		b.WriteString("| spendable | **" + gnot(bal) + "** |\n\n")
		b.WriteString(sourceNote(src))
		return b.String()
	}

	locked := lockedCapped(s, bal, n)
	t := ui.NewTable("", "")
	t.Row("balance", "**"+gnot(bal)+"**")
	t.Row("spendable now", "**"+gnot(s.Spendable(bal, n))+"**")
	t.Row("locked now", gnot(locked))
	t.Row("granted", gnot(s.Original))
	t.Row("vested", gnot(s.Vested(n))+" ("+permille(s.PermilleVested(n))+")")
	t.Row("still to vest", gnot(s.Locked(n)))
	t.Row("curve", s.Type.String())
	t.Row("term", tstamp(s.Start)+" to "+tstamp(s.End))
	t.Row("finishes in", duration(s.RemainingSeconds(n)))
	b.WriteString(t.String())
	b.WriteString("\n")

	if s.Locked(n) > bal {
		b.WriteString("\n> This account holds less than its schedule still locks, so ")
		b.WriteString("nothing moves at all. That happens when coins were spent while ")
		b.WriteString("they were free and the grant has since outrun the balance.\n")
	}

	b.WriteString("\n")
	b.WriteString(sourceNote(src))
	return b.String()
}

func renderUnknown(addr address) string {
	var b strings.Builder
	bal := balanceOf(addr)
	b.WriteString("## ")
	b.WriteString(ui.AddrText(addr))
	b.WriteString("\n\nNo schedule on file for this address.\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| balance | **" + gnot(bal) + "** |\n")
	b.WriteString("| spendable | unknown |\n\n")
	b.WriteString("The balance above is real. How much of it moves is not knowable from ")
	b.WriteString("inside a realm. Read the schedule off the chain:\n\n")
	b.WriteString("```\ngnokey query auth/accounts/" + addr.String() +
		" -remote https://rpc.gno.land:443\n```\n\n")
	b.WriteString("then either append it to this URL as `?o=<original_vesting>&s=<start_time>")
	b.WriteString("&e=<end_time>` (add `&d=1` for a `delayed` schedule), or, if this address ")
	b.WriteString("is yours, put it on file so the link works for everyone:\n\n")
	b.WriteString(ui.Action("Declare this schedule", "Declare",
		"original", "", "start", "", "end", "", "delayed", "false"))
	b.WriteString("\n")
	return b.String()
}

func sourceNote(src source) string {
	s := "Balance and clock are read from the chain. The schedule is " + src.label() + "."
	if src == sourceQuery {
		s += " Nothing was stored."
	}
	if src == sourceDeclared {
		s += " Only that address can write or remove it, so it can misdescribe nobody else."
	}
	return "> " + s + "\n"
}

func lookupForm() string {
	return "## Check another address\n\n" +
		"Append it to the path: `" + Link + ":g1…`\n\n" +
		"| | |\n|---|---|\n" +
		"| put your own schedule on file | " +
		ui.Action("Declare", "Declare", "original", "", "start", "", "end", "", "delayed", "false") +
		" |\n| take it off again | " + ui.Action("Forget", "Forget") + " |\n"
}

// scheduleFromQuery reads a one-off schedule out of the URL. It returns a
// human-readable reason rather than an error value, because every caller turns
// it straight into page text.
func scheduleFromQuery(req *realmpath.Request) (vesting.Schedule, string) {
	o, err := strconv.ParseInt(req.Query.Get("o"), 10, 64)
	if err != nil {
		return vesting.Schedule{}, "`o` (the original vesting amount, in ugnot) is not a number."
	}
	s, err := strconv.ParseInt(orZero(req.Query.Get("s")), 10, 64)
	if err != nil {
		return vesting.Schedule{}, "`s` (the start time, unix seconds) is not a number."
	}
	e, err := strconv.ParseInt(orZero(req.Query.Get("e")), 10, 64)
	if err != nil {
		return vesting.Schedule{}, "`e` (the end time, unix seconds) is not a number."
	}
	typ := vesting.Continuous
	if d := req.Query.Get("d"); d == "1" || d == "true" {
		typ = vesting.Delayed
	}
	sch, verr := vesting.New(o, s, e, typ)
	if verr != nil {
		return vesting.Schedule{}, "That is not a valid schedule: " + verr.Error() + "."
	}
	return sch, ""
}

func orZero(s string) string {
	if s == "" {
		return "0"
	}
	return s
}

// lockedCapped is what the account cannot move, which is never more than it
// holds. The schedule alone can say otherwise once coins have been spent.
func lockedCapped(s vesting.Schedule, balance, n int64) int64 {
	l := s.Locked(n)
	if l > balance {
		return balance
	}
	if l < 0 {
		return 0
	}
	return l
}

// tstamp renders a unix second as a plain UTC date, which is all a two-year
// term needs. gno has no time formatting worth the dependency here.
func tstamp(sec int64) string {
	y, m, d := civil(sec / 86400)
	return ufmtDate(y, m, d)
}

// civil converts a day count since 1970-01-01 to a calendar date, by Howard
// Hinnant's civil_from_days. Integer only, no time package, no locale.
func civil(z int64) (year int64, month int64, day int64) {
	z += 719468
	era := z / 146097
	if z < 0 {
		era = (z - 146096) / 146097
	}
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	y := yoe + era*400
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	d := doy - (153*mp+2)/5 + 1
	m := mp + 3
	if mp >= 10 {
		m = mp - 9
	}
	if m <= 2 {
		y++
	}
	return y, m, d
}

func ufmtDate(y, m, d int64) string {
	return strconv.FormatInt(y, 10) + "-" + pad2(m) + "-" + pad2(d)
}

func pad2(n int64) string {
	s := strconv.FormatInt(n, 10)
	if len(s) < 2 {
		return "0" + s
	}
	return s
}

package vesting

// ExampleRender pins the index.
//
// reset() first, deliberately: an Example runs AFTER every Test in the package
// and sees the rows they declared, so without it this output depends on test
// order. The block time inside a gno test is fixed at 2009-02-13, before the
// real mainnet term starts, so the seeded rows render at 0% vested with the
// whole grant locked. That is a legitimate point on the curve and a stable one.
//
// With no declarations there is no Declared section and no pager, which is the
// shape the page has on a fresh deploy.
func ExampleRender() {
	reset()
	print(Render(""))
	// Output:
	// # Vesting
	//
	// How much of an account's balance can actually move right now.
	//
	// | account | balance | spendable | locked | vested |
	// | --- | --- | --- | --- | --- |
	// | moul `g1manfre…dlf5` | 0.000000 GNOT | 0.000000 GNOT | 0.000000 GNOT | 0.0% |
	// | investors\-vesting multisig `g1x7tm26…gax3` | 0.000000 GNOT | 0.000000 GNOT | 0.000000 GNOT | 0.0% |
	//
	// ## Check another address
	//
	// Append it to the path: `/r/moul/vesting/v0:g1…`
	//
	// | | |
	// |---|---|
	// | put your own schedule on file | [Declare](/r/moul/vesting/v0$help&func=Declare&delayed=false&end=&original=&start=) |
	// | take it off again | [Forget](/r/moul/vesting/v0$help&func=Forget) |
	//
	// ## What is real here, and what is not
	//
	// | figure | where it comes from |
	// |---|---|
	// | balance | read from the chain every render, `banker.GetCoins` |
	// | the clock | read from the chain every render, the block time |
	// | the schedule | **supplied**, because no realm can read one |
	//
	// A realm's whole view of an account is its TOTAL balance, locked coins included. `std.VestingSchedule` lives in the auth store and no native reaches it, so the curve has to be told to this realm rather than found.
	//
	// That is safe to cache because a schedule can never change: it is set once, at genesis, and no message type creates or modifies one. A schedule declared correctly today is correct forever.
}

// Realm vesting answers one question for a gno.land account: of the coins it
// holds, how many can actually move right now.
//
// # Read this before you trust a number here
//
// A realm CANNOT read an account's vesting schedule. The VM's whole view of an
// account is banker.GetCoins, which returns the TOTAL balance with the locked
// part included, and no native exposes std.VestingSchedule. So this realm
// reads two things from the chain and is told the third:
//
//	balance     read from the chain, banker.GetCoins   always true
//	now         read from the chain, block time        always true
//	schedule    supplied, see below                    only as good as its source
//
// Every rendered figure says which of the two it rests on. Nothing here is
// presented as verified when it is not.
//
// # Where a schedule comes from
//
// Either the query string, for a one-off calculation that stores nothing, or
// the registry. [Declare] writes a schedule for the CALLER'S OWN address and
// no other, which is the whole trust model: an address can only misdescribe
// itself, and a wrong entry misleads nobody but its author.
//
// Anyone can read their real schedule in one command and declare it:
//
//	gnokey query auth/accounts/g1youraddress -remote https://rpc.gno.land:443
//
// # Why the schedule can be cached at all
//
// Because it can never change. std.SetVesting has exactly one caller in the
// monorepo, gno.land/pkg/gnoland/app.go, during genesis balance loading, and
// no message type creates or modifies a schedule. A schedule declared once is
// correct forever, which is what makes a registry honest rather than stale.
package vesting

import (
	"strconv"
	"strings"
	"time"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/vesting/v0"
)

const (
	// Path is this realm's package path.
	Path = "gno.land/r/moul/vesting/v0"
	// Link is Path as a gnoweb route.
	Link = "/r/moul/vesting/v0"
	// Denom is the only coin this realm reports on.
	Denom = "ugnot"
)

// seeded are the schedules this realm ships with, restored by init() after
// every redeploy.
//
// They are source constants and not registry rows on purpose: the realm is
// private = true, so a redeploy wipes realm state, and the one schedule the
// page exists to show should not need a transaction to come back. Each is
// copied from the genesis allocation sheet that built mainnet, which is the
// public, pinned input named in misc/deployments/mainnet.gno.land/gen-genesis.sh.
//
// An address is seeded here only when its LABEL is public too. The addresses
// are all on chain, but naming one is a claim about who holds it, and this
// realm is public and permanent. gen-genesis.sh names the investors-vesting
// multisig outright, so that one ships; the treasuries and the other buckets
// are identified nowhere public, so they do not, and the URL form serves
// anyone who wants to check them anyway.
var seeded = []struct {
	addr     address
	label    string
	original int64
	start    int64
	end      int64
	delayed  bool
}{
	{
		addr:     "g1manfred47kzduec920z88wfr64ylksmdcedlf5",
		label:    "moul",
		original: 106560000000,
		start:    1789225200,
		end:      1852383600,
	},
	{
		// "including the investors-vesting multisig
		// g1x7tm26g9wj84cmg3cs74uwf3g9lqj4mjp6gax3, 150,000,000 GNOT total,
		// 144,000,000 of it vesting continuously" -- gen-genesis.sh, and the
		// sheet row it describes:
		//   g1x7tm26…=150000000000000ugnot;vesting=144000000000000ugnot,1789225200,1852383600
		addr:     "g1x7tm26g9wj84cmg3cs74uwf3g9lqj4mjp6gax3",
		label:    "investors-vesting multisig",
		original: 144000000000000,
		start:    1789225200,
		end:      1852383600,
	},
}

// declared maps an address to the schedule that address declared for itself.
// Seeded schedules are NOT in here: they are read from the seeded slice, which
// is what lets the index render them in full while paging everything else.
// Anyone may Declare, so this tree is unbounded and the page that shows it
// cannot be.
var declared avl.Tree

// seedIndex resolves a seeded address without walking the slice twice.
var seedIndex avl.Tree

// entry is one row of the registry.
type entry struct {
	schedule vesting.Schedule
	label    string // non-empty only for a seeded row
	seeded   bool
	at       int64 // block height the row was written at; 0 for a seeded row
}

func init() { reset() }

// reset restores the registry to exactly what the source declares. init() is
// its only caller on chain; a test calls it to render a page that does not
// depend on what the test before it wrote, since an Example runs after every
// Test in the package and sees the state they left.
func reset() {
	declared = avl.Tree{}
	seedIndex = avl.Tree{}
	for _, s := range seeded {
		typ := vesting.Continuous
		if s.delayed {
			typ = vesting.Delayed
		}
		sch, err := vesting.New(s.original, s.start, s.end, typ)
		if err != nil {
			panic("vesting: seeded schedule for " + s.label + ": " + err.Error())
		}
		seedIndex.Set(s.addr.String(), &entry{schedule: sch, label: s.label, seeded: true})
	}
}

// Declare records the caller's own vesting schedule, replacing any previous
// one. It cannot write a row for anybody else, which is what keeps the
// registry honest without the realm being able to verify a thing.
//
// Pass original = 0 to declare that the address has no schedule at all.
func Declare(cur realm, original, start, end int64, delayed bool) {
	typ := vesting.Continuous
	if delayed {
		typ = vesting.Delayed
	}
	sch, err := vesting.New(original, start, end, typ)
	if err != nil {
		panic(err.Error())
	}
	who := unsafe.PreviousRealm().Address()
	if e, ok := lookup(who); ok && e.seeded {
		panic("vesting: " + who.String() + " is seeded in the source; edit the realm instead")
	}
	declared.Set(who.String(), &entry{schedule: sch, at: chainHeight()})
	chain.Emit("declared", "addr", who.String(),
		"original", strconv.FormatInt(original, 10),
		"start", strconv.FormatInt(start, 10),
		"end", strconv.FormatInt(end, 10),
		"type", typ.String())
}

// Forget removes the caller's own declaration.
func Forget(cur realm) {
	who := unsafe.PreviousRealm().Address()
	e, ok := lookup(who)
	if !ok {
		panic("vesting: nothing declared for " + who.String())
	}
	if e.seeded {
		panic("vesting: " + who.String() + " is seeded in the source; edit the realm instead")
	}
	declared.Remove(who.String())
	chain.Emit("forgot", "addr", who.String())
}

// Count returns how many schedules addresses have declared for themselves.
// Seeded schedules are not included; SeededCount reports those.
func Count() int { return declared.Size() }

// SeededCount returns how many schedules this realm ships in its source.
func SeededCount() int { return seedIndex.Size() }

// ScheduleOf returns the declared schedule for addr, and whether there is one.
func ScheduleOf(addr address) (original, start, end int64, delayed, ok bool) {
	e, found := lookup(addr)
	if !found {
		return 0, 0, 0, false, false
	}
	s := e.schedule
	return s.Original, s.Start, s.End, s.Type == vesting.Delayed, true
}

// SpendableOf returns what addr can move right now, and whether the answer
// rests on a declared schedule. With ok false the figure is the whole balance,
// which is correct only if the address really has no schedule.
func SpendableOf(addr address) (spendable int64, ok bool) {
	bal := balanceOf(addr)
	e, found := lookup(addr)
	if !found {
		return bal, false
	}
	return e.schedule.Spendable(bal, now()), true
}

// LockedOf returns what addr cannot move right now, and whether the answer
// rests on a declared schedule.
func LockedOf(addr address) (locked int64, ok bool) {
	e, found := lookup(addr)
	if !found {
		return 0, false
	}
	bal := balanceOf(addr)
	l := e.schedule.Locked(now())
	if l > bal {
		l = bal // cannot lock more than is there
	}
	return l, true
}

// lookup reads a row, seeded first so a seeded address can never be shadowed.
// avl's Get returns ONE value and nil for a miss, unlike Remove which returns
// two; that asymmetry is a documented gno-vs-Go trap.
func lookup(addr address) (*entry, bool) {
	if v := seedIndex.Get(addr.String()); v != nil {
		return v.(*entry), true
	}
	v := declared.Get(addr.String())
	if v == nil {
		return nil, false
	}
	return v.(*entry), true
}

// balanceOf reads the address's TOTAL ugnot, locked included. That is what
// banker.GetCoins reports and the only balance figure a realm can obtain.
// A readonly banker takes no realm, so this works from inside Render.
func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoins(addr).AmountOf(Denom)
}

// gnot renders a ugnot amount as GNOT with six decimals and no float.
func gnot(u int64) string {
	neg := u < 0
	if neg {
		u = -u
	}
	whole, frac := u/1_000_000, u%1_000_000
	s := ufmt.Sprintf("%d.%s", whole, pad6(frac))
	if neg {
		s = "-" + s
	}
	return s + " GNOT"
}

// pad6 left-pads to six digits. ufmt has no width flags, so this is by hand.
func pad6(n int64) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

// permille renders tenths of a percent as a percentage with one decimal.
func permille(p int64) string {
	return ufmt.Sprintf("%d.%d%%", p/10, p%10)
}

// duration renders a span of seconds as days and hours, which is the only
// resolution worth reading on a two-year schedule.
func duration(sec int64) string {
	if sec <= 0 {
		return "complete"
	}
	d, h := sec/86400, (sec%86400)/3600
	var b strings.Builder
	if d > 0 {
		b.WriteString(strconv.FormatInt(d, 10))
		b.WriteString("d ")
	}
	b.WriteString(strconv.FormatInt(h, 10))
	b.WriteString("h")
	return b.String()
}

// isAddr is a cheap shape check, so a typo renders as "not an address" rather
// than as an account with a zero balance.
func isAddr(s string) bool {
	if len(s) != 40 || !strings.HasPrefix(s, "g1") {
		return false
	}
	for _, r := range s {
		if !(r >= 'a' && r <= 'z') && !(r >= '0' && r <= '9') {
			return false
		}
	}
	return true
}

// now is the chain's own clock, in unix seconds. time.Now() in a realm returns
// the BLOCK time, not a wall clock, which is exactly the value the ante
// handler compares a vesting schedule against.
func now() int64 { return time.Now().Unix() }

func chainHeight() int64 { return runtime.ChainHeight() }

