// TestRenderShapes walks the three routes the page serves and checks each one
// names its source, which is the promise the whole realm makes.
func TestRenderShapes(t *testing.T) {
	index := Render("")
	uassert.True(t, strings.Contains(index, "# Vesting"), "index has no title")
	uassert.True(t, strings.Contains(index, "no realm can read one"),
		"index does not say the schedule is supplied")

	seeded := Render(moul.String())
	uassert.True(t, strings.Contains(seeded, "seeded in this realm's source"),
		"a seeded row does not say where it came from")
	uassert.True(t, strings.Contains(seeded, "spendable now"))

	query := Render(moul.String() + "?o=1000000&s=100&e=200")
	uassert.True(t, strings.Contains(query, "supplied in the URL by you"),
		"a query schedule does not say it was supplied")
	uassert.True(t, strings.Contains(query, "Nothing was stored."))

	unknown := Render(testutils.TestAddress("nobody").String())
	uassert.True(t, strings.Contains(unknown, "No schedule on file"))
	uassert.True(t, strings.Contains(unknown, "gnokey query auth/accounts/"),
		"the unknown page does not say how to find the schedule")

	bad := Render("not-an-address")
	uassert.True(t, strings.Contains(bad, "is not a gno.land address"))
}

// TestRenderEscapesWhatTheCallerTyped: the path is attacker-controlled and a
// live realm can never be patched, so the escaping is checked before deploy.
func TestRenderEscapesWhatTheCallerTyped(t *testing.T) {
	out := Render("[x](/r/evil)")
	uassert.False(t, strings.Contains(out, "[x](/r/evil)"),
		"a markdown link typed into the path reached the page unescaped")
}

// The not-an-address line puts the caller's text in a code span. Markdown
// escapes do not apply inside one, so an escaper there is not merely useless,
// its backslashes reach the reader, and an escaped backtick still CLOSES the
// span. Reverting render.gno:35 to the hand-rolled backticks makes both halves
// of this fail.
func TestNotAnAddressPutsThePathInACodeSpanWithoutEscapes(t *testing.T) {
	out := Render("gno.land_x-y")
	uassert.True(t, strings.Contains(out, "`gno.land_x-y`"),
		"the path is not shown verbatim in a code span")
	uassert.False(t, strings.Contains(out, `gno\.land`),
		"an inline escaper ran inside a code span, so its backslashes reach the reader")

	// A backtick in the path must not end the span early and pull the realm's
	// own sentence out of it. The fence has to outscan the content, so a single
	// internal backtick means a DOUBLE backtick fence.
	out = Render("a`b")
	uassert.True(t, strings.Contains(out, "``a`b``"),
		"the fence does not outscan the caller's backtick, so the span closes early")
	uassert.True(t, strings.Contains(out, "is not a gno.land address."),
		"the sentence did not survive a backtick in the path")
}

// TestRenderQueryRejectsGarbage keeps a typo readable instead of rendering a
// schedule of zeroes as though it were real.
func TestRenderQueryRejectsGarbage(t *testing.T) {
	out := Render(moul.String() + "?o=abc")
	uassert.True(t, strings.Contains(out, "is not a number"))

	out = Render(moul.String() + "?o=100&s=200&e=100")
	uassert.True(t, strings.Contains(out, "not a valid schedule"))
}

// TestChainHeightIsReadable guards the one call that would make Declare
// non-deterministic if it were wrong.
func TestChainHeightIsReadable(t *testing.T) {
	uassert.Equal(t, runtime.ChainHeight(), chainHeight())
}

// TestIndexIsBounded is the defect this realm shipped with: renderIndex
// iterated EVERY registry row, and Declare is open to anyone, so the front
// page grew without limit until it exceeded the query gas ceiling and stopped
// rendering for everybody.
//
// vm/qrender runs on a gas meter. A realm that returns a large string fails
// with OutOfGasError{Descriptor:"CPUCycles"} rather than answering slowly, and
// the safe budget is tens of KB. A row is ~120 bytes, so a few hundred
// declarations was enough. The realm is private = true, so the only repair
// would have been a redeploy, which wipes every declaration and re-charges the
// whole storage deposit.
func TestIndexIsBounded(cur realm, t *testing.T) {
	reset()
	for i := 0; i < 400; i++ {
		testing.SetRealm(testing.NewUserRealm(testutils.TestAddress(ufmt.Sprintf("spam%d", i))))
		Declare(cross(cur), 1000, 100, 200, false)
	}
	uassert.Equal(t, 400, Count(), "the registry should hold every declaration")

	out := Render("")
	uassert.True(t, len(out) < 12000,
		ufmt.Sprintf("the index rendered %d bytes for 401 rows; it must page", len(out)))

	// Paging still has to reach them, so page 2 differs from page 1.
	uassert.True(t, Render("?page=2") != out, "?page=2 rendered the same page as page 1")
	reset()
}

// Realm aaabbb is ONE AMM pair, AAA/BBB, and nothing else.
//
// This is the whole instance half of the instance-per-realm pattern, and it is
// meant to be read in full in one screen: two configuration constants, an init
// that builds the pair and announces it to the registry, and one-line
// re-exports that forward the realm's own `cur` into the shared logic in
// p/moul/x/pair/v0. Every instance in the ecosystem is byte-identical to this
// file except for the two constants, which is what makes verifying an
// unknown instance a two-line diff.
//
// The re-exports cannot be factored away: MsgCall addresses a realm path and a
// function name, so anything a user calls has to be declared here.
//
// State and funds belong to THIS realm: the pair struct is its variable, the
// tokens sit at its own package address, and its creator paid its storage
// deposit. A bug in one instance cannot touch another.
//
// Pattern, and why an AMM is the contested case for it: see the README of
// gno.land/p/moul/x/pair/v0.
package aaabbb

import (
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/pair/v0"
	"gno.land/r/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/pairreg/v0"
	"gno.land/r/nt/grc20reg/v0"

	// Only because both tokens live in this same repository: the blank imports
	// force their init (and therefore their grc20reg registration) to run
	// before this one in a test binary. An instance deployed on chain against
	// already-deployed tokens does not need them.
	_ "gno.land/r/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/pairs/aaa/v0"
	_ "gno.land/r/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/pairs/bbb/v0"
)

// The only two lines that differ between two instances.
const (
	keyA = "gno.land/r/moul/x/pairs/aaa/v0.AAA"
	keyB = "gno.land/r/moul/x/pairs/bbb/v0.BBB"
)

var p *pair.Pair

func init(cur realm) {
	p = pair.New(keyA, keyB, grc20reg.MustGet(keyA), grc20reg.MustGet(keyB))
	pairreg.Register(cross(cur), p)
}

func AddLiquidity(cur realm, maxA, maxB int64) int64 { return p.AddLiquidity(0, cur, maxA, maxB) }

func RemoveLiquidity(cur realm, shares int64) (int64, int64) {
	return p.RemoveLiquidity(0, cur, shares)
}

func Swap(cur realm, keyIn string, amountIn, minOut int64) int64 {
	return p.Swap(0, cur, keyIn, amountIn, minOut)
}

func Quote(keyIn string, amountIn int64) int64 { return p.Quote(keyIn, amountIn) }
func Reserves() (int64, int64)                 { return p.Reserves() }
func SharesOf(owner address) int64             { return p.SharesOf(owner) }
func TotalShares() int64                       { return p.TotalShares() }
func Keys() (string, string)                   { return p.Keys() }
func Render(path string) string                { return p.Render(path) }

