// Package bencodedemo is a small gnoweb demo of the bencode codec provided by
// the [p/moul/x/daily/bencode](/p/moul/x/daily/bencode/v0) library: the four
// types, the round trip that makes an infohash reproducible, and the
// non-canonical inputs the decoder refuses instead of tidying up.
//
// It contains no codec logic of its own. Stateless, so Render is
// deterministic: every figure below is computed from the fixed tables at the
// top of this file, never from chain state.
package bencodedemo

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/bencode/v0"
)

// samples are valid, canonical encodings, one per type plus the composites.
var samples = []string{
	"i42e",
	"i-7e",
	"4:spam",
	"0:",
	"li1ei2ei3ee",
	"d3:cow3:moo4:spam4:eggse",
}

// torrent is the shape the format exists for: a tracker announce beside an
// info dictionary whose re-encoding is what gets hashed.
const torrent = "d8:announce21:udp://tracker.example4:infod6:lengthi262144e4:name8:disk.img12:piece lengthi16384eee"

const backLink = "[back to the demo](/r/moul/x/daily/bencodedemo/v0)\n"

// MaxInput bounds what this page will decode. The library accepts up to
// bencode.MaxLen bytes, but a Render runs under the chain's query gas meter
// and gnoweb does not bound a render argument, so the page stops well short of
// the library's own limit. 512 bytes is more than anyone pastes by hand.
const MaxInput = 512

// rejected are inputs a sloppy decoder accepts and silently rewrites. Each one
// would change the digest of whatever contained it.
var rejected = []struct {
	in  string
	why string
}{
	{"i007e", "leading zeros in an integer"},
	{"i-0e", "negative zero"},
	{"03:abc", "leading zeros in a string length"},
	{"d4:spam4:eggs3:cow3:mooe", "dictionary keys out of order"},
	{"d3:cow3:moo3:cow3:mooe", "duplicate dictionary key"},
	{"i1ei2e", "a second value after the first"},
}

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/")        -> the types, the round trip, the refusals
//	Render("/<bencoded value>")     -> decode that input and show the tree
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Bencode\n\n")
	b.WriteString("The BitTorrent serialization format, demoing the ")
	b.WriteString("[`p/moul/x/daily/bencode`](/p/moul/x/daily/bencode/v0) library.\n\n")

	if in := parseArg(path); in != "" {
		b.WriteString("## Your input\n\n")
		if len(in) > MaxInput {
			b.WriteString(strconv.Itoa(len(in)) + " bytes. This page decodes at most ")
			b.WriteString(strconv.Itoa(MaxInput) + ".\n\n")
			b.WriteString(backLink)
			return b.String()
		}
		b.WriteString(ui.Inline(in) + "\n\n")
		v, err := bencode.Decode(in)
		if err != nil {
			b.WriteString("Rejected: " + ui.Inline(err.Error()) + "\n\n")
			b.WriteString(backLink)
			return b.String()
		}
		tree(&b, v, 0)
		b.WriteString("\nRe-encodes to " + ui.Inline(v.Encode()))
		if v.Encode() == in {
			b.WriteString(", byte for byte.\n\n")
		} else {
			b.WriteString(", which differs from the input.\n\n")
		}
		b.WriteString(backLink)
		return b.String()
	}

	b.WriteString("## The four types\n\n")
	tt := ui.NewTable("encoding", "kind", "reads as")
	for _, s := range samples {
		v, err := bencode.Decode(s)
		if err != nil {
			tt.Row("`"+s+"`", "error", err.Error())
			continue
		}
		tt.Row("`"+s+"`", v.Kind().String(), summarize(v))
	}
	b.WriteString(tt.String() + "\n")

	b.WriteString("## A torrent, decoded\n\n")
	t, err := bencode.Decode(torrent)
	if err != nil {
		b.WriteString("the sample failed to decode: " + ui.Inline(err.Error()) + "\n")
		return b.String()
	}
	tree(&b, t, 0)
	b.WriteString("\nThe `info` sub-dictionary re-encodes to ")
	info := t.Get("info")
	b.WriteString("`" + info.Encode() + "`, ")
	b.WriteString(strconv.Itoa(len(info.Encode())) + " bytes. ")
	b.WriteString("Hash those bytes and you have the infohash, which is why the ")
	b.WriteString("decoder is not allowed to tidy anything up on the way through.\n\n")

	b.WriteString("## What it refuses\n\n")
	rt := ui.NewTable("input", "why", "error")
	for _, r := range rejected {
		_, err := bencode.Decode(r.in)
		msg := "accepted"
		if err != nil {
			msg = err.Error()
		}
		rt.Row("`"+r.in+"`", r.why, msg)
	}
	b.WriteString(rt.String() + "\n")

	b.WriteString("> Every one of those parses. A decoder that accepted them ")
	b.WriteString("and re-emitted the canonical form would change the identity ")
	b.WriteString("of the document it was handed.\n\n")
	b.WriteString("Decode your own: ")
	b.WriteString("[`d3:cow3:mooe`](/r/moul/x/daily/bencodedemo/v0:d3:cow3:mooe)\n")
	return b.String()
}

// summarize describes a value in one cell, without recursing.
func summarize(v *bencode.Value) string {
	switch v.Kind() {
	case bencode.KindInt:
		return strconv.FormatInt(v.Int(), 10)
	case bencode.KindString:
		if v.Text() == "" {
			return "_(empty string)_"
		}
		return ui.Cell(v.Text())
	case bencode.KindList:
		return strconv.Itoa(v.Len()) + " item(s)"
	case bencode.KindDict:
		return strconv.Itoa(v.Len()) + " key(s): " + ui.Cell(strings.Join(v.Keys(), ", "))
	default:
		return "_(nothing)_"
	}
}

// tree writes a value as a nested markdown list. It takes the builder rather
// than returning a string: a dictionary of a few hundred entries is reachable
// inside MaxInput, and += over that many lines copies the page once per line.
func tree(b *strings.Builder, v *bencode.Value, depth int) {
	pad := strings.Repeat("  ", depth)
	switch v.Kind() {
	case bencode.KindList:
		b.WriteString(pad + "- list, " + strconv.Itoa(v.Len()) + " item(s)\n")
		for i := 0; i < v.Len(); i++ {
			tree(b, v.At(i), depth+1)
		}
	case bencode.KindDict:
		b.WriteString(pad + "- dict, " + strconv.Itoa(v.Len()) + " key(s)\n")
		for _, k := range v.Keys() {
			child := v.Get(k)
			if child.Kind() == bencode.KindList || child.Kind() == bencode.KindDict {
				b.WriteString(pad + "  - **" + ui.Inline(k) + "**:\n")
				tree(b, child, depth+2)
				continue
			}
			b.WriteString(pad + "  - **" + ui.Inline(k) + "**: " + leaf(child) + "\n")
		}
	default:
		b.WriteString(pad + "- " + leaf(v) + "\n")
	}
}

// leaf renders an int or a string as one line.
func leaf(v *bencode.Value) string {
	switch v.Kind() {
	case bencode.KindInt:
		return "int `" + strconv.FormatInt(v.Int(), 10) + "`"
	case bencode.KindString:
		if v.Text() == "" {
			return "string, empty"
		}
		return "string " + ui.Inline(v.Text())
	default:
		return "nothing"
	}
}

// parseArg takes the whole render path as the value to decode: a bencoded
// string contains colons and digits, and splitting on them would mangle it.
// Only the routing slash comes off. Trimming whitespace would eat a byte the
// caller declared the length of, so "6:hello " would arrive as a five byte
// string claiming six and be rejected for the trim rather than for itself.
func parseArg(path string) string {
	return strings.TrimPrefix(path, "/")
}

package bencodedemo

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// TestRenderRefusesOversizedInput pins the page's own limit, which is tighter
// than the library's: a Render runs under the chain's query gas meter and
// gnoweb does not bound a render argument.
func TestRenderRefusesOversizedInput(t *testing.T) {
	big := "l" + strings.Repeat("1:a", (MaxInput-2)/3) + "e"
	uassert.True(t, len(big) <= MaxInput, "the control input must be accepted")
	got := Render("/" + big)
	uassert.True(t, strings.Contains(got, "- list, "), "a legal input still decodes")

	over := "l" + strings.Repeat("1:a", MaxInput) + "e"
	got = Render("/" + over)
	uassert.True(t, strings.Contains(got, "This page decodes at most 512."),
		"an oversized input is refused by length, before decoding")
	uassert.False(t, strings.Contains(got, "- list, "), "and nothing is decoded")
}

// TestRenderEscapesCallerMarkdown pins the escaping, which a pinned example
// cannot show convincingly: the input there would have to be hostile.
func TestRenderEscapesCallerMarkdown(t *testing.T) {
	// 10 bytes, not 9: a wrong length is rejected before the decoded leaf is
	// ever rendered, and the test would then only cover the echoed heading.
	got := Render("/d3:cow10:[x](/evil)e")
	uassert.False(t, strings.Contains(got, "Rejected"), "the input must decode")
	uassert.False(t, strings.Contains(got, "[x](/evil)"), "the link must not survive")
	uassert.True(t, strings.Contains(got, "**cow**: string "), "the decoded leaf is rendered")
	uassert.Equal(t, 3, strings.Count(got, `\[x\]`), "escaped in the heading, the leaf and the re-encoding")
}

// TestRenderKeepsCallerBytes pins that the page does not trim the value it was
// handed: a trailing space is part of a six byte string, not routing noise.
func TestRenderKeepsCallerBytes(t *testing.T) {
	got := Render("/6:hello ")
	uassert.True(t, strings.Contains(got, "string hello"), "the space-bearing string decodes")
	uassert.False(t, strings.Contains(got, "Rejected"), "and is not rejected")
}

package bencodedemo

// ExampleRender pins the realm's Render output as a testable example. The
// refusal table is the library's strictness contract, so this doubles as a
// conformance test.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Bencode
	//
	// The BitTorrent serialization format, demoing the [`p/moul/x/daily/bencode`](/p/moul/x/daily/bencode/v0) library.
	//
	// ## The four types
	//
	// | encoding | kind | reads as |
	// | --- | --- | --- |
	// | `i42e` | int | 42 |
	// | `i-7e` | int | -7 |
	// | `4:spam` | string | spam |
	// | `0:` | string | _(empty string)_ |
	// | `li1ei2ei3ee` | list | 3 item(s) |
	// | `d3:cow3:moo4:spam4:eggse` | dict | 2 key(s): cow, spam |
	//
	// ## A torrent, decoded
	//
	// - dict, 2 key(s)
	//   - **announce**: string udp://tracker\.example
	//   - **info**:
	//     - dict, 3 key(s)
	//       - **length**: int `262144`
	//       - **name**: string disk\.img
	//       - **piece length**: int `16384`
	//
	// The `info` sub-dictionary re-encodes to `d6:lengthi262144e4:name8:disk.img12:piece lengthi16384ee`, 56 bytes. Hash those bytes and you have the infohash, which is why the decoder is not allowed to tidy anything up on the way through.
	//
	// ## What it refuses
	//
	// | input | why | error |
	// | --- | --- | --- |
	// | `i007e` | leading zeros in an integer | bencode: input is not canonical |
	// | `i-0e` | negative zero | bencode: input is not canonical |
	// | `03:abc` | leading zeros in a string length | bencode: input is not canonical |
	// | `d4:spam4:eggs3:cow3:mooe` | dictionary keys out of order | bencode: input is not canonical |
	// | `d3:cow3:moo3:cow3:mooe` | duplicate dictionary key | bencode: input is not canonical |
	// | `i1ei2e` | a second value after the first | bencode: trailing data after top-level value |
	//
	// > Every one of those parses. A decoder that accepted them and re-emitted the canonical form would change the identity of the document it was handed.
	//
	// Decode your own: [`d3:cow3:mooe`](/r/moul/x/daily/bencodedemo/v0:d3:cow3:mooe)
}

// ExampleRenderDecode pins the caller-supplied decode path: the tree, and the
// round trip that says the input was already canonical.
func ExampleRenderDecode() {
	print(Render("/d3:cowl1:ai7ee4:spam4:eggse"))
	// Output:
	// # Bencode
	//
	// The BitTorrent serialization format, demoing the [`p/moul/x/daily/bencode`](/p/moul/x/daily/bencode/v0) library.
	//
	// ## Your input
	//
	// d3:cowl1:ai7ee4:spam4:eggse
	//
	// - dict, 2 key(s)
	//   - **cow**:
	//     - list, 2 item(s)
	//       - string a
	//       - int `7`
	//   - **spam**: string eggs
	//
	// Re-encodes to d3:cowl1:ai7ee4:spam4:eggse, byte for byte.
	//
	// [back to the demo](/r/moul/x/daily/bencodedemo/v0)
}

// ExampleRenderReject pins what a non-canonical paste looks like.
func ExampleRenderReject() {
	print(Render("/i007e"))
	// Output:
	// # Bencode
	//
	// The BitTorrent serialization format, demoing the [`p/moul/x/daily/bencode`](/p/moul/x/daily/bencode/v0) library.
	//
	// ## Your input
	//
	// i007e
	//
	// Rejected: bencode: input is not canonical
	//
	// [back to the demo](/r/moul/x/daily/bencodedemo/v0)
}

// Package blog is a multi-author on-chain blog realm for gno.land.
//
// Any caller can Publish a post; posts are stored persistently and rendered
// newest-first. Each post records its author (the calling address) and the
// block height at which it was published.
package blog

import (
	"strconv"
	"strings"

	"chain"
	"chain/markdown"
	"chain/runtime"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
)

// selfPath is this realm's own page. A root-relative link resolves against
// the domain, not the realm, so every link back into it names it in full.
const selfPath = "/r/moul/x/daily/blog/v1"

// Post is a single blog entry. It carries no id field: the id belongs to the
// store, which hands it back on lookup and iteration.
type Post struct {
	Title  string
	Body   string
	Author address
	Height int64
}

// posts holds every published post. The store keys by seqid, so iteration is
// in publication order for any number of posts; v0 kept its own nextID plus a
// key() that zero-padded to width 12 and stopped ordering past it.
var posts = store.Named("post")

// Publish creates a new post authored by the caller and returns its id.
// It is a state-mutating exported function, so it takes `cur realm`.
func Publish(cur realm, title string, body string) int {
	if !cur.IsCurrent() {
		panic("blog: spoofed realm")
	}
	title = strings.TrimSpace(title)
	body = strings.TrimSpace(body)
	if strings.TrimSpace(markdown.StripBidiAndZeroWidth(title)) == "" {
		panic("blog: title must not be empty")
	}
	if strings.TrimSpace(markdown.StripBidiAndZeroWidth(body)) == "" {
		panic("blog: body must not be empty")
	}

	author := cur.Previous().Address()
	id := posts.Add(&Post{
		Title:  title,
		Body:   body,
		Author: author,
		Height: runtime.ChainHeight(),
	})

	chain.Emit(
		"PostPublished",
		"id", id.String(),
		"author", author.String(),
	)
	return int(id)
}

// PostCount returns the number of published posts.
func PostCount() int {
	return posts.Len()
}

// Render lists all posts newest-first at the root, or a single post's full
// text at path "/<id>". Render is NOT a crossing function.
func Render(path string) string {
	path = strings.TrimSpace(path)
	if path == "" || path == "/" {
		return renderList()
	}
	idStr := strings.TrimPrefix(path, "/")
	id, ok := store.ParseID(idStr)
	if !ok {
		return "# Not found\n\nInvalid post path: " + md.InlineCode(path) + "\n\n[← back](" + selfPath + ")\n"
	}
	v, ok := posts.Get(id)
	if !ok {
		return "# Not found\n\nNo post with id " + idStr + ".\n\n[← back](" + selfPath + ")\n"
	}
	return renderPost(v.(*Post))
}

func renderList() string {
	var b strings.Builder
	b.WriteString("# 📝 Blog\n\n")
	if posts.Len() == 0 {
		b.WriteString("_No posts yet. Be the first to `Publish`._\n")
		return b.String()
	}
	b.WriteString(strconv.Itoa(posts.Len()) + " post(s), newest first.\n\n")

	// Ids ascend with publication, so reverse iteration is newest-first.
	posts.EachReverse(func(id store.ID, v any) {
		p := v.(*Post)
		b.WriteString("## [")
		b.WriteString(ui.Inline(p.Title))
		b.WriteString("](" + selfPath + ":/")
		b.WriteString(id.String())
		b.WriteString(")\n\n")
		b.WriteString("by `")
		b.WriteString(p.Author.String())
		b.WriteString("` · height ")
		b.WriteString(strconv.FormatInt(p.Height, 10))
		b.WriteString("\n\n")
		b.WriteString(ui.Excerpt(strings.TrimSpace(p.Body), 140))
		b.WriteString("\n\n---\n\n")
	})
	return b.String()
}

func renderPost(p *Post) string {
	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(ui.Inline(p.Title))
	b.WriteString("\n\n")
	b.WriteString("by `")
	b.WriteString(p.Author.String())
	b.WriteString("` · height ")
	b.WriteString(strconv.FormatInt(p.Height, 10))
	b.WriteString("\n\n")
	// Anyone may publish, so the body is the caller's text, not this realm's
	// markdown: each line is escaped, and a blank line still breaks a paragraph.
	for i, line := range strings.Split(p.Body, "\n") {
		if i > 0 {
			b.WriteString("  \n")
		}
		b.WriteString(ui.Inline(line))
	}
	b.WriteString("\n\n---\n\n[← back to all posts](" + selfPath + ")\n")
	return b.String()
}

