package commitrevealdemo

// ExampleRender pins the realm's Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Commit–Reveal
	//
	// Bind to a choice without disclosing it, demoing the [`p/moul/x/daily/commitreveal`](/p/moul/x/daily/commitreveal/v0) library.
	//
	// ## The problem
	//
	// A transaction is public before it executes. In a sealed-bid auction or a simultaneous-move game, whoever moves last reads everyone else's move and wins for free.
	//
	// ## Phase 1 — commit
	//
	// Each player publishes only `H(value ‖ salt)`. Nothing about the move leaks, but neither can change it later.
	//
	// | player | commitment |
	// |---|---|
	// | alice | `11811a2d4eede29f…` |
	// | bob | `db066e8c917e07d5…` |
	//
	// ## Phase 2 — reveal
	//
	// Now the values and salts are published and checked against the commitments recorded earlier:
	//
	// | check | result |
	// |---|---|
	// | alice opens with `rock` | ✅ accepted |
	// | bob opens with `paper` | ✅ accepted |
	// | bob tries `scissors` instead | ❌ `commitreveal: reveal does not match the commitment` |
	// | bob claims alice's commitment | ❌ `commitreveal: reveal does not match the commitment` |
	//
	// Bob cannot switch his move after seeing Alice's, and cannot pass off her commitment as his own.
	//
	// ## Why the salt is mandatory
	//
	// Rock-paper-scissors has three possible moves. Without a salt there are exactly three possible hashes, and hashing all three breaks the scheme outright. The library refuses a salt shorter than `16` bytes rather than leaving that as advice:
	//
	// - `Commit("rock", "tooshort")` → `commitreveal: salt is shorter than MinSaltLen`
	//
	// The salt also keeps two players who pick the *same* move from publishing the same commitment:
	//
	// | same move, different salt | commitment |
	// |---|---|
	// | player 1 | `a5d84fa94157acca…` |
	// | player 2 | `ccbc5d0b7ab1e84d…` |
	//
	// ## Two details that are easy to get wrong
	//
	// - **Length-prefixed hashing.** With plain concatenation `("ab","cd…")` and `("abc","d…")` hash identically, so one commitment could be opened two different ways.
	// - **Constant-time comparison.** A short-circuiting check leaks, through timing, how many leading bytes of a guess were right — enough to rebuild a commitment byte by byte.
}

package connect4

import (
	"chain"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/store/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/md/v0"
)

// selfPath is this realm's own page. A root-relative link resolves against
// the domain, not the realm, so every link back into it names it in full.
const selfPath = "/r/moul/x/daily/connect4/v1"

const (
	cols = 7
	rows = 6
)

// cell values
const (
	empty = 0
	red   = 1 // 🔴 game creator (caller of NewGame)
	yel   = 2 // 🟡 opponent
)

// Game holds the full state of one Connect Four match.
// board is indexed board[row][col]; row 0 is the BOTTOM row.
// It carries no ID field: the id belongs to the store, which hands it back on
// lookup and iteration.
type Game struct {
	Red      address // 🔴 creator, moves first
	Yellow   address // 🟡 opponent
	Board    [rows][cols]int
	Turn     int  // whose turn: red or yel
	Winner   int  // empty until decided; red/yel = winner
	Draw     bool // true when board full with no winner
	Finished bool
}

// games assigns the game ids. v1 kept its own nextID plus an idKey() that
// zero-padded to width 12, which stopped ordering the Render list past 10^12.
var games = store.Named("game")

// NewGame creates a match between the caller (🔴) and opponent (🟡).
// Returns the new game id.
func NewGame(cur realm, opponent address) int64 {
	if !cur.IsCurrent() {
		panic("connect4: spoofed realm")
	}
	caller := cur.Previous().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if opponent.String() == "" {
		panic("opponent address is empty")
	}
	id := games.Add(&Game{
		Red:    caller,
		Yellow: opponent,
		Turn:   red,
	})
	chain.Emit("GameCreated",
		"id", id.String(),
		"red", caller.String(),
		"yellow", opponent.String(),
	)
	return int64(id)
}

func getGame(id int64) (*Game, error) {
	v, ok := games.Get(store.ID(id))
	if !ok {
		return nil, errors.New("game not found: " + strconv.FormatInt(id, 10))
	}
	return v.(*Game), nil
}

// Drop places the caller's disc into the given column (0-6).
// Enforces turn order by caller, rejects full columns, and detects
// a 4-in-a-row win or a draw.
func Drop(cur realm, gameID int64, column int) {
	if !cur.IsCurrent() {
		panic("connect4: spoofed realm")
	}
	if column < 0 || column >= cols {
		panic("column out of range (0-6)")
	}
	g, err := getGame(gameID)
	if err != nil {
		panic(err.Error())
	}
	if g.Finished {
		panic("game already finished")
	}

	caller := cur.Previous().Address()
	var mover int
	switch caller {
	case g.Red:
		mover = red
	case g.Yellow:
		mover = yel
	default:
		panic("caller is not a player in this game")
	}
	if mover != g.Turn {
		panic("not your turn")
	}

	// find lowest empty row in the column
	placed := -1
	for r := 0; r < rows; r++ {
		if g.Board[r][column] == empty {
			g.Board[r][column] = mover
			placed = r
			break
		}
	}
	if placed == -1 {
		panic("column is full")
	}

	if wins(&g.Board, placed, column, mover) {
		g.Winner = mover
		g.Finished = true
		chain.Emit("GameWon",
			"id", strconv.FormatInt(gameID, 10),
			"winner", caller.String(),
		)
	} else if full(&g.Board) {
		g.Draw = true
		g.Finished = true
		chain.Emit("GameDraw", "id", strconv.FormatInt(gameID, 10))
	} else {
		if g.Turn == red {
			g.Turn = yel
		} else {
			g.Turn = red
		}
		chain.Emit("DiscDropped",
			"id", strconv.FormatInt(gameID, 10),
			"col", strconv.Itoa(column),
			"player", caller.String(),
		)
	}

}

func full(b *[rows][cols]int) bool {
	for c := 0; c < cols; c++ {
		if b[rows-1][c] == empty {
			return false
		}
	}
	return true
}

// wins checks whether the disc just placed at (r,c) for player p completes
// a run of 4 in any of the four directions.
func wins(b *[rows][cols]int, r, c, p int) bool {
	// direction pairs: horizontal, vertical, diag /, diag \
	dirs := [4][2]int{{0, 1}, {1, 0}, {1, 1}, {1, -1}}
	for _, d := range dirs {
		count := 1
		count += run(b, r, c, d[0], d[1], p)
		count += run(b, r, c, -d[0], -d[1], p)
		if count >= 4 {
			return true
		}
	}
	return false
}

func run(b *[rows][cols]int, r, c, dr, dc, p int) int {
	n := 0
	for i := 1; i < 4; i++ {
		rr := r + dr*i
		cc := c + dc*i
		if rr < 0 || rr >= rows || cc < 0 || cc >= cols {
			break
		}
		if b[rr][cc] != p {
			break
		}
		n++
	}
	return n
}

func glyph(v int) string {
	switch v {
	case red:
		return "🔴"
	case yel:
		return "🟡"
	default:
		return "·"
	}
}

// Render draws the board with 🔴🟡· and shows whose turn / the winner.
// path "" lists all games; path "<id>" shows a single board.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path == "" {
		return renderList()
	}
	id, ok := store.ParseID(path)
	if !ok {
		return "# Connect Four\n\nInvalid game id: " + md.InlineCode(path) + "\n"
	}
	g, err := getGame(int64(id))
	if err != nil {
		return "# Connect Four\n\n" + err.Error() + "\n"
	}
	return renderGame(id, g)
}

func renderList() string {
	var sb strings.Builder
	sb.WriteString("# Connect Four\n\n")
	sb.WriteString("Two-player Connect Four on a 7×6 board. 🔴 is the game creator, 🟡 the opponent.\n\n")
	if games.Len() == 0 {
		sb.WriteString("_No games yet. Call `NewGame(opponent)` to start one._\n")
		return sb.String()
	}
	sb.WriteString("## Games\n\n")
	sb.WriteString("| ID | 🔴 Red | 🟡 Yellow | Status |\n")
	sb.WriteString("|----|--------|-----------|--------|\n")
	games.Each(func(id store.ID, v any) {
		g := v.(*Game)
		status := ""
		switch {
		case g.Winner == red:
			status = "🔴 won"
		case g.Winner == yel:
			status = "🟡 won"
		case g.Draw:
			status = "draw"
		case g.Turn == red:
			status = "🔴 to move"
		default:
			status = "🟡 to move"
		}
		sb.WriteString("| [" + id.String() + "](" + selfPath + ":" + id.String() + ") | " +
			ui.Addr(g.Red) + " | " + ui.Addr(g.Yellow) + " | " + status + " |\n")
	})
	sb.WriteString("\nOpen a game by its id (e.g. path `1`).\n")
	return sb.String()
}

func renderGame(id store.ID, g *Game) string {
	var sb strings.Builder
	sb.WriteString("# Connect Four — Game " + id.String() + "\n\n")
	sb.WriteString("- 🔴 Red: `" + g.Red.String() + "`\n")
	sb.WriteString("- 🟡 Yellow: `" + g.Yellow.String() + "`\n\n")

	// status line
	switch {
	case g.Winner == red:
		sb.WriteString("**🔴 Red wins!**\n\n")
	case g.Winner == yel:
		sb.WriteString("**🟡 Yellow wins!**\n\n")
	case g.Draw:
		sb.WriteString("**Draw — board full.**\n\n")
	case g.Turn == red:
		sb.WriteString("**Turn: 🔴 Red**\n\n")
	default:
		sb.WriteString("**Turn: 🟡 Yellow**\n\n")
	}

	// board top-down (row rows-1 at top, row 0 at bottom)
	sb.WriteString("```\n")
	for r := rows - 1; r >= 0; r-- {
		for c := 0; c < cols; c++ {
			sb.WriteString(glyph(g.Board[r][c]))
		}
		sb.WriteString("\n")
	}
	// column indices
	for c := 0; c < cols; c++ {
		sb.WriteString(strconv.Itoa(c))
	}
	sb.WriteString("\n```\n\n")

	if !g.Finished {
		sb.WriteString("Drop a disc: `Drop(" + id.String() + ", <col 0-6>)`\n")
	}
	return sb.String()
}

