// Package crondemo is a small gnoweb demo of the cron expression parser
// provided by the [p/moul/x/daily/cron](/p/moul/x/daily/cron/v0) library: the
// grammar, the next firing times of a handful of schedules, the union rule
// that governs the two day fields, and the expression that never fires.
//
// It contains no scheduling logic of its own, and no state. Every instant on
// the page is computed from the fixed anchor below rather than from
// time.Now(), which is what lets an example test pin the output: a block
// timestamp would make the page different on every call and identical to
// nothing.
package crondemo

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/cron/v0"
)

// anchor is the instant every "next" on this page is measured from: a Tuesday
// morning, deliberately mid-minute so the exclusive boundary is visible.
var anchor = time.Date(2026, time.March, 10, 9, 17, 0, 0, time.UTC)

// schedules is the worked example: one line per shape of the grammar.
var schedules = []struct {
	expr string
	what string
}{
	{"* * * * *", "every minute"},
	{"*/15 * * * *", "every quarter hour"},
	{"0 * * * *", "on the hour"},
	{"5,25,45 * * * *", "a list of minutes"},
	{"5/20 * * * *", "from minute 5, every 20"},
	{"30 8 * * 1-5", "weekday mornings"},
	{"0 12 * * sat,sun", "weekend noon"},
	{"0 0 1 jan,jul *", "twice a year"},
	{"0 0 29 2 *", "the leap day"},
}

// macros is the @shorthand table, each paired with what it expands to.
var macros = []struct {
	macro string
	same  string
}{
	{"@hourly", "0 * * * *"},
	{"@daily", "0 0 * * *"},
	{"@weekly", "0 0 * * 0"},
	{"@monthly", "0 0 1 * *"},
	{"@yearly", "0 0 1 1 *"},
}

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/") -> the full demo
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Cron expressions\n\n")
	b.WriteString("The five-field crontab grammar, parsed and answered: given a ")
	b.WriteString("schedule and an instant, when does it next fire. Demoing the ")
	b.WriteString("[`p/moul/x/daily/cron`](/p/moul/x/daily/cron/v0) library.\n\n")

	b.WriteString("## The grammar\n\n")
	gt := ui.NewTable("position", "field", "range", "names")
	gt.Row("1", "minute", "`0-59`", "")
	gt.Row("2", "hour", "`0-23`", "")
	gt.Row("3", "day of month", "`1-31`", "")
	gt.Row("4", "month", "`1-12`", "`jan`..`dec`")
	gt.Row("5", "day of week", "`0-7`", "`sun`..`sat`")
	b.WriteString(gt.String() + "\n")
	b.WriteString("Every field is a comma-separated list whose items are a value, ")
	b.WriteString("a range, a star, or any of those with a step: `5`, `5-30`, ")
	b.WriteString("`*`, `*/15`, `5-30/5`, `5/20`. In the weekday field `0` and ")
	b.WriteString("`7` are both Sunday, which is what keeps `5-7` meaning Friday ")
	b.WriteString("through Sunday instead of running backwards.\n\n")

	b.WriteString("## Next firing times\n\n")
	b.WriteString("Measured from `" + stamp(anchor) + "`, and strictly after it: ")
	b.WriteString("a schedule handed its own firing time answers with the ")
	b.WriteString("following one.\n\n")
	st := ui.NewTable("expression", "meaning", "next", "then", "and then")
	for _, sc := range schedules {
		s, err := cron.Parse(sc.expr)
		if err != nil {
			st.Row(ui.Cell(sc.expr), ui.Cell(sc.what), ui.Cell(err.Error()), "", "")
			continue
		}
		cells := []string{"never", "", ""}
		for i, t := range s.NextN(anchor, 3) {
			cells[i] = stamp(t)
		}
		st.Row("`"+sc.expr+"`", sc.what, cells[0], cells[1], cells[2])
	}
	b.WriteString(st.String() + "\n")
	b.WriteString("The last row is not a failure. `0 0 29 2 *` is a perfectly ")
	b.WriteString("well formed expression that skips three years out of four, ")
	b.WriteString("and the parser has no business rejecting it.\n\n")

	b.WriteString("## The two day fields are a union\n\n")
	b.WriteString("This is the rule a reimplementation gets wrong. When **both** ")
	b.WriteString("the day-of-month and the day-of-week field are narrowed, a ")
	b.WriteString("day matches when **either** does. `0 0 13 * 5` is the ")
	b.WriteString("classic: the 13th of the month OR any Friday, never the ")
	b.WriteString("intersection, which is why it also fires on ordinary ")
	b.WriteString("Fridays.\n\n")
	ut := ui.NewTable("expression", "day of month", "day of week", "combined", "next three")
	for _, c := range []struct {
		expr string
		dom  string
		dow  string
		rule string
	}{
		{"0 0 13 * 5", "the 13th", "Friday", "**either**"},
		{"0 0 13 * *", "the 13th", "any", "the 13th"},
		{"0 0 * * 5", "any", "Friday", "Friday"},
	} {
		s := cron.MustParse(c.expr)
		days := make([]string, 0, 3)
		for _, t := range s.NextN(anchor, 3) {
			days = append(days, stamp(t))
		}
		ut.Row("`"+c.expr+"`", c.dom, c.dow, c.rule, strings.Join(days, ", "))
	}
	b.WriteString(ut.String() + "\n")
	b.WriteString("When only one of the two is narrowed the other matches every ")
	b.WriteString("day, so the union and the intersection agree and there is ")
	b.WriteString("nothing to decide. The rule only bites on the first row.\n\n")

	b.WriteString("## Macros\n\n")
	mt := ui.NewTable("macro", "expands to", "next")
	for _, m := range macros {
		s := cron.MustParse(m.macro)
		next, ok := s.Next(anchor)
		when := "never"
		if ok {
			when = stamp(next)
		}
		mt.Row("`"+m.macro+"`", "`"+m.same+"`", when)
	}
	b.WriteString(mt.String() + "\n")
	b.WriteString("`@annually` is `@yearly` and `@midnight` is `@daily`. A ")
	b.WriteString("schedule reports the expression it was parsed from, so a ")
	b.WriteString("macro stays a macro on the way back out.\n\n")

	b.WriteString("## What a bad expression says\n\n")
	et := ui.NewTable("expression", "error")
	for _, bad := range []string{
		"* * * *",
		"60 * * * *",
		"* * * * 8",
		"* * * * 5-1",
		"*/0 * * * *",
		"@fortnightly",
	} {
		_, err := cron.Parse(bad)
		msg := "accepted"
		if err != nil {
			msg = err.Error()
		}
		et.Row("`"+bad+"`", ui.Cell(msg))
	}
	b.WriteString(et.String() + "\n")
	b.WriteString("The field is named in the message. Five fields all accept ")
	b.WriteString("numbers, so `out of range` on its own says nothing about ")
	b.WriteString("which one to go and fix.\n\n")

	b.WriteString("## Why a realm would want this\n\n")
	b.WriteString("A chain has no timer. Nothing on gno.land wakes a realm up, ")
	b.WriteString("so a schedule is not a thing that runs: it is a thing that ")
	b.WriteString("is *checked*. A realm stores the expression, and whoever ")
	b.WriteString("calls in next asks whether the due instant has passed. ")
	b.WriteString("`Next` turns a crontab line into that one comparison, and ")
	b.WriteString("`Matches` answers it for the current block without any ")
	b.WriteString("arithmetic at the call site.\n\n")
	b.WriteString("Everything here is UTC on purpose. A block timestamp carries ")
	b.WriteString("no local zone, and a schedule whose answer depended on one ")
	b.WriteString("would not be the same schedule on every validating node.\n")

	return b.String()
}

// stamp formats an instant as the page shows it: date, minute, weekday.
//
// Written out with strconv rather than reached for from a formatter because
// ufmt/v0 has no width flags, and a zero-padded minute is the whole point.
func stamp(t time.Time) string {
	return strconv.Itoa(t.Year()) + "-" + pad2(int(t.Month())) + "-" + pad2(t.Day()) +
		" " + pad2(t.Hour()) + ":" + pad2(t.Minute()) +
		" " + weekdayName(t.Weekday())
}

// pad2 renders 0..99 with a leading zero.
func pad2(v int) string {
	if v < 10 {
		return "0" + strconv.Itoa(v)
	}
	return strconv.Itoa(v)
}

// weekdayName is the three-letter form, spelled the way the grammar spells it.
func weekdayName(d time.Weekday) string {
	names := []string{"sun", "mon", "tue", "wed", "thu", "fri", "sat"}
	return names[int(d)]
}

package crondemo

// ExampleRender pins the realm Render output as a testable example.
//
// The block below is copied verbatim from what gno printed, never hand
// typed: every instant in it is computed by the library under test, so a
// change in the parser shows up here as a diff rather than as prose.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Cron expressions
	//
	// The five-field crontab grammar, parsed and answered: given a schedule and an instant, when does it next fire. Demoing the [`p/moul/x/daily/cron`](/p/moul/x/daily/cron/v0) library.
	//
	// ## The grammar
	//
	// | position | field | range | names |
	// | --- | --- | --- | --- |
	// | 1 | minute | `0-59` |  |
	// | 2 | hour | `0-23` |  |
	// | 3 | day of month | `1-31` |  |
	// | 4 | month | `1-12` | `jan`..`dec` |
	// | 5 | day of week | `0-7` | `sun`..`sat` |
	//
	// Every field is a comma-separated list whose items are a value, a range, a star, or any of those with a step: `5`, `5-30`, `*`, `*/15`, `5-30/5`, `5/20`. In the weekday field `0` and `7` are both Sunday, which is what keeps `5-7` meaning Friday through Sunday instead of running backwards.
	//
	// ## Next firing times
	//
	// Measured from `2026-03-10 09:17 tue`, and strictly after it: a schedule handed its own firing time answers with the following one.
	//
	// | expression | meaning | next | then | and then |
	// | --- | --- | --- | --- | --- |
	// | `* * * * *` | every minute | 2026-03-10 09:18 tue | 2026-03-10 09:19 tue | 2026-03-10 09:20 tue |
	// | `*/15 * * * *` | every quarter hour | 2026-03-10 09:30 tue | 2026-03-10 09:45 tue | 2026-03-10 10:00 tue |
	// | `0 * * * *` | on the hour | 2026-03-10 10:00 tue | 2026-03-10 11:00 tue | 2026-03-10 12:00 tue |
	// | `5,25,45 * * * *` | a list of minutes | 2026-03-10 09:25 tue | 2026-03-10 09:45 tue | 2026-03-10 10:05 tue |
	// | `5/20 * * * *` | from minute 5, every 20 | 2026-03-10 09:25 tue | 2026-03-10 09:45 tue | 2026-03-10 10:05 tue |
	// | `30 8 * * 1-5` | weekday mornings | 2026-03-11 08:30 wed | 2026-03-12 08:30 thu | 2026-03-13 08:30 fri |
	// | `0 12 * * sat,sun` | weekend noon | 2026-03-14 12:00 sat | 2026-03-15 12:00 sun | 2026-03-21 12:00 sat |
	// | `0 0 1 jan,jul *` | twice a year | 2026-07-01 00:00 wed | 2027-01-01 00:00 fri | 2027-07-01 00:00 thu |
	// | `0 0 29 2 *` | the leap day | 2028-02-29 00:00 tue | 2032-02-29 00:00 sun | 2036-02-29 00:00 fri |
	//
	// The last row is not a failure. `0 0 29 2 *` is a perfectly well formed expression that skips three years out of four, and the parser has no business rejecting it.
	//
	// ## The two day fields are a union
	//
	// This is the rule a reimplementation gets wrong. When **both** the day-of-month and the day-of-week field are narrowed, a day matches when **either** does. `0 0 13 * 5` is the classic: the 13th of the month OR any Friday, never the intersection, which is why it also fires on ordinary Fridays.
	//
	// | expression | day of month | day of week | combined | next three |
	// | --- | --- | --- | --- | --- |
	// | `0 0 13 * 5` | the 13th | Friday | **either** | 2026-03-13 00:00 fri, 2026-03-20 00:00 fri, 2026-03-27 00:00 fri |
	// | `0 0 13 * *` | the 13th | any | the 13th | 2026-03-13 00:00 fri, 2026-04-13 00:00 mon, 2026-05-13 00:00 wed |
	// | `0 0 * * 5` | any | Friday | Friday | 2026-03-13 00:00 fri, 2026-03-20 00:00 fri, 2026-03-27 00:00 fri |
	//
	// When only one of the two is narrowed the other matches every day, so the union and the intersection agree and there is nothing to decide. The rule only bites on the first row.
	//
	// ## Macros
	//
	// | macro | expands to | next |
	// | --- | --- | --- |
	// | `@hourly` | `0 * * * *` | 2026-03-10 10:00 tue |
	// | `@daily` | `0 0 * * *` | 2026-03-11 00:00 wed |
	// | `@weekly` | `0 0 * * 0` | 2026-03-15 00:00 sun |
	// | `@monthly` | `0 0 1 * *` | 2026-04-01 00:00 wed |
	// | `@yearly` | `0 0 1 1 *` | 2027-01-01 00:00 fri |
	//
	// `@annually` is `@yearly` and `@midnight` is `@daily`. A schedule reports the expression it was parsed from, so a macro stays a macro on the way back out.
	//
	// ## What a bad expression says
	//
	// | expression | error |
	// | --- | --- |
	// | `* * * *` | cron: want 5 fields, got 4 in "\* \* \* \*" |
	// | `60 * * * *` | cron: minute field "60": out of range 0\-59: 60 |
	// | `* * * * 8` | cron: day of week field "8": out of range 0\-7: 8 |
	// | `* * * * 5-1` | cron: day of week field "5\-1": range runs backwards: "5\-1" |
	// | `*/0 * * * *` | cron: minute field "\*/0": step must be at least 1, got 0 |
	// | `@fortnightly` | cron: unknown macro "@fortnightly" |
	//
	// The field is named in the message. Five fields all accept numbers, so `out of range` on its own says nothing about which one to go and fix.
	//
	// ## Why a realm would want this
	//
	// A chain has no timer. Nothing on gno.land wakes a realm up, so a schedule is not a thing that runs: it is a thing that is *checked*. A realm stores the expression, and whoever calls in next asks whether the due instant has passed. `Next` turns a crontab line into that one comparison, and `Matches` answers it for the current block without any arithmetic at the call site.
	//
	// Everything here is UTC on purpose. A block timestamp carries no local zone, and a schedule whose answer depended on one would not be the same schedule on every validating node.
}

// Package dijkstrademo is a small gnoweb demo of the shortest-path search
// provided by the [p/moul/x/daily/dijkstra](/p/moul/x/daily/dijkstra/v0)
// library: the cheapest route to every node, the order the search settles
// them in, and the tie-break that makes both reproducible.
//
// It contains no search logic of its own. Stateless, so Render is
// deterministic: every figure below comes from the fixed graphs declared at
// the top of this file, never from chain state, which is what lets an example
// test pin the page.
package dijkstrademo

import (
	"strconv"
	"strings"

	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/ui/v0"
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/x/daily/dijkstra/v0"
)

// link is one arc of the worked example: a small directed delivery network
// where the obvious route is the wrong one twice over.
type link struct {
	from, to string
	cost     int
}

var network = []link{
	{"depot", "north", 2},
	{"depot", "east", 4},
	{"north", "east", 1},
	{"north", "ridge", 3},
	{"east", "port", 6},
	{"ridge", "port", 3},
	{"port", "beacon", 2},
}

// The source of the worked example, and a node nothing reaches, to show that
// unreachable is an answer rather than an error.
const (
	source   = "depot"
	isolated = "quarry"
)

// fanout is the determinism example: one hub, three spokes, all at the same
// cost. Which one settles first is decided by the order they were declared
// in, never by a map.
var fanout = []string{"west", "south", "crater"}

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/") -> the full demo
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Dijkstra\n\n")
	b.WriteString("The cheapest route from one node to every other node of a ")
	b.WriteString("weighted graph, demoing the ")
	b.WriteString("[`p/moul/x/daily/dijkstra`](/p/moul/x/daily/dijkstra/v0) library.\n\n")

	g := dijkstra.New()
	for _, l := range network {
		g.AddEdge(l.from, l.to, l.cost)
	}
	g.AddNode(isolated)
	r := g.From(source)

	b.WriteString("## The network\n\n")
	b.WriteString("Arcs are one-way. ")
	b.WriteString(strconv.Itoa(g.Len()) + " nodes, " + strconv.Itoa(g.Edges()))
	b.WriteString(" arcs, searched from `" + source + "`.\n\n")
	nt := ui.NewTable("from", "to", "cost")
	for _, l := range network {
		nt.Row(ui.Cell(l.from), ui.Cell(l.to), strconv.Itoa(l.cost))
	}
	b.WriteString(nt.String() + "\n")
	b.WriteString("`" + isolated + "` is in the graph with no arcs at all.\n\n")

	b.WriteString("## Cheapest route to each node\n\n")
	rt := ui.NewTable("node", "distance", "arrives via", "route")
	for _, n := range g.Names() {
		d, ok := r.Dist(n)
		if !ok {
			rt.Row(ui.Cell(n), "unreachable", "", "")
			continue
		}
		via, hasVia := r.Via(n)
		if !hasVia {
			via = "source"
		}
		rt.Row(ui.Cell(n), strconv.Itoa(d), ui.Cell(via), route(r.Path(n)))
	}
	b.WriteString(rt.String() + "\n")
	b.WriteString("Two of those rows are the point of the algorithm. `east` is ")
	b.WriteString("reachable directly for 4, and the answer is 3, through ")
	b.WriteString("`north`. `port` is first offered at 9 by `east`, and ends at ")
	b.WriteString("8 through `ridge`, which the search only discovers two ")
	b.WriteString("settlements later.\n\n")

	b.WriteString("## The order the search settles nodes\n\n")
	b.WriteString("Always the closest node still outstanding, never the next ")
	b.WriteString("one along an arc. That is the whole difference from a ")
	b.WriteString("breadth-first walk, and it is why a cheap long way round ")
	b.WriteString("still wins.\n\n")
	ot := ui.NewTable("step", "settles", "at distance")
	for i, n := range r.Order() {
		d, _ := r.Dist(n)
		ot.Row(strconv.Itoa(i+1), ui.Cell(n), strconv.Itoa(d))
	}
	b.WriteString(ot.String() + "\n")
	b.WriteString(strconv.Itoa(r.Reachable()) + " of " + strconv.Itoa(g.Len()))
	b.WriteString(" nodes were reached, in " + strconv.Itoa(r.Relaxations()))
	b.WriteString(" improvements. An arc that is looked at and rejected costs ")
	b.WriteString("a comparison; only an improvement costs a write.\n\n")

	b.WriteString("## Ties, and why a realm should care\n\n")
	b.WriteString("Three spokes, all 5 away from the hub. Nothing in the ")
	b.WriteString("distances separates them, so something else has to, and ")
	b.WriteString("that something must not be map iteration order: a `Render` ")
	b.WriteString("that reshuffled between validating nodes would be a ")
	b.WriteString("consensus bug, not a cosmetic one.\n\n")
	tt := ui.NewTable("declared", "settle order")
	tt.Row(names(fanout), route(settleFanout(fanout)))
	reversed := reverse(fanout)
	tt.Row(names(reversed), route(settleFanout(reversed)))
	b.WriteString(tt.String() + "\n")
	b.WriteString("The tie resolves to the order the graph was built in, and ")
	b.WriteString("nothing else. Build it the same way twice and you get the ")
	b.WriteString("same page twice.\n\n")

	b.WriteString("## What it will not do\n\n")
	b.WriteString("A negative arc panics at `AddEdge`, where the caller can ")
	b.WriteString("still fix it. Accepting one would not return an error ")
	b.WriteString("later, it would return a confident wrong answer: the ")
	b.WriteString("search never revisits a settled node, so a negative arc ")
	b.WriteString("pointing back at one is simply never seen.\n\n")
	lt := ui.NewTable("limit", "value", "why")
	lt.Row("`MaxNodes`", strconv.Itoa(dijkstra.MaxNodes),
		"the frontier holds at most one entry per node, so this bounds memory")
	lt.Row("`MaxEdges`", strconv.Itoa(dijkstra.MaxEdges),
		"arcs bound the work, not the memory")
	lt.Row("negative arc", "panics", "the algorithm's precondition, not a simplification")
	lt.Row("self-loop", "panics", "it can never shorten a path, so it is a caller mistake")
	b.WriteString(lt.String() + "\n")
	b.WriteString("Both caps are small on purpose. This is a routing table ")
	b.WriteString("for a realm, not a road atlas, and a caller that can state ")
	b.WriteString("the worst case up front can price the gas before it sends ")
	b.WriteString("the transaction.\n")

	return b.String()
}

// route joins a path with an arrow. Each node name is escaped on its own and
// the separator never is: running the whole joined string through the
// escaper would turn the arrows into a literal backslash soup, which is the
// bug this spelling exists to avoid.
func route(path []string) string {
	if len(path) == 0 {
		return ""
	}
	cells := make([]string, len(path))
	for i, n := range path {
		cells[i] = ui.Cell(n)
	}
	return strings.Join(cells, " -> ")
}

// names renders a declaration order as a comma-separated list, escaped the
// same way.
func names(in []string) string {
	cells := make([]string, len(in))
	for i, n := range in {
		cells[i] = ui.Cell(n)
	}
	return strings.Join(cells, ", ")
}

// settleFanout builds the hub-and-spoke graph with the spokes declared in the
// given order and returns the order the search settles them in.
func settleFanout(spokes []string) []string {
	g := dijkstra.New()
	g.AddNode("hub")
	for _, s := range spokes {
		g.AddNode(s)
	}
	for _, s := range spokes {
		g.AddEdge("hub", s, 5)
	}
	return g.From("hub").Order()
}

// reverse copies a slice back to front. Written out rather than imported
// because there is no sensible shared home for three lines of it.
func reverse(in []string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		out[len(in)-1-i] = s
	}
	return out
}

package dijkstrademo

